INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q026', 'shared-gk-bank', 'History', 2, 25, 'What was the significance of the Indus Valley Civilization''s urban planning, as seen at sites like Mohenjo-daro and Harappa?', 'The Indus Valley Civilization is notable for its advanced urban planning, including a grid-pattern layout of streets, sophisticated drainage and sewage systems, standardized brick sizes, and structures like the Great Bath at Mohenjo-daro — features considered remarkably advanced for a Bronze Age civilization and suggesting a high degree of centralized planning and civic organization.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q027', 'shared-gk-bank', 'History', 2, 26, 'What script did the Indus Valley Civilization use, and has it been deciphered?', 'The Indus Valley Civilization used a pictographic script found on seals and artifacts, but despite many attempts, the script has not yet been definitively deciphered by scholars, making it difficult to directly understand their language, literature, or detailed historical records.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q028', 'shared-gk-bank', 'History', 2, 27, 'Who founded the Mauryan Empire, and in which year approximately?', 'The Mauryan Empire was founded by Chandragupta Maurya around 321 BCE, after he overthrew the Nanda dynasty with the guidance of his advisor Chanakya (Kautilya), going on to build one of the largest empires in ancient Indian history.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q029', 'shared-gk-bank', 'History', 2, 28, 'What transformed Emperor Ashoka''s approach to governance after the Kalinga War?', 'After witnessing the massive bloodshed and suffering caused by the Kalinga War (around 261 BCE), Ashoka renounced further military conquest and embraced Buddhism, adopting a policy of "Dhamma" (moral governance) emphasizing non-violence, religious tolerance, and the welfare of his subjects, which he propagated through edicts inscribed on pillars and rocks across his empire.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q030', 'shared-gk-bank', 'History', 2, 29, 'What is the "Arthashastra," and who is traditionally credited with writing it?', 'The Arthashastra is an ancient Indian treatise on statecraft, economic policy, and military strategy, traditionally attributed to Chanakya (also known as Kautilya or Vishnugupta), who served as an advisor to Chandragupta Maurya. It covers topics ranging from taxation and diplomacy to law and espionage.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q031', 'shared-gk-bank', 'History', 2, 30, 'Which Gupta ruler is often associated with the "Golden Age" of ancient India, and why?', 'Chandragupta II (also known as Vikramaditya) is often associated with the peak of the Gupta "Golden Age," a period marked by significant achievements in science, mathematics, astronomy, art, and literature, along with relative political stability and economic prosperity across northern India.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q032', 'shared-gk-bank', 'History', 2, 31, 'What were the contributions of the mathematician-astronomer Aryabhata during the Gupta period?', 'Aryabhata made significant contributions including an early approximation of the value of pi, concepts related to place-value notation and zero, an explanation of solar and lunar eclipses based on scientific reasoning, and the proposal that the Earth rotates on its axis — ideas documented in his work, the Aryabhatiya.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q033', 'shared-gk-bank', 'History', 2, 32, 'Who was Fa-Hien, and why is his account significant for historians of ancient India?', 'Fa-Hien was a Chinese Buddhist monk and traveler who visited India during the reign of Chandragupta II, documenting his observations of Indian society, Buddhism, and governance in his travel records — providing valuable independent, contemporary evidence that historians use to reconstruct life during the Gupta period.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q034', 'shared-gk-bank', 'History', 2, 33, 'Who established the Delhi Sultanate, and what was his original profession/background?', 'The Delhi Sultanate was established by Qutb-ud-din Aibak in 1206, a former slave (Mamluk) who rose through military ranks to become a general and eventually a ruler, founding what is known as the Slave (Mamluk) Dynasty — the first of several dynasties that would rule the Delhi Sultanate.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q035', 'shared-gk-bank', 'History', 2, 34, 'What economic reforms did Alauddin Khilji introduce, and what was their purpose?', 'Alauddin Khilji introduced market control reforms that fixed the prices of essential commodities like grain, cloth, and horses, and established a strict administrative system to enforce these controls. The primary purpose was to maintain a strong, well-supplied army at low cost by ensuring soldiers and the general population had access to affordable goods.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q036', 'shared-gk-bank', 'History', 2, 35, 'Who founded the Vijayanagara Empire, and in which region was it located?', 'The Vijayanagara Empire was founded in 1336 by brothers Harihara I and Bukka Raya, in the Deccan region of South India, with its capital at Vijayanagara (near present-day Hampi, Karnataka) — it became one of the most powerful and prosperous South Indian empires, known for its patronage of art, architecture, and trade.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q037', 'shared-gk-bank', 'History', 2, 36, 'What was the significance of the Bahmani Sultanate in Deccan history?', 'The Bahmani Sultanate, founded in 1347, was a prominent Muslim kingdom in the Deccan region that served as a major rival power to the Vijayanagara Empire, and later fragmented into five smaller successor states (the Deccan Sultanates), significantly shaping the political landscape of the Deccan for centuries.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q038', 'shared-gk-bank', 'History', 2, 37, 'What was the outcome of the First Battle of Panipat (1526), and who were the key figures?', 'The First Battle of Panipat (1526) was fought between Babur (founder of the Mughal dynasty) and Ibrahim Lodi (the last ruler of the Delhi Sultanate''s Lodi dynasty). Babur''s decisive victory, aided by the effective use of artillery and gunpowder, established Mughal rule in India.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q039', 'shared-gk-bank', 'History', 2, 38, 'What was "Din-i-Ilahi," introduced by Akbar?', 'Din-i-Ilahi was a syncretic religious and ethical system introduced by Emperor Akbar, blending elements from various religions including Islam, Hinduism, Christianity, and Zoroastrianism. It was intended to promote religious tolerance and unity among his diverse subjects, though it attracted relatively few actual followers.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q040', 'shared-gk-bank', 'History', 2, 39, 'What is the Mansabdari system, introduced during Akbar''s reign?', 'The Mansabdari system was an administrative and military framework under which officials (mansabdars) were assigned a rank (mansab) that determined their status, salary, and the number of troops they were required to maintain for the empire, helping Akbar organize and control a vast and diverse bureaucracy and army.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q041', 'shared-gk-bank', 'History', 2, 40, 'Which Mughal emperor commissioned the construction of the Taj Mahal, and in whose memory?', 'Emperor Shah Jahan commissioned the Taj Mahal in Agra as a mausoleum in memory of his wife, Mumtaz Mahal, who died during childbirth — it is widely regarded as one of the finest examples of Mughal architecture and is a UNESCO World Heritage Site.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q042', 'shared-gk-bank', 'History', 2, 41, 'What were some of Aurangzeb''s notable policies that are often cited as contributing to Mughal decline?', 'Aurangzeb''s prolonged military campaigns in the Deccan, reimposition of the jizya tax on non-Muslims, and generally less tolerant religious policies compared to earlier Mughal emperors are often cited by historians as factors that strained the empire''s resources and alienated various groups, contributing to the eventual weakening of Mughal central authority after his death.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q043', 'shared-gk-bank', 'History', 2, 42, 'Who was Shivaji, and what was his significance in Indian history?', 'Shivaji Bhonsle was the founder of the Maratha Empire in the 17th century, known for his military strategy, administrative reforms, and establishment of "Hindavi Swarajya" (self-rule), successfully challenging Mughal authority in western India and laying the foundation for the later rise of the Maratha Confederacy as a major power.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q044', 'shared-gk-bank', 'History', 2, 43, 'What was the Bhakti movement, and what was its broad social significance?', 'The Bhakti movement was a devotional religious movement that emphasized a direct, personal relationship with God through intense love and devotion, often expressed through poetry and song in regional languages, rather than through elaborate rituals or caste-based practices. It had broad social significance in challenging caste hierarchies and promoting a more inclusive, accessible form of spirituality across various regions and communities in India.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q045', 'shared-gk-bank', 'History', 2, 44, 'What was the immediate trigger for the Revolt of 1857?', 'The immediate trigger was the introduction of the new Enfield rifle cartridges, which were widely believed to be greased with cow and pig fat — offensive to both Hindu and Muslim sepoys (soldiers) for religious reasons — sparking a mutiny that quickly escalated into a broader rebellion against British East India Company rule across parts of northern and central India.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q046', 'shared-gk-bank', 'History', 2, 45, 'What was the "Partition of Bengal" in 1905, and what movement did it provoke?', 'The Partition of Bengal in 1905, orchestrated by Lord Curzon, divided the Bengal Presidency along communal lines, officially for administrative convenience but widely seen as a "divide and rule" strategy. It provoked the Swadeshi Movement, which promoted the boycott of British goods and the use of indigenous (swadeshi) products as a form of economic and political protest.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q047', 'shared-gk-bank', 'History', 2, 46, 'What was the Dandi March (Salt Satyagraha) of 1930?', 'The Dandi March was a 24-day, roughly 390-kilometre march led by Mahatma Gandhi from Sabarmati Ashram to the coastal village of Dandi, where he and his followers produced salt from seawater in defiance of the British salt tax and monopoly — a powerful act of civil disobedience that galvanized nationwide participation in the independence movement.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q048', 'shared-gk-bank', 'History', 2, 47, 'What was the Khilafat Movement, and how did it relate to the Indian freedom struggle?', 'The Khilafat Movement (1919-1924) was a pan-Islamic protest by Indian Muslims in support of the Ottoman Caliphate after World War I. Mahatma Gandhi linked it with the broader Non-Cooperation Movement against British rule, aiming to build Hindu-Muslim unity in the fight for Indian independence, though the alliance eventually weakened after the Khilafat issue lost relevance following the abolition of the Caliphate in Turkey.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q049', 'shared-gk-bank', 'History', 2, 48, 'What were the key causes of the French Revolution (1789)?', 'Key causes included widespread social inequality under the rigid estate system, severe financial crisis and high taxation burdening the common people, food scarcity and rising bread prices, and the influence of Enlightenment ideas questioning absolute monarchy and advocating liberty, equality, and fraternity — all converging to spark the revolution that overthrew the French monarchy.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q050', 'shared-gk-bank', 'History', 2, 49, 'What triggered the start of World War I in 1914?', 'World War I was triggered by the assassination of Archduke Franz Ferdinand of Austria-Hungary by a Serbian nationalist in Sarajevo in June 1914, which set off a chain reaction of alliance-based declarations of war among major European powers, rapidly escalating a regional crisis into a global conflict.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q051', 'shared-gk-bank', 'Indian Polity', 0, 50, 'What is the Preamble of the Indian Constitution, and what key values does it enshrine?', 'The Preamble is an introductory statement that declares India to be a Sovereign, Socialist, Secular, Democratic Republic, and sets out the objectives of securing Justice, Liberty, Equality, and Fraternity for all citizens — serving as a guide to interpreting the spirit and purpose behind the Constitution''s provisions.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q052', 'shared-gk-bank', 'Indian Polity', 0, 51, 'What is the difference between Fundamental Rights and Directive Principles of State Policy (DPSPs)?', 'Fundamental Rights (Part III) are justiciable, meaning citizens can directly approach courts to enforce them if violated. DPSPs (Part IV) are non-justiciable guidelines directing the state toward establishing social and economic democracy, but they cannot be enforced through courts — they function more as policy aspirations than legally enforceable rights.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q053', 'shared-gk-bank', 'Indian Polity', 0, 52, 'Under which Article is the Right to Constitutional Remedies guaranteed, and why is it significant?', 'The Right to Constitutional Remedies is guaranteed under Article 32, allowing citizens to directly approach the Supreme Court if their Fundamental Rights are violated. Dr. B.R. Ambedkar called it the "heart and soul" of the Constitution because it makes Fundamental Rights meaningfully enforceable rather than merely declaratory.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q054', 'shared-gk-bank', 'Indian Polity', 0, 53, 'What is a "Money Bill," and which House has primary authority over it?', 'A Money Bill deals specifically with matters like taxation, government borrowing, or expenditure from the Consolidated Fund of India. Under Article 110, it can only be introduced in the Lok Sabha, and the Rajya Sabha has limited power over it — it can only recommend changes, which the Lok Sabha may accept or reject.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q055', 'shared-gk-bank', 'Indian Polity', 0, 54, 'What is the difference between the Lok Sabha and the Rajya Sabha in terms of composition?', 'The Lok Sabha (House of the People) consists of members directly elected by citizens through general elections, representing the population at large. The Rajya Sabha (Council of States) consists mostly of members elected by state legislative assemblies, representing the states, along with some members nominated by the President for their expertise in fields like art, literature, or science.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q056', 'shared-gk-bank', 'Indian Polity', 0, 55, 'What is a "No-Confidence Motion," and what happens if it succeeds?', 'A No-Confidence Motion is a parliamentary motion that can be moved only in the Lok Sabha, testing whether the government still commands majority support. If it succeeds (is passed), the Council of Ministers, including the Prime Minister, is constitutionally required to resign.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q057', 'shared-gk-bank', 'Indian Polity', 0, 56, 'What is the role of the Speaker of the Lok Sabha?', 'The Speaker presides over Lok Sabha sessions, maintains order and decorum during debates, decides procedural matters including whether a bill is a Money Bill, and has a casting vote in case of a tie. The Speaker is elected by the members of the Lok Sabha from among themselves.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q058', 'shared-gk-bank', 'Indian Polity', 0, 57, 'What is the "Anti-Defection Law," and under which Schedule of the Constitution is it contained?', 'The Anti-Defection Law, contained in the Tenth Schedule of the Constitution (added by the 52nd Amendment, 1985), lays down the process by which a legislator can be disqualified for defecting from their political party — such as voluntarily giving up party membership or voting against party directions on key issues without permission.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q059', 'shared-gk-bank', 'Indian Polity', 0, 58, 'What is the role of the Finance Commission of India?', 'The Finance Commission, constituted every five years under Article 280, recommends how tax revenues collected by the Union government should be distributed between the Centre and the states, and among the states themselves, aiming to address fiscal imbalances and support equitable development across the country.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q060', 'shared-gk-bank', 'Indian Polity', 0, 59, 'What is the Union Public Service Commission (UPSC) responsible for?', 'The UPSC is a constitutional body responsible for conducting examinations and recruitment for All India Services (like IAS, IPS) and various central government civil services positions, as well as advising the government on matters relating to recruitment and personnel management for these services.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q061', 'shared-gk-bank', 'Indian Polity', 0, 60, 'What is the significance of the 42nd Amendment to the Constitution?', 'The 42nd Amendment (1976), often called the "Mini Constitution," made extensive changes including adding the words "Socialist" and "Secular" to the Preamble, introducing Fundamental Duties (Article 51A), and curtailing judicial review power over constitutional amendments — several of these changes were later modified by subsequent amendments and court judgments.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q062', 'shared-gk-bank', 'Indian Polity', 0, 61, 'What is "judicial review," and which body primarily exercises it in India?', 'Judicial review is the power of courts to examine the constitutionality of legislative and executive actions, and to strike down those found to be in violation of the Constitution. In India, this power is primarily exercised by the Supreme Court and High Courts.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q063', 'shared-gk-bank', 'Indian Polity', 0, 62, 'What is the difference between "original jurisdiction" and "appellate jurisdiction" of the Supreme Court?', 'Original jurisdiction refers to cases that can be filed directly in the Supreme Court as the first court of instance, such as disputes between the Centre and states, or Fundamental Rights violations under Article 32. Appellate jurisdiction refers to the Supreme Court''s power to hear appeals against judgments of lower courts, such as High Courts.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q064', 'shared-gk-bank', 'Indian Polity', 0, 63, 'What is a "writ," and name two types of writs the Supreme Court/High Courts can issue.', 'A writ is a formal written order issued by a court directing a person or authority to act or refrain from acting in a certain way, used to enforce Fundamental Rights. Examples include Habeas Corpus (produce a detained person before the court) and Mandamus (direct a public authority to perform its legal duty).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q065', 'shared-gk-bank', 'Indian Polity', 0, 64, 'What is the role of the Attorney General of India?', 'The Attorney General is the Indian government''s chief legal advisor and its primary representative in cases before the Supreme Court. Appointed by the President, the Attorney General advises the government on legal matters and performs legal duties assigned by the Constitution or the President.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q066', 'shared-gk-bank', 'Indian Polity', 0, 65, 'Is India a purely federal or purely unitary state, and how is it typically described?', 'India is typically described as "quasi-federal" or having a "federal structure with unitary bias" — it has a division of powers between the Centre and states as in a federal system, but also features strong unitary elements, such as a single Constitution, a single citizenship, and emergency provisions that can centralize power, unlike a purely federal system.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q067', 'shared-gk-bank', 'Indian Polity', 0, 66, 'What is the significance of the basic structure doctrine, established in the Kesavananda Bharati case (1973)?', 'The basic structure doctrine holds that while Parliament has wide powers to amend the Constitution under Article 368, it cannot alter or destroy its "basic structure" — core features like democracy, secularism, judicial review, and federalism — ensuring that fundamental constitutional principles remain protected from being overridden even by a constitutional amendment.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q068', 'shared-gk-bank', 'Indian Polity', 0, 67, 'What is the procedure for impeachment of the President of India?', 'The President can be impeached for "violation of the Constitution" through a process that can be initiated in either House of Parliament, requiring a resolution supported by at least one-fourth of the members of that House, followed by a 14-day notice, and ultimately needing to pass by a two-thirds majority in both Houses.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q069', 'shared-gk-bank', 'Indian Polity', 0, 68, 'What is the role of the National Commission for Scheduled Castes?', 'The National Commission for Scheduled Castes is a constitutional body (under Article 338) responsible for monitoring the implementation of safeguards for Scheduled Castes, investigating complaints of rights violations, and advising the government on policy matters affecting the socio-economic development of Scheduled Castes.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q070', 'shared-gk-bank', 'Indian Polity', 0, 69, 'What is the basic difference between a "Bill" and an "Act" in the lawmaking process?', 'A Bill is a draft legislative proposal that is introduced and debated in Parliament (or a state legislature). Once it is passed by both Houses and receives the assent of the President (or Governor, for state bills), it becomes an "Act" — a law that is legally binding and enforceable.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q071', 'shared-gk-bank', 'Indian Polity', 0, 70, 'What is "Zero Hour" in the Indian Parliament?', 'Zero Hour is an informal parliamentary device (not defined in the rules) that begins immediately after Question Hour, typically around noon, during which Members of Parliament can raise urgent public importance matters without prior notice, though the government is not obligated to respond immediately.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q072', 'shared-gk-bank', 'Indian Polity', 0, 71, 'What is "Question Hour" in the Indian Parliament?', 'Question Hour is typically the first hour of a parliamentary sitting, during which Members of Parliament ask questions to ministers regarding the administration and policies of their respective ministries, holding the government accountable through both oral and written responses.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q073', 'shared-gk-bank', 'Indian Polity', 0, 72, 'What is the "Collegium system" for judicial appointments in India?', 'The Collegium system is a mechanism, evolved through Supreme Court judgments rather than being explicitly defined in the Constitution, under which the Chief Justice of India and a group of senior-most Supreme Court judges recommend appointments and transfers of judges to the Supreme Court and High Courts, with the government''s role largely limited to processing these recommendations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q074', 'shared-gk-bank', 'Indian Polity', 0, 73, 'What is "President''s Rule," and under which Article is it imposed?', 'President''s Rule, imposed under Article 356, allows the President to take over the administration of a state (dismissing the state government and often suspending or dissolving the state legislature) if the constitutional machinery in that state is reported to have broken down and the state cannot be governed according to constitutional provisions.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q075', 'shared-gk-bank', 'Indian Polity', 0, 74, 'What was the significance of the 73rd and 74th Constitutional Amendments?', 'The 73rd Amendment (1992) gave constitutional status to Panchayati Raj institutions (rural local self-government), while the 74th Amendment (1992) did the same for urban local bodies like Municipalities and Municipal Corporations — both aimed at strengthening grassroots democracy and decentralizing governance down to the local level.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q076', 'shared-gk-bank', 'Geography', 1, 75, 'What are the three major physiographic divisions of India, broadly speaking?', 'India''s landmass is broadly divided into three major physiographic divisions: the Himalayan mountain system in the north, the Indo-Gangetic Plains in the middle, and the Peninsular Plateau (including the Deccan Plateau) in the south, each with distinct geological origins and landforms.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q077', 'shared-gk-bank', 'Geography', 1, 76, 'What is the significance of the Western Ghats, and what UNESCO status do they hold?', 'The Western Ghats are a mountain range running along India''s western coast, recognized as one of the world''s biodiversity hotspots due to their exceptional variety of flora and fauna, including many endemic species. They are designated a UNESCO World Heritage Site for their ecological significance.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q078', 'shared-gk-bank', 'Geography', 1, 77, 'Which is the largest state in India by area?', 'Rajasthan is the largest state in India by area, known for the Thar Desert, the Aravalli Range, and a rich cultural and historical heritage including numerous forts and palaces.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q079', 'shared-gk-bank', 'Geography', 1, 78, 'Which is the smallest state in India by area?', 'Goa is the smallest state in India by area, located on the western coast and known for its beaches, Portuguese colonial heritage, and tourism industry.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q080', 'shared-gk-bank', 'Geography', 1, 79, 'What is a "plateau," and name India''s largest plateau.', 'A plateau is an elevated flat-topped landform that rises sharply above the surrounding area on at least one side. The Deccan Plateau, covering much of peninsular India, is India''s largest plateau, formed primarily from ancient volcanic basalt rock (the Deccan Traps).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q081', 'shared-gk-bank', 'Geography', 1, 80, 'What is the Deccan Plateau, and which rivers flow through/around it?', 'The Deccan Plateau is a large triangular plateau covering most of southern India, bounded by the Western Ghats and Eastern Ghats. Major rivers flowing through it include the Godavari, Krishna, and Kaveri (Cauvery), which generally flow eastward into the Bay of Bengal.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q082', 'shared-gk-bank', 'Geography', 1, 81, 'What is the significance of the Thar Desert, and in which state is it primarily located?', 'The Thar Desert, primarily located in Rajasthan (extending into parts of Gujarat, Punjab, and Haryana), is one of the most densely populated deserts in the world, known for its arid climate, sand dunes, and unique ecosystem adapted to extreme heat and low rainfall.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q083', 'shared-gk-bank', 'Geography', 1, 82, 'What is a "monsoon," and which two monsoon systems affect India?', 'A monsoon is a seasonal reversal of wind patterns that brings significant rainfall to a region. India is affected by the Southwest Monsoon (June to September), which brings the bulk of the country''s annual rainfall from the Arabian Sea and Bay of Bengal, and the Northeast Monsoon (October to December), which brings rainfall mainly to the southeastern coast, particularly Tamil Nadu.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q084', 'shared-gk-bank', 'Geography', 1, 83, 'What is the capital of Madhya Pradesh?', 'Bhopal is the capital of Madhya Pradesh, often referred to as the "City of Lakes" due to its numerous natural and artificial lakes.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q085', 'shared-gk-bank', 'Geography', 1, 84, 'What is the capital of Karnataka?', 'Bengaluru (formerly Bangalore) is the capital of Karnataka, widely known as India''s leading technology and startup hub, often called the "Silicon Valley of India."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q086', 'shared-gk-bank', 'Geography', 1, 85, 'What is the southernmost point of mainland India, and what is it called?', 'Kanyakumari, located in Tamil Nadu, is the southernmost point of mainland India, notable as the meeting point of the Arabian Sea, the Bay of Bengal, and the Indian Ocean.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q087', 'shared-gk-bank', 'Geography', 1, 86, 'What is the significance of the Sundarbans, and which two countries share it?', 'The Sundarbans is the world''s largest mangrove forest, formed at the delta of the Ganga, Brahmaputra, and Meghna rivers, shared between India (West Bengal) and Bangladesh. It is a UNESCO World Heritage Site and home to the Royal Bengal Tiger.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q088', 'shared-gk-bank', 'Geography', 1, 87, 'Which river is known as the "Sorrow of Bihar," and why?', 'The Kosi River is known as the "Sorrow of Bihar" due to its tendency to frequently change course and cause devastating floods in the region, resulting in significant loss of life, property, and agricultural land over the years.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q089', 'shared-gk-bank', 'Geography', 1, 88, 'Where are the Andaman and Nicobar Islands located, and which body of water surrounds them?', 'The Andaman and Nicobar Islands are a Union Territory of India located in the Bay of Bengal, situated between the Indian mainland and Southeast Asia, known for their rich marine biodiversity and strategic maritime location.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q090', 'shared-gk-bank', 'Geography', 1, 89, 'In which country''s territory does the summit of Mount Everest lie?', 'The summit of Mount Everest lies on the border between Nepal and the Tibet Autonomous Region of China, making it accessible for climbing expeditions from both the Nepali (south) and Tibetan (north) sides.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q091', 'shared-gk-bank', 'Geography', 1, 90, 'What is the Prime Meridian, and which city does it pass through?', 'The Prime Meridian is the imaginary line of 0 degrees longitude from which all other longitudes are measured, both east and west. It passes through Greenwich, London, and serves as the reference point for Greenwich Mean Time (GMT) and international time zone calculations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q092', 'shared-gk-bank', 'Geography', 1, 91, 'What is a "river delta," and name the delta formed by the Ganga and Brahmaputra rivers.', 'A river delta is a landform created at the mouth of a river where it deposits sediment as it slows down and meets a larger body of water, often forming a fan-like or triangular shape. The Ganga and Brahmaputra rivers together form the Sundarbans Delta, the largest river delta in the world, which empties into the Bay of Bengal.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q093', 'shared-gk-bank', 'Geography', 1, 92, 'What is the significance of the Vindhya and Satpura ranges in Indian geography?', 'The Vindhya and Satpura ranges are two roughly parallel mountain ranges in central India that are often considered a traditional dividing line between North India and South India (Peninsular India), with the Narmada River flowing in the rift valley between them.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q094', 'shared-gk-bank', 'Geography', 1, 93, 'Which is the most populous Indian state, and what is its capital?', 'Uttar Pradesh is the most populous Indian state, with Lucknow as its capital — it is also one of the most politically significant states due to its large number of parliamentary seats.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q095', 'shared-gk-bank', 'Geography', 1, 94, 'What are the "Deccan Traps," and how were they formed?', 'The Deccan Traps are a large igneous plateau formed by extensive volcanic eruptions that occurred roughly 66 million years ago, releasing massive amounts of basaltic lava that solidified into the layered rock formations now covering much of the Deccan Plateau in western and central India.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q096', 'shared-gk-bank', 'Geography', 1, 95, 'Which is the longest river in the world, and on which continent is it located?', 'The Nile River is generally considered the longest river in the world (though the Amazon River is a close rival in some measurements), located in Africa, flowing through multiple countries including Egypt, Sudan, and Uganda before emptying into the Mediterranean Sea.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q097', 'shared-gk-bank', 'Geography', 1, 96, 'What is the capital of Rajasthan, and what is the state widely known for?', 'Jaipur, often called the "Pink City," is the capital of Rajasthan. The state is widely known for its desert landscape (the Thar Desert), historic forts and palaces, and vibrant cultural heritage, making it one of India''s most popular tourist destinations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q098', 'shared-gk-bank', 'Economy', 3, 97, 'What is the Goods and Services Tax (GST), and when was it implemented in India?', 'GST is a single, comprehensive indirect tax levied on the supply of goods and services across India, replacing a complex web of earlier indirect taxes like VAT, excise duty, and service tax. It was implemented on July 1, 2017, under the principle of "One Nation, One Tax," and is administered jointly by the central and state governments through the GST Council.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q099', 'shared-gk-bank', 'Economy', 3, 98, 'What are the different tax slabs typically used under India''s GST structure?', 'India''s GST structure uses multiple tax slabs — commonly 0%, 5%, 12%, 18%, and 28% — with different goods and services taxed at different rates depending on whether they are considered essential, standard, or luxury/sin items; essential items like fresh food are often exempted or taxed at 0%.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q100', 'shared-gk-bank', 'Economy', 3, 99, 'What is the difference between "direct tax" and "indirect tax"? Give one example of each.', 'A direct tax is paid directly by the individual or entity on whom it is levied and cannot be shifted to someone else — e.g., income tax. An indirect tax is initially paid by one party (like a seller) but is ultimately passed on to another party (the consumer) through the price of goods or services — e.g., GST.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q101', 'shared-gk-bank', 'Economy', 3, 100, 'What is NITI Aayog, and what replaced it?', 'NITI Aayog (National Institution for Transforming India) is the government''s premier policy think tank, established in 2015 to replace the Planning Commission. Unlike the Planning Commission, which allocated funds to states through Five-Year Plans, NITI Aayog focuses on cooperative federalism, policy advice, and strategic/long-term planning without direct fund allocation powers.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q102', 'shared-gk-bank', 'Economy', 3, 101, 'What were the "Five-Year Plans" in India, and when did this planning model end?', 'The Five-Year Plans were centralized economic planning documents that set targets and allocated resources for India''s economic development over five-year periods, modeled partly on the Soviet planning system, starting in 1951. The system ended after the Twelfth Five-Year Plan (2012-2017), being replaced by NITI Aayog''s more flexible, non-binding policy frameworks.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q103', 'shared-gk-bank', 'Economy', 3, 102, 'What is "fiscal deficit," and how is it calculated?', 'Fiscal deficit is the difference between the government''s total expenditure and its total revenue (excluding borrowings) in a financial year. It represents the amount the government needs to borrow to meet its spending commitments, and is usually expressed as a percentage of GDP to gauge the scale of government borrowing relative to the size of the economy.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q104', 'shared-gk-bank', 'Economy', 3, 103, 'What is the "Union Budget," and who presents it in India?', 'The Union Budget is the annual financial statement of the Government of India''s estimated receipts and expenditures for the upcoming financial year, presented in Parliament by the Finance Minister, typically on February 1st, outlining tax proposals, spending allocations, and fiscal targets for the year ahead.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q105', 'shared-gk-bank', 'Economy', 3, 104, 'What does "revenue deficit" mean, and how does it differ from "fiscal deficit"?', 'Revenue deficit is the excess of the government''s revenue expenditure (day-to-day operational spending) over its revenue receipts (tax and non-tax income), excluding capital transactions. Fiscal deficit is broader — it is the total gap between all expenditure (revenue plus capital) and all receipts excluding borrowings — so revenue deficit is effectively a subset of the overall fiscal deficit.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q106', 'shared-gk-bank', 'Economy', 3, 105, 'What is "FDI" (Foreign Direct Investment), and why do countries like India encourage it?', 'FDI refers to an investment made by a foreign entity to acquire a lasting interest in, or significant control over, a business in another country — such as building a factory or acquiring a stake in a local company. Countries encourage FDI because it brings in capital, technology, management expertise, and job creation that might not otherwise be available domestically.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q107', 'shared-gk-bank', 'Economy', 3, 106, 'What is the difference between "FDI" and "FPI" (Foreign Portfolio Investment)?', 'FDI involves a long-term, controlling stake in a business (such as building operations or acquiring significant ownership), while FPI involves buying financial assets like stocks and bonds in a foreign market purely for investment returns, without seeking control or management influence over the underlying companies. FPI is generally more liquid and volatile than FDI.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q108', 'shared-gk-bank', 'Economy', 3, 107, 'What is a "Special Economic Zone (SEZ)" in India?', 'An SEZ is a geographically delineated area within India that is treated as a foreign territory for trade and tariff purposes, offering tax incentives, simplified regulations, and infrastructure support to businesses operating within it, primarily to boost exports, attract investment, and generate employment.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q109', 'shared-gk-bank', 'Economy', 3, 108, 'What does "per capita income" measure, and why is it a useful (but limited) economic indicator?', 'Per capita income measures the average income earned per person in a country over a specific period, calculated by dividing the national income by the total population. It is useful for comparing living standards across countries or over time, but limited because it doesn''t reflect income distribution — a high average can mask significant inequality between rich and poor.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q110', 'shared-gk-bank', 'Economy', 3, 109, 'What is "inflation," and what are its two broad types based on cause?', 'Inflation is a sustained increase in the general price level of goods and services over time, reducing the purchasing power of money. Its two broad types are demand-pull inflation (caused by demand for goods outpacing supply) and cost-push inflation (caused by rising production costs, like wages or raw materials, pushing up prices).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q111', 'shared-gk-bank', 'Economy', 3, 110, 'What is the role of the "Finance Commission" in India''s fiscal federalism?', 'The Finance Commission is a constitutional body appointed every five years under Article 280 to recommend how tax revenues collected by the central government should be distributed between the Centre and the states, and among the states themselves, aiming to ensure fiscal balance and address regional disparities.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q112', 'shared-gk-bank', 'Economy', 3, 111, 'What is "disguised unemployment," and in which sector of the Indian economy is it most commonly found?', 'Disguised unemployment occurs when more people are employed in a job than are actually needed to perform it efficiently, so removing some workers would not reduce total output. It is most commonly found in India''s agricultural sector, where family labor is often spread across a farm beyond what is productively required.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q113', 'shared-gk-bank', 'Economy', 3, 112, 'What does "balance of payments" record, and what are its two main components?', 'The balance of payments is a systematic record of all economic transactions between a country''s residents and the rest of the world over a given period. Its two main components are the current account (trade in goods, services, and income flows) and the capital account (financial transactions involving assets and liabilities, like investments and loans).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q114', 'shared-gk-bank', 'Economy', 3, 113, 'What is "GDP growth rate," and how does it differ from GDP itself?', 'GDP is the total monetary value of goods and services produced in a country during a specific period, while the GDP growth rate measures the percentage change in GDP from one period to the next (usually year-over-year or quarter-over-quarter), indicating whether and how fast the economy is expanding or contracting.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q115', 'shared-gk-bank', 'Economy', 3, 114, 'What is "stagflation," and why is it considered particularly difficult for policymakers to address?', 'Stagflation is an unusual economic condition combining stagnant economic growth, high unemployment, and high inflation simultaneously. It is difficult to address because conventional tools to fight inflation (raising interest rates) tend to further slow growth and raise unemployment, while tools to boost growth (lowering interest rates) tend to worsen inflation — creating a policy trade-off with no easy solution.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q116', 'shared-gk-bank', 'Economy', 3, 115, 'What is the purpose of "subsidies" in the Indian economy, and name one major example.', 'Subsidies are financial assistance provided by the government to reduce the cost of certain goods or services for consumers or producers, typically to make essential items more affordable or to support a strategic sector. A major example in India is the fertilizer subsidy, which keeps fertilizer prices low for farmers to support agricultural productivity.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q117', 'shared-gk-bank', 'Economy', 3, 116, 'What does "ease of doing business" measure, and why does India''s ranking matter?', '"Ease of doing business" refers to a set of indicators (historically tracked by the World Bank) measuring how simple or complex it is to start and operate a business in a country — covering factors like registering a business, obtaining permits, and enforcing contracts. A better ranking signals a more business-friendly regulatory environment, which can help attract both domestic and foreign investment.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q118', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 117, 'What is the "G20," and what is India''s significance within it?', 'The G20 (Group of Twenty) is an intergovernmental forum of the world''s major economies, representing around 85% of global GDP, that coordinates on international economic and financial issues. India held the G20 presidency in 2023, hosting the main summit in New Delhi and using the platform to push priorities like sustainable development, digital public infrastructure, and the inclusion of the African Union as a permanent G20 member.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q119', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 118, 'What is BRICS, and which countries originally formed it?', 'BRICS is an intergovernmental grouping of major emerging economies, originally comprising Brazil, Russia, India, China, and South Africa, aimed at promoting cooperation on economic, political, and developmental issues among member nations and offering an alternative voice to Western-led institutions in global governance.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q120', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 119, 'What is SAARC, and what is its primary goal?', 'SAARC (South Asian Association for Regional Cooperation) is a regional intergovernmental organization comprising South Asian countries, including India, Pakistan, Bangladesh, Sri Lanka, Nepal, Bhutan, Maldives, and Afghanistan, established to promote economic and regional integration, as well as cooperation on social, cultural, and security matters among member states.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q121', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 120, 'What is the Quadrilateral Security Dialogue (the "Quad"), and which four countries are part of it?', 'The Quad is a strategic security and diplomatic dialogue involving India, the United States, Japan, and Australia, focused on promoting a free, open, and secure Indo-Pacific region, cooperating on issues including maritime security, infrastructure, and emerging technologies.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q122', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 121, 'What is the Digital India programme, and what is its core objective?', 'Digital India is a flagship Government of India initiative launched in 2015 aimed at transforming India into a digitally empowered society and knowledge economy, by improving digital infrastructure, delivering government services electronically, and promoting digital literacy across the country.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q123', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 122, 'What is the Ayushman Bharat scheme, and what does it provide?', 'Ayushman Bharat is a national health protection scheme launched by the Government of India that provides health insurance coverage (up to a specified amount per family per year) for secondary and tertiary hospitalization to economically vulnerable families, aiming to reduce the financial burden of healthcare expenses on poorer households.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q124', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 123, 'What is the Swachh Bharat Abhiyan, and when was it launched?', 'The Swachh Bharat Abhiyan (Clean India Mission) is a nationwide sanitation and cleanliness campaign launched on October 2, 2014, aiming to eliminate open defecation, improve solid waste management, and promote overall hygiene and cleanliness across urban and rural India.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q125', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 124, 'What is the purpose of the United Nations Security Council (UNSC), and how many permanent members does it have?', 'The UNSC is the UN body primarily responsible for maintaining international peace and security, with the power to authorize peacekeeping operations, sanctions, and in some cases military action. It has five permanent members with veto power — the United States, United Kingdom, France, Russia, and China — along with ten non-permanent members elected for two-year terms.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q126', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 125, 'What is the World Health Organization (WHO), and what is its primary role?', 'The WHO is a specialized agency of the United Nations responsible for international public health, coordinating global responses to disease outbreaks, setting health standards and guidelines, and working with member countries to strengthen health systems and improve health outcomes worldwide.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q127', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 126, 'What is the Paris Agreement, and what is its central goal?', 'The Paris Agreement is an international treaty on climate change, adopted in 2015, in which signatory countries commit to efforts to limit global temperature rise this century to well below 2 degrees Celsius above pre-industrial levels, with an aspirational target of 1.5 degrees Celsius, through nationally determined contributions to reduce greenhouse gas emissions.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q128', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 127, 'What is the Pradhan Mantri Awas Yojana (PMAY), and what is its goal?', 'PMAY is a government housing scheme aimed at providing affordable housing to the urban and rural poor in India, offering interest subsidies on home loans and direct financial assistance for house construction, with the broader goal of achieving "Housing for All."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q129', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 128, 'What is the Jal Jeevan Mission, and what does it aim to achieve?', 'The Jal Jeevan Mission is a Government of India initiative launched in 2019 aiming to provide functional household tap water connections to every rural household in India, ensuring access to safe and adequate drinking water for all.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q130', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 129, 'What is the International Solar Alliance (ISA), and what role has India played in it?', 'The ISA is an international coalition of countries aimed at promoting solar energy adoption and reducing dependence on fossil fuels, particularly among sun-rich nations. India co-founded the alliance alongside France in 2015 and hosts its headquarters in Gurugram, reflecting India''s leadership role in global renewable energy cooperation.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q131', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 130, 'What is the Atal Innovation Mission (AIM), and what does it promote?', 'The Atal Innovation Mission is a flagship initiative under NITI Aayog aimed at promoting a culture of innovation and entrepreneurship across India, including setting up Atal Tinkering Labs in schools to encourage problem-solving and innovation skills among young students.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q132', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 131, 'What is the significance of India''s "Make in India" initiative?', 'Make in India is a government initiative launched in 2014 aimed at encouraging both domestic and foreign companies to manufacture products within India, with the goal of boosting the manufacturing sector''s contribution to GDP, creating jobs, and reducing reliance on imports.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q133', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 132, 'What is the Production Linked Incentive (PLI) scheme, and what is its purpose?', 'The PLI scheme offers financial incentives to companies based on incremental sales of products manufactured in India, aiming to boost domestic manufacturing capacity, attract large investments in key sectors (like electronics, pharmaceuticals, and textiles), and improve India''s position in global supply chains.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q134', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 133, 'What is the significance of the term "Amrit Kaal" used by the Government of India?', '"Amrit Kaal" refers to the 25-year period leading up to India''s 100th year of independence in 2047, used by the government as a framing for long-term national development goals and policy planning aimed at transforming India into a developed economy by that milestone.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q135', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 134, 'What is the One District One Product (ODOP) initiative?', 'ODOP is a government initiative aimed at identifying and promoting one unique product from each district of India — often a traditional craft, agricultural product, or local specialty — to boost local economies, generate employment, and preserve traditional skills and industries.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q136', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 135, 'What is the significance of the National Logistics Policy, launched in 2022?', 'The National Logistics Policy aims to reduce the cost of logistics in India (historically a higher percentage of GDP compared to many developed nations) by improving infrastructure coordination, digitization of logistics processes, and streamlining regulatory processes to make Indian goods more competitive in both domestic and international markets.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q137', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 136, 'What is UNESCO, and what is one of its key functions relevant to India?', 'UNESCO (United Nations Educational, Scientific and Cultural Organization) is a UN specialized agency promoting international cooperation in education, science, culture, and communication. One key function relevant to India is designating and helping preserve World Heritage Sites — India has numerous UNESCO World Heritage Sites, including cultural and natural sites like the Taj Mahal and Kaziranga National Park.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q138', 'shared-gk-bank', 'Science & Technology', 5, 137, 'What was "Chandrayaan-1," and what was its major scientific contribution?', 'Chandrayaan-1 was India''s first lunar probe, launched by ISRO in 2008. Its major scientific contribution was helping confirm the presence of water molecules on the Moon''s surface, a significant discovery that reshaped understanding of lunar composition and potential future resource utilization.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q139', 'shared-gk-bank', 'Science & Technology', 5, 138, 'What was the Mars Orbiter Mission (Mangalyaan), and what made it historically significant?', 'Mangalyaan was India''s first interplanetary mission, launched by ISRO in 2013 to study Mars'' atmosphere and surface. It was historically significant because it made India the first country to successfully reach Mars orbit on its very first attempt, and did so at a remarkably low cost compared to similar missions by other space agencies.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q140', 'shared-gk-bank', 'Science & Technology', 5, 139, 'What is "Gaganyaan," and what is its primary objective?', 'Gaganyaan is ISRO''s planned human spaceflight programme, aiming to send Indian astronauts into low Earth orbit aboard an indigenously developed spacecraft, which would make India only the fourth country (after the US, Russia, and China) to independently launch humans into space.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q141', 'shared-gk-bank', 'Science & Technology', 5, 140, 'What is the Polar Satellite Launch Vehicle (PSLV), and what is it primarily used for?', 'The PSLV is one of ISRO''s most reliable and frequently used launch vehicles, primarily designed to place satellites into polar and sun-synchronous orbits. It has also been used for a wide range of missions, including launching satellites for other countries, making it a key contributor to ISRO''s commercial launch services.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q142', 'shared-gk-bank', 'Science & Technology', 5, 141, 'What is "DRDO," and what is its primary role?', 'DRDO (Defence Research and Development Organisation) is India''s premier agency for military research and development, responsible for designing and developing advanced defense technologies, including missiles, radar systems, aircraft systems, and other equipment for the Indian armed forces.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q143', 'shared-gk-bank', 'Science & Technology', 5, 142, 'What is "Agni" in the context of Indian defense technology?', 'Agni is a series of indigenously developed medium- to intercontinental-range ballistic missiles developed by DRDO, forming a key part of India''s strategic missile defense capability, with different variants (Agni-I through Agni-V and beyond) offering progressively longer ranges.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q144', 'shared-gk-bank', 'Science & Technology', 5, 143, 'What is "BrahMos," and what makes it notable?', 'BrahMos is a supersonic cruise missile jointly developed by India and Russia, named after the Brahmaputra and Moskva rivers. It is notable for being one of the fastest cruise missiles in the world, capable of being launched from land, sea, air, and submarine platforms.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q145', 'shared-gk-bank', 'Science & Technology', 5, 144, 'What is the Aadhaar system, and what is its primary technological function?', 'Aadhaar is a 12-digit unique identification number issued by the Unique Identification Authority of India (UIDAI) to Indian residents, based on their biometric and demographic data. It serves as a foundational digital identity system used to verify identity for accessing government services, banking, and other services, underpinning much of India''s digital public infrastructure.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q146', 'shared-gk-bank', 'Science & Technology', 5, 145, 'What is "artificial intelligence (AI)," in simple terms?', 'Artificial intelligence refers to computer systems designed to perform tasks that typically require human intelligence, such as understanding language, recognizing patterns, making decisions, or learning from data, by using algorithms and large datasets to simulate aspects of human cognitive function.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q147', 'shared-gk-bank', 'Science & Technology', 5, 146, 'What is the difference between "hardware" and "software" in computing?', 'Hardware refers to the physical, tangible components of a computer system, such as the processor, memory, and storage devices. Software refers to the set of instructions, programs, and data that tell the hardware what tasks to perform, and cannot be physically touched — it exists as code stored on hardware.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q148', 'shared-gk-bank', 'Science & Technology', 5, 147, 'What is "cloud computing," in simple terms?', 'Cloud computing is the delivery of computing services — such as storage, processing power, and software — over the internet ("the cloud") rather than relying on local physical servers or personal devices, allowing users to access and scale resources on demand without owning the underlying infrastructure.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q149', 'shared-gk-bank', 'Science & Technology', 5, 148, 'What is the difference between "renewable" and "non-renewable" energy sources? Give one example of each.', 'Renewable energy sources are naturally replenished over short timescales and don''t get depleted with use, such as solar energy (from sunlight). Non-renewable energy sources exist in finite quantities and take millions of years to form naturally, such as coal (a fossil fuel), meaning their use depletes a limited supply.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q150', 'shared-gk-bank', 'Science & Technology', 5, 149, 'What is "photosynthesis," and what does it primarily produce?', 'Photosynthesis is the process by which green plants, algae, and some bacteria convert light energy (usually sunlight), water, and carbon dioxide into glucose (a form of chemical energy) and oxygen, which is released as a byproduct — forming the foundation of most food chains on Earth.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q151', 'shared-gk-bank', 'Science & Technology', 5, 150, 'What is the difference between "mitosis" and "meiosis" in cell division?', 'Mitosis is a type of cell division that produces two genetically identical daughter cells with the same number of chromosomes as the parent cell, used for growth and repair. Meiosis produces four genetically distinct daughter cells with half the chromosome number, used specifically for producing reproductive cells (sperm and eggs) to maintain chromosome number across generations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q152', 'shared-gk-bank', 'Science & Technology', 5, 151, 'What is the periodic table, and who is credited with its early development?', 'The periodic table is a tabular arrangement of chemical elements organized by increasing atomic number, grouped by similar chemical properties into rows (periods) and columns (groups). Dmitri Mendeleev is widely credited with developing an early, influential version of the periodic table in 1869, notably predicting the existence and properties of then-undiscovered elements based on gaps in his arrangement.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q153', 'shared-gk-bank', 'Science & Technology', 5, 152, 'What is the function of the human liver?', 'The liver performs numerous vital functions, including detoxifying harmful substances in the blood, producing bile to aid in fat digestion, storing glycogen (energy reserves), and synthesizing important proteins, making it one of the body''s most metabolically active organs.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q154', 'shared-gk-bank', 'Science & Technology', 5, 153, 'What is "vaccination," and how does it generally work to protect against disease?', 'Vaccination involves introducing a weakened, inactivated, or partial form of a pathogen (or genetic instructions to produce part of it) into the body, training the immune system to recognize and produce antibodies against that specific pathogen, so that it can respond quickly and effectively if exposed to the real, dangerous version later.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q155', 'shared-gk-bank', 'Science & Technology', 5, 154, 'What is the difference between a satellite in "low Earth orbit (LEO)" versus "geostationary orbit (GEO)"?', 'A satellite in low Earth orbit (LEO) orbits relatively close to Earth (a few hundred to about 2,000 km altitude) and completes an orbit in about 90 minutes, commonly used for earth observation and constellations like internet satellites. A geostationary orbit (GEO) satellite orbits at about 36,000 km altitude and matches Earth''s rotation, appearing to stay fixed over one point on the equator — commonly used for communication and weather satellites.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q156', 'shared-gk-bank', 'Science & Technology', 5, 155, 'What is "UPI" built on top of, in terms of underlying digital infrastructure?', 'UPI (Unified Payments Interface) is built on India''s broader digital public infrastructure stack, leveraging Aadhaar-based identity verification and bank account linkages to enable instant, interoperable payments between any two bank accounts using a mobile app, without needing to share sensitive bank details directly.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q157', 'shared-gk-bank', 'Science & Technology', 5, 156, 'What is "e-waste," and why is its management an important environmental concern?', 'E-waste refers to discarded electronic devices and equipment, such as old phones, computers, and appliances. Its management is an important environmental concern because e-waste often contains hazardous materials (like lead and mercury) that can contaminate soil and water if disposed of improperly, while also containing valuable recoverable materials if recycled responsibly.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q158', 'shared-gk-bank', 'Science & Technology', 5, 157, 'What is the significance of India''s National Supercomputing Mission?', 'The National Supercomputing Mission aims to boost India''s computing capabilities by establishing a network of high-performance supercomputing facilities across academic and research institutions, supporting advanced research in fields like weather forecasting, scientific simulation, and data-intensive computing that require massive processing power.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q159', 'shared-gk-bank', 'Sports', 6, 158, 'What is the significance of the 2028 Los Angeles Olympics regarding cricket?', 'Cricket is set to return to the Olympic programme at the 2028 Los Angeles Olympics (in the T20 format) after over a century''s absence from the Games, marking a major milestone for the sport''s global visibility and potential growth, including in markets where cricket has historically had limited following.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q160', 'shared-gk-bank', 'Sports', 6, 159, 'What is the Ranji Trophy, and what level of cricket does it represent in India?', 'The Ranji Trophy is India''s premier domestic first-class cricket tournament, contested by teams representing different states and regions. It serves as a key pathway for identifying and developing cricket talent that can progress to representing India at the international level.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q161', 'shared-gk-bank', 'Sports', 6, 160, 'What is the significance of the "Olympic Charter" regarding the Olympic motto?', 'The Olympic motto, "Citius, Altius, Fortius" (Latin for "Faster, Higher, Stronger"), was officially extended in 2021 to "Citius, Altius, Fortius – Communiter" (adding "Together"), reflecting the Olympic movement''s emphasis on solidarity and collective human achievement alongside individual excellence.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q162', 'shared-gk-bank', 'Sports', 6, 161, 'What are the Asian Games, and how often are they held?', 'The Asian Games are a continental multi-sport event held every four years among athletes from across Asia, organized by the Olympic Council of Asia, serving as one of the largest and most prestigious multi-sport competitions in the world after the Olympics.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q163', 'shared-gk-bank', 'Sports', 6, 162, 'What is the Khel Ratna Award, and what does it recognize?', 'The Major Dhyan Chand Khel Ratna Award is India''s highest sporting honor, recognizing the most spectacular and outstanding performance by a sportsperson over a period of four years, across any recognized sport, awarded by the Government of India.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q164', 'shared-gk-bank', 'Sports', 6, 163, 'What is the Arjuna Award, and how does it differ from the Khel Ratna?', 'The Arjuna Award recognizes consistent outstanding performance by a sportsperson over a four-year period in a specific sport, similar to but distinct from the Khel Ratna, which is considered a higher honor reserved for truly exceptional, standout performances; many athletes receive the Arjuna Award before later being considered for the Khel Ratna.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q165', 'shared-gk-bank', 'Sports', 6, 164, 'Who is Neeraj Chopra, and what historic achievement is he known for?', 'Neeraj Chopra is an Indian javelin thrower who won the gold medal in the men''s javelin throw at the 2020 Tokyo Olympics, becoming the first Indian to win an Olympic gold medal in track and field (athletics), and one of independent India''s few individual Olympic gold medalists overall.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q166', 'shared-gk-bank', 'Sports', 6, 165, 'What is the significance of the badminton player P.V. Sindhu''s Olympic record?', 'P.V. Sindhu is an Indian badminton player who won a silver medal at the 2016 Rio Olympics and a bronze medal at the 2020 Tokyo Olympics, making her the first Indian woman to win two individual Olympic medals.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q167', 'shared-gk-bank', 'Sports', 6, 166, 'What is the FIFA World Cup, and how often is it held?', 'The FIFA World Cup is the premier international men''s football (soccer) tournament, contested by national teams and held every four years, organized by FIFA (Fédération Internationale de Football Association), widely regarded as the most prestigious trophy in the sport.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q168', 'shared-gk-bank', 'Sports', 6, 167, 'What is a "hat-trick" in cricket, and what does it signify?', 'A hat-trick in cricket occurs when a bowler takes three wickets on three consecutive deliveries (balls), which can span across different overs but must be consecutive balls bowled by the same bowler — considered a rare and notable individual bowling achievement.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q169', 'shared-gk-bank', 'Sports', 6, 168, 'What is the significance of the term "grand slam" in tennis?', 'In tennis, the term "Grand Slam" refers collectively to the four most prestigious annual tournaments — the Australian Open, the French Open (Roland Garros), Wimbledon, and the US Open. Winning all four in a single calendar year is called a "Calendar Grand Slam," an extremely rare feat.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q170', 'shared-gk-bank', 'Sports', 6, 169, 'What is the Commonwealth Games, and who is eligible to participate?', 'The Commonwealth Games is a multi-sport event held every four years among athletes from the Commonwealth of Nations — a group of countries, mostly former British territories, with historical ties to the United Kingdom — fostering sporting competition and cultural exchange among member nations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q171', 'shared-gk-bank', 'Sports', 6, 170, 'What is the difference between "Test cricket," "One Day International (ODI)," and "T20" formats?', 'Test cricket is played over up to five days with no limit on overs per innings, considered the traditional and most comprehensive format. ODI cricket is limited to 50 overs per side in a single day. T20 cricket is limited to 20 overs per side, designed to be a fast-paced, shorter format completed in a few hours.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q172', 'shared-gk-bank', 'Sports', 6, 171, 'What is the significance of Milkha Singh in Indian sports history?', 'Milkha Singh, nicknamed "The Flying Sikh," was a legendary Indian track and field sprinter renowned for his performances in the 400m event during the 1950s-60s, including narrowly missing an Olympic medal in the 1960 Rome Olympics, and remains one of India''s most celebrated athletes despite that near-miss.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q173', 'shared-gk-bank', 'Sports', 6, 172, 'What is the Davis Cup, and what sport is it associated with?', 'The Davis Cup is the premier international team competition in men''s tennis, contested annually between national teams from different countries, often described as the "World Cup of Tennis."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q174', 'shared-gk-bank', 'Sports', 6, 173, 'What does "FIDE" stand for, and what sport does it govern?', 'FIDE stands for Fédération Internationale des Échecs (International Chess Federation), the governing body for international chess competitions, responsible for organizing world championships and maintaining official chess player rankings globally.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q175', 'shared-gk-bank', 'Sports', 6, 174, 'What is the significance of Viswanathan Anand in Indian chess?', 'Viswanathan Anand is an Indian chess grandmaster widely regarded as one of the greatest chess players in history, having won the World Chess Championship multiple times (in different formats) between 2000 and 2012, and is credited with significantly popularizing chess in India.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q176', 'shared-gk-bank', 'Sports', 6, 175, 'What is the Indian Premier League (IPL), and what format of cricket does it feature?', 'The IPL is a professional Twenty20 (T20) cricket league in India featuring franchise teams representing different cities, founded in 2008, known for attracting top international and domestic cricketing talent and for being one of the most financially significant sports leagues in the world.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q177', 'shared-gk-bank', 'Sports', 6, 176, 'What is the significance of the term "century" in cricket batting statistics?', 'A century in cricket refers to a batsman scoring 100 or more runs in a single innings, widely regarded as a significant individual batting milestone and a key measure of a batsman''s form and contribution to the team''s total.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q178', 'shared-gk-bank', 'Sports', 6, 177, 'What is the Paralympic Games, and how does it relate to the Olympic Games?', 'The Paralympic Games is a major international multi-sport event for athletes with physical, sensory, and intellectual disabilities, held shortly after the Olympic Games in the same host city, organized by the International Paralympic Committee, celebrating elite athletic performance among para-athletes.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q179', 'shared-gk-bank', 'Sports', 6, 178, 'What is the significance of Abhinav Bindra in Indian Olympic history?', 'Abhinav Bindra is an Indian shooter who won the gold medal in the men''s 10m air rifle event at the 2008 Beijing Olympics, making him the first Indian to win an individual Olympic gold medal, a landmark moment in India''s Olympic history.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q180', 'shared-gk-bank', 'Awards & Honours', 7, 179, 'What are the "Padma Awards," and what are their three categories (in descending order of prestige)?', 'The Padma Awards are India''s second-highest civilian honors (after the Bharat Ratna), given for distinguished and exceptional service in any field. In descending order of prestige, the three categories are Padma Vibhushan, Padma Bhushan, and Padma Shri.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q181', 'shared-gk-bank', 'Awards & Honours', 7, 180, 'What is the Jnanpith Award, and what field does it recognize?', 'The Jnanpith Award is India''s highest literary honor, given annually to an author for their outstanding contribution to Indian literature, and can be awarded to writers working in any of the languages recognized under the Indian Constitution''s Eighth Schedule.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q182', 'shared-gk-bank', 'Awards & Honours', 7, 181, 'What is the Pulitzer Prize, and in which country is it awarded?', 'The Pulitzer Prize is a prestigious American award recognizing excellence in journalism, literature, and musical composition, administered by Columbia University in the United States, awarded annually across numerous categories.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q183', 'shared-gk-bank', 'Awards & Honours', 7, 182, 'What is the Ramon Magsaysay Award, and what is it often referred to as?', 'The Ramon Magsaysay Award is an annual award established to recognize individuals or organizations in Asia for their greatness of spirit in service to others, named after a former Philippine president. It is often referred to as "Asia''s Nobel Prize" due to its prestige within the region.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q184', 'shared-gk-bank', 'Awards & Honours', 7, 183, 'What is the Academy Award (Oscar), and which organization presents it?', 'The Academy Award, popularly known as the Oscar, is a prestigious annual award recognizing excellence in cinematic achievements across various categories such as Best Picture, Best Director, and Best Actor/Actress, presented by the Academy of Motion Picture Arts and Sciences in the United States.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q185', 'shared-gk-bank', 'Awards & Honours', 7, 184, 'What is the Param Vir Chakra, and what does it recognize?', 'The Param Vir Chakra is India''s highest military decoration, awarded for the highest degree of valor or self-sacrifice displayed in the presence of the enemy, whether on land, at sea, or in the air, and can be awarded posthumously.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q186', 'shared-gk-bank', 'Awards & Honours', 7, 185, 'What is the Ashoka Chakra, and how does it relate to the Param Vir Chakra?', 'The Ashoka Chakra is India''s highest peacetime gallantry award, recognizing the most conspicuous bravery or acts of self-sacrifice in situations other than direct conflict with an enemy (such as during internal security operations or disaster situations). It is considered the peacetime equivalent of the wartime Param Vir Chakra.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q187', 'shared-gk-bank', 'Awards & Honours', 7, 186, 'What is the Dronacharya Award, and whom is it given to?', 'The Dronacharya Award is given by the Government of India to outstanding coaches who have contributed significantly to successfully training sportspersons or teams to achieve notable performances in national and international sporting events, recognizing excellence in coaching rather than direct athletic performance.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q188', 'shared-gk-bank', 'Awards & Honours', 7, 187, 'What is the Booker Prize, and what type of literary work is it awarded for?', 'The Booker Prize is a prestigious British literary award given annually for the best single work of sustained fiction, originally written in English and published in the UK or Ireland; its International counterpart recognizes fiction translated into English from other languages.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q189', 'shared-gk-bank', 'Awards & Honours', 7, 188, 'What is the Grammy Award, and what field does it primarily recognize?', 'The Grammy Award is a prestigious American award recognizing outstanding achievements in the music industry, presented annually by the Recording Academy across numerous categories spanning different genres, performances, and production achievements.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q190', 'shared-gk-bank', 'Awards & Honours', 7, 189, 'What is the Padma Shri, and who is generally eligible to receive it?', 'The Padma Shri is the fourth-highest civilian award in India, recognized for distinguished contribution in fields such as art, literature, education, sports, medicine, social work, and public affairs; it is open to any Indian citizen regardless of profession, race, or gender, without restriction to government or public figures.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q191', 'shared-gk-bank', 'Awards & Honours', 7, 190, 'What is the Sahitya Akademi Award, and how does it differ from the Jnanpith Award?', 'The Sahitya Akademi Award is an annual literary honor given by the Sahitya Akademi (National Academy of Letters) for an outstanding literary work published in a specific language during a given year. Unlike the Jnanpith Award, which recognizes a writer''s overall lifetime body of work, the Sahitya Akademi Award typically honors one specific book.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q192', 'shared-gk-bank', 'Awards & Honours', 7, 191, 'What is the Kirti Chakra, and where does it rank among India''s gallantry awards?', 'The Kirti Chakra is India''s second-highest peacetime gallantry award, ranking just below the Ashoka Chakra, awarded for conspicuous gallantry displayed otherwise than in the face of the enemy.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q193', 'shared-gk-bank', 'Awards & Honours', 7, 192, 'What is the Templeton Prize, and what field of achievement does it typically honor?', 'The Templeton Prize is an international award recognizing individuals who have made exceptional contributions affirming life''s spiritual dimension, often awarded to scientists, philosophers, or religious leaders whose work explores the intersection of science, philosophy, and spirituality.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q194', 'shared-gk-bank', 'Awards & Honours', 7, 193, 'What is the Rajiv Gandhi Khel Ratna Award''s original name, and when was it renamed?', 'India''s highest sporting honor was originally named the Rajiv Gandhi Khel Ratna Award; it was renamed the Major Dhyan Chand Khel Ratna Award in 2021, in honor of the legendary Indian hockey player Major Dhyan Chand.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q195', 'shared-gk-bank', 'Awards & Honours', 7, 194, 'What is the Nehru Award for International Understanding, and what does it recognize?', 'The Nehru Award for International Understanding is an Indian award given to individuals (regardless of nationality) for outstanding contributions toward promoting international understanding, goodwill, and friendship among peoples of the world.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q196', 'shared-gk-bank', 'Awards & Honours', 7, 195, 'What is the Shanti Swarup Bhatnagar Prize, and what field does it recognize?', 'The Shanti Swarup Bhatnagar Prize is India''s most prestigious award for science and technology, given annually to Indian scientists under the age of 45 for notable and outstanding research across various scientific disciplines, administered by the Council of Scientific and Industrial Research (CSIR).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q197', 'shared-gk-bank', 'Awards & Honours', 7, 196, 'What is the Fields Medal, and what field does it recognize?', 'The Fields Medal is one of the most prestigious international awards in mathematics, given every four years to mathematicians under the age of 40 for outstanding contributions to the field, often described as the "Nobel Prize of Mathematics" since no Nobel Prize exists for mathematics.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q198', 'shared-gk-bank', 'Awards & Honours', 7, 197, 'What is the Tyagraja Award, and what field does it honor?', 'The Tyagraja Award recognizes excellence in Carnatic (South Indian classical) music, named after the renowned composer-saint Tyagaraja, honoring musicians who have made significant contributions to preserving and advancing this classical music tradition.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q199', 'shared-gk-bank', 'Awards & Honours', 7, 198, 'What is the Indira Gandhi Peace Prize, and what does it recognize?', 'The Indira Gandhi Prize for Peace, Disarmament and Development is an Indian award given annually to individuals or organizations for contributions toward promoting international peace, disarmament, and development, named in memory of former Prime Minister Indira Gandhi.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q200', 'shared-gk-bank', 'Awards & Honours', 7, 199, 'What is the Bharatiya Jnanpith''s relationship to the broader recognition of regional Indian languages?', 'The Jnanpith Award (administered by the Bharatiya Jnanpith organization) plays a significant role in recognizing literary excellence across India''s many regional languages, having honored writers across numerous languages listed in the Constitution''s Eighth Schedule, helping bring national recognition to literary traditions that might otherwise remain confined to a single linguistic region.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q061', 'railway-exam-bank', 'General Awareness', 0, 60, 'What is the headquarters of Northern Railway zone?', 'Northern Railway''s headquarters is at New Delhi; it is one of the busiest zones, covering parts of Delhi, Haryana, Punjab, Himachal Pradesh, Uttar Pradesh, Rajasthan, and Jammu & Kashmir.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q062', 'railway-exam-bank', 'General Awareness', 0, 61, 'Which city serves as the headquarters of Southern Railway?', 'Southern Railway''s headquarters is located in Chennai, Tamil Nadu; it was one of the original zones formed in 1951, covering most of South India including Tamil Nadu, Kerala, Puducherry, and parts of Karnataka and Andhra Pradesh.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q063', 'railway-exam-bank', 'General Awareness', 0, 62, 'What is the headquarters of Central Railway, and where was the first train in India flagged off from a station under this zone?', 'Central Railway''s headquarters is Chhatrapati Shivaji Maharaj Terminus (CSMT) in Mumbai, which is also where India''s first passenger train departed from (then called Bori Bunder) on April 16, 1853.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q064', 'railway-exam-bank', 'General Awareness', 0, 63, 'Which city is the headquarters of Western Railway?', 'Western Railway''s headquarters is at Churchgate, Mumbai; it covers Gujarat, parts of Maharashtra, Madhya Pradesh, and the Union Territories of Daman, Diu, and Dadra & Nagar Haveli.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q065', 'railway-exam-bank', 'General Awareness', 0, 64, 'What is the headquarters of South Eastern Railway?', 'South Eastern Railway''s headquarters is at Garden Reach, Kolkata; it primarily serves West Bengal, Jharkhand, Odisha, and Chhattisgarh.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q066', 'railway-exam-bank', 'General Awareness', 0, 65, 'Where is the headquarters of South Central Railway located?', 'South Central Railway''s headquarters is at Secunderabad, Telangana; it was formed in 1966 and covers parts of Telangana, Andhra Pradesh, Karnataka, and Maharashtra.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q067', 'railway-exam-bank', 'General Awareness', 0, 66, 'What is the headquarters of North Eastern Railway, and how does it differ from Northeast Frontier Railway?', 'North Eastern Railway''s headquarters is at Gorakhpur, Uttar Pradesh, covering parts of UP and Bihar. It is a distinct zone from Northeast Frontier Railway (headquartered at Maligaon, Guwahati), which serves the northeastern states of India — the similar names often cause confusion in exams.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q068', 'railway-exam-bank', 'General Awareness', 0, 67, 'Which zone has its headquarters at Hajipur, Bihar?', 'East Central Railway has its headquarters at Hajipur, Bihar; it was carved out in 2002 and covers parts of Bihar, Jharkhand, and Uttar Pradesh.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q069', 'railway-exam-bank', 'General Awareness', 0, 68, 'What is the headquarters of East Coast Railway?', 'East Coast Railway''s headquarters is at Bhubaneswar, Odisha; it was formed in 2003 and primarily covers Odisha and parts of Andhra Pradesh and Chhattisgarh.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q070', 'railway-exam-bank', 'General Awareness', 0, 69, 'Where is the headquarters of South East Central Railway?', 'South East Central Railway''s headquarters is at Bilaspur, Chhattisgarh; it was formed in 2003, carved out from South Eastern and Central Railway zones.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q071', 'railway-exam-bank', 'General Awareness', 0, 70, 'What is the headquarters of North Western Railway?', 'North Western Railway''s headquarters is at Jaipur, Rajasthan; it primarily covers Rajasthan and parts of Haryana, Punjab, and Gujarat.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q072', 'railway-exam-bank', 'General Awareness', 0, 71, 'Which zone is headquartered at Hubballi (Hubli), Karnataka?', 'South Western Railway is headquartered at Hubballi, Karnataka; it was formed in 2003 and covers Karnataka and parts of Andhra Pradesh.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q073', 'railway-exam-bank', 'General Awareness', 0, 72, 'On which date did India''s first passenger train run, and between which two stations?', 'India''s first passenger train ran on April 16, 1853, between Bori Bunder (now Chhatrapati Shivaji Maharaj Terminus) in Bombay and Thane, covering a distance of about 34 kilometres.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q074', 'railway-exam-bank', 'General Awareness', 0, 73, 'Which company operated India''s first railway line?', 'The Great Indian Peninsula Railway (GIPR) operated India''s first railway line, running the inaugural passenger service between Bombay and Thane in 1853.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q075', 'railway-exam-bank', 'General Awareness', 0, 74, 'When were the Indian Railways zones formed through nationalization/reorganization, and how many zones were initially created?', 'The various private railway companies operating in India were consolidated into zones starting in 1951-52, with six initial zones created; the system has since been expanded multiple times to the current 17-plus zones.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q076', 'railway-exam-bank', 'General Awareness', 0, 75, 'Until which year was the Railway Budget presented separately from the Union Budget in India?', 'The Railway Budget was presented separately from the Union Budget from 1924 until 2016; starting with the 2017-18 budget, it was merged into the Union Budget presented by the Finance Minister.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q077', 'railway-exam-bank', 'General Awareness', 0, 76, 'Under whose administration was India''s early railway network, including the Bombay-Thane line, primarily built?', 'India''s early railway network was built primarily under British colonial administration, with British engineers and companies like the Great Indian Peninsula Railway leading construction, as railways were initially built to serve colonial trade and administrative interests.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q078', 'railway-exam-bank', 'General Awareness', 0, 77, 'What is the significance of April 16 in the history of Indian Railways?', 'April 16 marks the anniversary of India''s first passenger train journey in 1853 (Bombay to Thane), and is often referenced in railway history discussions and general awareness exam sections as the founding date of Indian passenger rail travel.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q079', 'railway-exam-bank', 'General Awareness', 0, 78, 'Which Indian railway company built one of the first railway lines in the eastern part of India?', 'The East Indian Railway Company built one of the earliest railway lines in eastern India, connecting Howrah to Hooghly in 1854, shortly after the first line opened in western India.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q080', 'railway-exam-bank', 'General Awareness', 0, 79, 'What major administrative change took effect for Indian Railways'' zonal structure in 2010 with the inclusion of Metro Railway?', 'Metro Railway, Kolkata (operating the Kolkata Metro) was designated as a separate zone of Indian Railways in 2010, becoming the newest zone at that time and the first to operate purely urban metro services under the zonal railway structure.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q081', 'railway-exam-bank', 'General Awareness', 0, 80, 'When was the Rajdhani Express introduced, and what does its name signify?', 'The Rajdhani Express was introduced in 1969, running between New Delhi and Howrah. Its name means "capital," as these premier trains connect the national capital, New Delhi, with various state capitals.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q082', 'railway-exam-bank', 'General Awareness', 0, 81, 'What is distinctive about the Shatabdi Express trains?', 'Shatabdi Express trains are intercity, same-day-return services (no overnight travel), introduced in 1988 to mark the birth centenary of Jawaharlal Nehru, typically covering shorter distances than Rajdhani trains and returning to the origin station the same day.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q083', 'railway-exam-bank', 'General Awareness', 0, 82, 'What makes the Vande Bharat Express significant among Indian trains?', 'The Vande Bharat Express, first launched in 2019 (originally called Train 18), is a semi-high-speed, self-propelled (no separate locomotive needed) train set designed and manufactured indigenously in India, representing a major step in domestic railway technology.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q084', 'railway-exam-bank', 'General Awareness', 0, 83, 'What is the key operational feature of a Duronto Express train?', 'Duronto Express trains are designed as point-to-point, non-stop services connecting two major cities directly, without intermediate halts (except for operational necessities like crew changes), aiming to minimize overall journey time between the two endpoints.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q085', 'railway-exam-bank', 'General Awareness', 0, 84, 'What is the Gatimaan Express known for, and which route does it operate on?', 'The Gatimaan Express, operating between Delhi and Agra, was India''s fastest conventional train (before the Vande Bharat era), reaching speeds of up to 160 km/h, significantly cutting travel time on that route.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q086', 'railway-exam-bank', 'General Awareness', 0, 85, 'What is the Garib Rath Express designed to provide?', 'The Garib Rath Express is designed to provide air-conditioned rail travel at affordable fares for economically weaker sections of society, offering 3-tier AC accommodation at rates lower than standard AC classes on other trains.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q087', 'railway-exam-bank', 'General Awareness', 0, 86, 'What is distinctive about the Humsafar Express service?', 'The Humsafar Express is a fully air-conditioned, 3-tier (3A) service introduced to provide comfortable long-distance travel with amenities like CCTV cameras, bio-toilets, and charging points, targeting passengers who want AC comfort without the higher cost of 1A or 2A classes.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q088', 'railway-exam-bank', 'General Awareness', 0, 87, 'What is the purpose of the Antyodaya Express trains?', 'Antyodaya Express trains are fully unreserved, superfast services introduced to provide affordable long-distance travel for economically disadvantaged passengers, without the need for advance reservations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q089', 'railway-exam-bank', 'General Awareness', 0, 88, 'What is unique about the Tejas Express compared to typical Indian Railways trains?', 'The Tejas Express is a premium train service featuring airline-style amenities such as onboard entertainment screens, attendants, and enhanced passenger comfort, and on some routes has been operated by IRCTC rather than directly by a zonal railway division.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q090', 'railway-exam-bank', 'General Awareness', 0, 89, 'What was "Train 18," and what is its current name?', '"Train 18" was the developmental/project name for India''s first indigenously designed and manufactured semi-high-speed train set, which was later launched commercially as the Vande Bharat Express.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q091', 'railway-exam-bank', 'General Awareness', 0, 90, 'What are the three main gauge types historically used on Indian Railways, and what is "Project Unigauge"?', 'The three gauges are Broad Gauge (1,676 mm), Metre Gauge (1,000 mm), and Narrow Gauge (762 mm or 610 mm). "Project Unigauge" is an ongoing Indian Railways initiative to convert metre gauge and narrow gauge lines to broad gauge, to standardize the network and improve operational efficiency.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q092', 'railway-exam-bank', 'General Awareness', 0, 91, 'What is the standard voltage used for overhead electric traction on Indian Railways'' broad gauge electrified lines?', 'Indian Railways primarily uses 25 kV AC (alternating current) for overhead traction electrification on its broad gauge network, supplied through overhead catenary wires to electric locomotives.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q093', 'railway-exam-bank', 'General Awareness', 0, 92, 'What is a "Dedicated Freight Corridor (DFC)," and name the two major DFCs built in India.', 'A Dedicated Freight Corridor is a railway line built exclusively for freight trains, separating them from passenger traffic to improve speed and capacity for both. India''s two major DFCs are the Eastern DFC (Punjab to West Bengal) and the Western DFC (Mumbai/JNPT to Delhi-NCR), constructed by the Dedicated Freight Corridor Corporation of India Limited (DFCCIL).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q094', 'railway-exam-bank', 'General Awareness', 0, 93, 'What is the role of the Dedicated Freight Corridor Corporation of India Limited (DFCCIL)?', 'DFCCIL is a public sector undertaking under the Ministry of Railways responsible for planning, constructing, and operating India''s Dedicated Freight Corridors, aimed at decongesting existing passenger lines and improving freight transport efficiency.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q095', 'railway-exam-bank', 'General Awareness', 0, 94, 'What is the significance of the Chenab Rail Bridge?', 'The Chenab Rail Bridge, part of the Udhampur-Srinagar-Baramulla Rail Link in Jammu & Kashmir, is the world''s highest railway bridge, standing about 359 metres above the Chenab River, and is a key engineering achievement connecting the Kashmir Valley to the rest of India''s rail network.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q096', 'railway-exam-bank', 'General Awareness', 0, 95, 'What is the Bogibeel Bridge, and where is it located?', 'The Bogibeel Bridge, located in Assam over the Brahmaputra River, is India''s longest combined rail-road bridge, providing a crucial connectivity link to the northeastern states for both rail and road traffic.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q097', 'railway-exam-bank', 'General Awareness', 0, 96, 'What is the significance of the Pamban Bridge?', 'The Pamban Bridge connects Rameswaram island to mainland India across the Palk Strait in Tamil Nadu; the original bridge (opened in 1914) was one of India''s first sea bridges, and a new vertical-lift railway bridge has since been built alongside it to allow ships to pass underneath while the rail line continues to operate.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q098', 'railway-exam-bank', 'General Awareness', 0, 97, 'What does electrification of the railway network primarily aim to achieve, from an operational standpoint?', 'Railway electrification replaces diesel locomotives with electric ones, aiming to reduce fuel costs and carbon emissions, increase average train speeds and haulage capacity, and improve overall energy efficiency across the network.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q099', 'railway-exam-bank', 'General Awareness', 0, 98, 'What is the role of the Research Designs and Standards Organisation (RDSO)?', 'RDSO, headquartered in Lucknow, is the research and standards-setting wing of Indian Railways, responsible for developing and approving technical standards, designs, and new technologies (such as the Kavach safety system) used across the railway network.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q100', 'railway-exam-bank', 'General Awareness', 0, 99, 'What type of track gauge does the Delhi Metro and most Indian metro systems typically use, compared to Indian Railways'' mainline network?', 'Most Indian metro systems, including the Delhi Metro, use standard gauge (1,435 mm) tracks, which is narrower than Indian Railways'' mainline broad gauge (1,676 mm), as metro systems are designed independently for urban transit needs rather than integration with the national rail network.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q101', 'railway-exam-bank', 'General Awareness', 0, 100, 'What is "Kavach," and what problem is it designed to solve?', 'Kavach is an indigenously developed Automatic Train Protection (ATP) system by RDSO that automatically applies brakes to prevent train collisions if a driver fails to control the train''s speed according to signals, directly addressing the risk of accidents caused by human error or signal overshooting.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q102', 'railway-exam-bank', 'General Awareness', 0, 101, 'What do the three standard colors of railway signals typically indicate?', 'A red signal means stop, a yellow (amber) signal typically means proceed with caution and prepare to stop at the next signal, and a green signal means the line ahead is clear to proceed at the permitted speed.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q103', 'railway-exam-bank', 'General Awareness', 0, 102, 'What is "interlocking" in the context of railway signaling?', 'Interlocking is a safety system that ensures signals, points (track switches), and routes are set in a mutually safe and consistent sequence, preventing a signal from showing "clear" unless the corresponding points and route are correctly and safely aligned.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q104', 'railway-exam-bank', 'General Awareness', 0, 103, 'What is the purpose of "block signaling" on a railway line?', 'Block signaling divides a railway line into sections called "blocks," allowing only one train to occupy a given block at a time, which prevents two trains from colliding by ensuring a safe distance is always maintained between consecutive trains on the same line.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q105', 'railway-exam-bank', 'General Awareness', 0, 104, 'What is an "Automatic Train Protection (ATP)" system designed to prevent, broadly speaking?', 'An Automatic Train Protection system is designed to automatically intervene (typically by applying brakes) to prevent a train from passing a danger signal, exceeding a permitted speed limit, or colliding with another train, reducing reliance on driver reaction alone for safety-critical situations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q106', 'railway-exam-bank', 'General Awareness', 0, 105, 'What is the function of a "level crossing" on a railway line, and why are many being replaced with alternatives?', 'A level crossing is a point where a railway line crosses a road at the same level, often controlled by gates or signals. Many are being replaced with road overbridges (ROBs) or underbridges (RUBs) because level crossings are a significant cause of accidents involving vehicles and pedestrians.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q107', 'railway-exam-bank', 'General Awareness', 0, 106, 'What is the purpose of "Train Collision Avoidance System (TCAS)," and how does it relate to Kavach?', 'Train Collision Avoidance System (TCAS) was the earlier name for what has since been rebranded and further developed as "Kavach" — an indigenous automatic train protection technology aimed at preventing train-to-train collisions on Indian Railways.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q108', 'railway-exam-bank', 'General Awareness', 0, 107, 'What safety role do "fog signals" (detonators) traditionally serve in railway operations?', 'Fog signals, also called detonators, are small explosive devices placed on the tracks that produce a loud bang when a train passes over them, used historically to warn train drivers of an upcoming signal when visibility is poor due to fog, before more modern visibility-independent systems became common.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q109', 'railway-exam-bank', 'General Awareness', 0, 108, 'What is the role of the Railway Board in Indian Railways'' organizational structure?', 'The Railway Board is the apex decision-making body of Indian Railways, functioning under the Ministry of Railways, responsible for policy formulation, overall administration, and coordination across all zones; it is headed by a Chairman and CEO.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q110', 'railway-exam-bank', 'General Awareness', 0, 109, 'How is each zone of Indian Railways administratively led, and how does this differ from division-level leadership?', 'Each zone is headed by a General Manager (GM), who oversees the zone''s overall operations and policy implementation. Each zone is further divided into operating divisions, each headed by a Divisional Railway Manager (DRM), who manages day-to-day operations within that division.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q111', 'railway-exam-bank', 'General Awareness', 0, 110, 'Under which ministry does Indian Railways function?', 'Indian Railways functions under the Ministry of Railways, Government of India, which oversees policy, investment, and overall governance of the national rail network through the Railway Board.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q112', 'railway-exam-bank', 'General Awareness', 0, 111, 'What is the difference between a "zone" and a "division" in Indian Railways'' structure?', 'A zone is a large administrative unit covering a broad geographic region (headed by a General Manager), while a division is a smaller administrative subdivision within a zone (headed by a Divisional Railway Manager), responsible for more localized day-to-day operational management.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q113', 'railway-exam-bank', 'General Awareness', 0, 112, 'What is the role of the Centre for Railway Information Systems (CRIS)?', 'CRIS is the IT arm of Indian Railways, responsible for developing and maintaining key digital systems used across the network, including the Passenger Reservation System (PRS), Freight Operations Information System (FOIS), and the National Train Enquiry System (NTES).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q114', 'railway-exam-bank', 'General Awareness', 0, 113, 'What is the Integral Coach Factory (ICF), and where is it located?', 'The Integral Coach Factory, located in Chennai, Tamil Nadu, is one of Indian Railways'' primary coach manufacturing units, producing passenger coaches used across the national network since the 1950s.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q115', 'railway-exam-bank', 'General Awareness', 0, 114, 'What is the Chittaranjan Locomotive Works (CLW) known for producing?', 'The Chittaranjan Locomotive Works, located in West Bengal, is one of Indian Railways'' main manufacturing units for electric locomotives, playing a key role in supplying electric traction power units for the network.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q116', 'railway-exam-bank', 'General Awareness', 0, 115, 'Which Indian railway station holds the distinction of having one of the world''s longest railway platforms?', 'Gorakhpur railway station in Uttar Pradesh has one of the world''s longest railway platforms, spanning well over a kilometre in length.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q117', 'railway-exam-bank', 'General Awareness', 0, 116, 'What UNESCO recognition does Chhatrapati Shivaji Maharaj Terminus (CSMT) in Mumbai hold?', 'Chhatrapati Shivaji Maharaj Terminus (CSMT), the headquarters of Central Railway, is recognized as a UNESCO World Heritage Site, noted for its Victorian Gothic Revival architecture blended with traditional Indian elements.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q118', 'railway-exam-bank', 'General Awareness', 0, 117, 'Why is Howrah railway station historically significant among Indian railway stations?', 'Howrah railway station, serving Kolkata, is one of the oldest and busiest railway stations in India, having played a central role in the development of railway transport in eastern India since the mid-19th century.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q119', 'railway-exam-bank', 'General Awareness', 0, 118, 'What is the significance of Charbagh railway station in Lucknow?', 'Charbagh railway station in Lucknow is notable for its distinctive architecture, which blends Rajput, Mughal, and Awadhi styles, and it serves as a major railway hub for the Lucknow region in North Central and Northern Railway zones.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q120', 'railway-exam-bank', 'General Awareness', 0, 119, 'What does the Modern Coach Factory (MCF) in Raebareli primarily manufacture?', 'The Modern Coach Factory in Raebareli, Uttar Pradesh, is one of Indian Railways'' newer coach-manufacturing units, producing modern passenger coaches including stainless steel and LHB (Linke Hofmann Busch) design coaches used in many express trains.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q121', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 120, 'In the series 5, 11, 23, 47, 95, ?, what is the missing number and what is the rule?', 'The missing number is 191. Each term is formed by doubling the previous term and adding 1: 5x2+1=11, 11x2+1=23, 23x2+1=47, 47x2+1=95, 95x2+1=191.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q122', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 121, 'Find the next term in the series: 3, 9, 27, 81, ?', 'The next term is 243. Each term is obtained by multiplying the previous term by 3, since this is a geometric series with a common ratio of 3: 3x3=9, 9x3=27, 27x3=81, 81x3=243.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q123', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 122, 'What comes next in the letter series: A, D, G, J, M, ?', 'The next letter is P. The series skips two letters each time, moving forward by 3 positions in the alphabet: A(1)+3=D(4), D+3=G(7), G+3=J(10), J+3=M(13), M+3=P(16).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q124', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 123, 'Find the missing number in the series: 1, 4, 9, 16, 25, ?', 'The missing number is 36. This is the series of perfect squares: 1 squared=1, 2 squared=4, 3 squared=9, 4 squared=16, 5 squared=25, 6 squared=36.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q125', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 124, 'What is the next term in the series: 2, 5, 10, 17, 26, ?', 'The next term is 37. The differences between consecutive terms increase by 2 each time (3, 5, 7, 9, 11), following the pattern n squared plus 1: for n=1..6 this gives 2, 5, 10, 17, 26, 37.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q126', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 125, 'If each letter in a word is replaced by the letter that comes exactly 3 positions after it in the alphabet, how would the word "BUS" be coded?', 'The word "BUS" would be coded as "EXV". Each letter shifts forward by 3 positions: B(2)+3=E(5), U(21)+3=X(24), S(19)+3=V(22).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q127', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 126, 'In a certain code, "FLOWER" is written as "EKNVDQ". What is the coding rule, and how would "GARDEN" be coded using the same rule?', 'The rule is that each letter is shifted one position backward in the alphabet (F to E, L to K, O to N, W to V, E to D, R to Q). Applying the same rule to "GARDEN" gives G to F, A to Z (wrapping to the previous letter before A), R to Q, D to C, E to D, N to M, so "GARDEN" would be coded as "FZQCDM".', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q128', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 127, 'If "1" stands for "A", "2" stands for "B", and so on up to "26" for "Z", how would the word "CAB" be represented numerically?', '"CAB" would be represented as 3-1-2, since C is the 3rd letter, A is the 1st letter, and B is the 2nd letter of the alphabet.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q129', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 128, 'If each letter is coded by its position in the alphabet, how would the word "SEAT" be coded?', '"SEAT" would be coded as 19-5-1-20, since S is the 19th letter, E is the 5th letter, A is the 1st letter, and T is the 20th letter of the alphabet.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q130', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 129, 'In a certain code, ''+'' means ''minus'', ''-'' means ''multiplied by'', ''x'' means ''divided by'', and ''÷'' means ''plus''. What is the value of "8 + 4 x 2 ÷ 6 - 3" using this code?', 'The value is 24. Substituting the actual operations (+ becomes minus, x becomes divide, - becomes multiply, divide-sign becomes plus), the expression becomes 8 minus (4 divided by 2) plus (6 multiplied by 3). Following the standard order of operations (division and multiplication before addition and subtraction): 4 divided by 2 is 2, and 6 multiplied by 3 is 18, so the expression becomes 8 minus 2 plus 18 = 24.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q131', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 130, 'Pointing to a photograph, Rohan said, "She is the daughter of my grandfather''s only son." How is the woman in the photograph related to Rohan?', 'The woman is Rohan''s sister. Rohan''s grandfather''s only son is Rohan''s father (since there is only one son), so the daughter of Rohan''s father is Rohan''s sister.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q132', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 131, 'If P is the brother of Q, Q is the sister of R, and R is the father of S, how is P related to S?', 'P is S''s uncle. Since R is S''s father and Q is R''s sibling (making Q S''s aunt), and P is Q''s brother, P is also R''s sibling, making P the uncle of S.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q133', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 132, 'A is the mother of B. B is the sister of C. D is the father of C. How is D related to A?', 'D is A''s husband. Since A is the mother of B, and D is the father of C who is B''s sibling, both A and D are the parents of B and C, making D the husband of A.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q134', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 133, 'Introducing a man, a woman said, "He is the son of my mother''s only daughter." How is the woman related to the man?', 'The woman is the man''s mother. Since the woman''s mother''s only daughter is the woman herself (as she has no sisters), the son referred to is the woman''s own son, making the woman his mother.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q135', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 134, 'X and Y are sisters. M is the brother of N, and N is the daughter of X. How is M related to Y?', 'M is Y''s nephew. Since N is X''s daughter, and M is N''s brother, M is also X''s son, making M the nephew of Y, who is X''s sister.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q136', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 135, 'A man walks 5 km towards south, then turns left and walks 3 km, then turns left again and walks 5 km. How far is he from his starting point, and in which direction?', 'He is 3 km away from his starting point, to the east. Walking south then turning left (east) for 3 km, then turning left again (north) for 5 km brings him back to the same latitude as the start but 3 km to the east, since the two 5 km legs (south then north) cancel out.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q137', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 136, 'Starting from a point, a person walks 10 metres north, then 6 metres east, then 10 metres south. How far and in which direction is he from the starting point?', 'He is 6 metres east of the starting point. The 10 metres north and 10 metres south movements cancel each other out, leaving only the 6 metres east displacement.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q138', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 137, 'A person walks 4 km east, then turns and walks 4 km south, then turns and walks 4 km west. In which direction is he now from his starting point, and how far?', 'He is 4 km south of his starting point. The eastward and westward movements of 4 km each cancel out, leaving only the 4 km southward displacement.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q139', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 138, 'If South-East becomes North, and North-East becomes West, following the same consistent rotation, what will South become?', 'South will become East. The directions are being rotated 135 degrees anticlockwise consistently (South-East to North is a 135 degree shift), so applying the same rotation to South results in East.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q140', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 139, 'Ravi walks 7 km towards north. From there, he walks 3 km towards south. Then, he walks 4 km towards east. How far and in which direction is he from his starting point?', 'His net displacement is 4 km north (7 km north minus 3 km south) and 4 km east, giving a straight-line distance of about 5.7 km (the square root of 4 squared plus 4 squared) in the north-east direction from the starting point.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q141', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 140, 'Consider the statements: "All pens are books. Some books are tables." Does it logically follow that "Some pens are tables"?', 'No, it does not necessarily follow. Since only "some" books are tables, there is no guarantee that any of the books that are pens are among those that are tables, so the conclusion is not a valid logical certainty from the given premises.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q142', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 141, 'Statements: "All doctors are engineers. All engineers are teachers." What can be validly concluded about doctors and teachers?', 'It can be validly concluded that "All doctors are teachers", since every doctor is an engineer (first statement), and every engineer is a teacher (second statement), so by transitivity, every doctor must also be a teacher.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q143', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 142, 'Statements: "No cat is a dog. All dogs are animals." What can be concluded about cats and animals?', 'No valid universal conclusion can be drawn connecting cats and animals from these two statements alone. The statements only establish that cats and dogs are mutually exclusive categories and that dogs are a subset of animals, but say nothing definite about whether cats are or are not animals.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q144', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 143, 'Statements: "Some flowers are red. All red things are beautiful." What can be concluded?', 'It can be concluded that "Some flowers are beautiful", since at least some flowers fall into the category of red things, and all red things are beautiful, so those particular flowers must also be beautiful.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q145', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 144, 'Statements: "All squares are rectangles. No rectangle is a triangle." What can be concluded about squares and triangles?', 'It can be concluded that "No square is a triangle", since every square is a rectangle, and no rectangle can be a triangle, so squares cannot be triangles either.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q146', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 145, '"Pen is to Write" as "Knife is to ?" Complete the analogy and explain the relationship.', '"Knife is to Cut." The relationship is tool-to-function: a pen is used to write, just as a knife is used to cut, with each tool paired with its primary purpose.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q147', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 146, '"Doctor is to Hospital" as "Teacher is to ?" Complete the analogy.', '"Teacher is to School." The relationship is profession-to-workplace: a doctor''s typical workplace is a hospital, just as a teacher''s typical workplace is a school.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q148', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 147, '"Fish is to Water" as "Bird is to ?" Complete the analogy and explain the relationship.', '"Bird is to Air (or Sky)." The relationship is organism-to-natural-habitat: a fish lives and moves primarily in water, just as a bird lives and moves primarily in air.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q149', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 148, '"Author is to Book" as "Sculptor is to ?" Complete the analogy.', '"Sculptor is to Sculpture (or Statue)." The relationship is creator-to-creation: an author creates a book, just as a sculptor creates a sculpture.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q150', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 149, '"12 is to 144" as "9 is to ?" Complete the numerical analogy and explain the rule.', '"9 is to 81." The rule is squaring the first number: 12 squared is 144, so following the same rule, 9 squared is 81.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q151', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 150, 'Which word does not belong with the others: Apple, Mango, Potato, Banana?', '"Potato" does not belong with the others. Apple, Mango, and Banana are all fruits, while Potato is a vegetable (specifically a tuber).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q152', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 151, 'Find the odd one out: Triangle, Square, Circle, Cube.', '"Cube" is the odd one out. Triangle, Square, and Circle are two-dimensional (flat) shapes, while a Cube is a three-dimensional solid shape.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q153', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 152, 'Find the odd number from the group: 16, 25, 36, 48, 49.', '"48" is the odd one out. 16, 25, 36, and 49 are all perfect squares (4, 5, 6, and 7 squared respectively), while 48 is not a perfect square.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q154', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 153, 'Which does not belong: Delhi, Mumbai, Kolkata, India?', '"India" does not belong with the others. Delhi, Mumbai, and Kolkata are all cities, while India is a country, a different category and level of classification.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q155', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 154, 'Find the odd one out: Eagle, Sparrow, Bat, Pigeon.', '"Bat" is the odd one out. Eagle, Sparrow, and Pigeon are all birds, while a Bat is a mammal, even though it can also fly.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q156', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 155, 'In a class of 40 students, Rohan ranks 12th from the top. What is his rank from the bottom?', 'Rohan''s rank from the bottom is 29th. Using the formula: Rank from bottom = Total students minus Rank from top plus 1 = 40 minus 12 plus 1 = 29.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q157', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 156, 'Five friends, P, Q, R, S, and T, are standing in a line based on height, with the order from tallest to shortest being P, Q, R, S, T. What is R''s rank from the shortest end?', 'R''s rank from the shortest end is 3rd. Since the order from tallest to shortest is P(1st), Q(2nd), R(3rd), S(4th), T(5th), counting from the shortest end (T is 1st, S is 2nd, R is 3rd).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q158', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 157, 'In a row of children, Meena is 7th from the left and 15th from the right. How many children are there in total in the row?', 'There are 21 children in the row. Using the formula: Total = (Position from left) plus (Position from right) minus 1 = 7 plus 15 minus 1 = 21.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q159', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 158, 'A is older than B but younger than C. D is older than C but younger than E. Who is the oldest among A, B, C, D, and E?', 'E is the oldest. The order from oldest to youngest is E, D, C, A, B, since D is older than C and younger than E (making E older than D, who is older than C), and C is older than A, who is older than B.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q160', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 159, 'In a sequence of 50 students arranged by marks, Priya ranks 18th from the top. If 5 students who scored lower than Priya are removed from the ranking, what would be Priya''s new rank from the top?', 'Priya''s rank from the top would remain 18th, since the 5 students removed scored lower than her and were ranked below her, so removing them does not affect the rank of anyone above or at her own position.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q161', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 160, 'If January 1, 2023, was a Sunday, what day of the week was January 1, 2024?', 'January 1, 2024, was a Monday. A normal (non-leap) year has 365 days, which is 52 weeks plus 1 extra day, so the day of the week advances by exactly 1 day when moving from January 1 of one normal year to January 1 of the next.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q162', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 161, 'What is the angle between the hour hand and the minute hand of a clock at 3:00?', 'The angle is 90 degrees. At 3:00, the minute hand points at 12 and the hour hand points at 3; each hour mark represents 30 degrees (360 divided by 12), so the hour hand at the 3 mark is 3 times 30, which is 90 degrees from the 12 mark.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q163', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 162, 'How many times do the hour and minute hands of a clock overlap (coincide) in a 12-hour period?', 'The hands overlap 11 times in a 12-hour period, not 12 times, because the minute hand gains a full lap on the hour hand roughly every 65 minutes rather than exactly every 60 minutes, causing one fewer overlap than a naive count of 12 would suggest.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q164', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 163, 'If today is Wednesday, what day of the week will it be 17 days from now?', 'It will be Saturday. Dividing 17 by 7 gives a remainder of 3 (17 = 2 times 7, plus 3), so counting 3 days forward from Wednesday gives Thursday, Friday, and then Saturday.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q165', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 164, 'A clock shows 4:30. What is the angle between the hour and minute hands at this time?', 'The angle is 45 degrees. At 4:30, the minute hand is at the 6 mark (180 degrees from 12). The hour hand, having moved halfway between 4 and 5, is at 4.5 times 30, which is 135 degrees from 12. The difference between 180 and 135 is 45 degrees.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q166', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 165, 'If a clock''s reflection in a mirror shows the time as 3:40, what is the actual time?', 'The actual time is 8:20. For mirror images of clock times, the rule is to subtract the shown time from 11:60: 11:60 minus 3:40 equals 8:20.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q167', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 166, 'In a water-image (reflection in water) of an object, how does the orientation differ from a regular mirror image?', 'A water image inverts the object top-to-bottom (vertically), unlike a regular mirror image (held vertically beside the object), which inverts it left-to-right (laterally) while keeping the top and bottom unchanged.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q168', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 167, 'If the word "MIRROR" is viewed in a plane mirror, which letters in it would appear unchanged in shape (though the overall word is reversed in sequence)?', 'Letters like "M", "O", and "R" (as written in standard uppercase block form) are vertically symmetric, so their individual shapes stay visually recognizable in a mirror, even though a mirror reverses the left-right sequence of the whole word.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q169', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 168, 'In a figure-series pattern-completion question, a square figure rotates 90 degrees clockwise at each step. If the figure starts pointing north, where will it point after 3 steps?', 'After 3 steps of 90 degree clockwise rotation each (totaling 270 degrees), the figure will point west. Starting at north (0 degrees), each 90 degree clockwise step moves it to east (90 degrees), then south (180 degrees), then west (270 degrees).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q170', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 169, 'In a non-verbal reasoning "paper folding and cutting" question, if a square paper is folded in half twice and a hole is punched through all layers, how many holes will appear when the paper is unfolded?', '4 holes will appear when unfolded. Folding the paper in half twice creates 4 layers (2 times 2), so punching a single hole through all the folded layers creates 4 corresponding holes once the paper is fully unfolded.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q171', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 170, 'Five people, A, B, C, D, and E, are sitting in a row facing north, in the left-to-right order C, A, B, D, E. Who is sitting at the extreme right end?', 'E is sitting at the extreme right end, since the given left-to-right order is C, A, B, D, E, making E the last, and therefore rightmost, person in the row.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q172', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 171, 'In a circular seating arrangement of 6 people facing the center, if P is seated to the immediate right of Q, what is Q''s position relative to P?', 'Q is seated to the immediate left of P. In a circular arrangement, if P is immediately to the right of Q, then by definition Q must be immediately to the left of P, since the relationship is simply reversed depending on whose perspective is used.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q173', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 172, 'Four friends, J, K, L, and M, are sitting around a square table, one on each side. J is facing K, and L is to the immediate right of J. Where is M sitting relative to J?', 'M is sitting to the immediate left of J. Since J and K are facing each other (sitting on opposite sides) and L is immediately to J''s right, the only remaining side, immediately to J''s left, must be occupied by M.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q174', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 173, 'In a row of 8 people facing north, X is 3rd from the left end and Y is 4th from the right end. How is Y''s position from the left end calculated, and how many people sit between X and Y?', 'Y''s position from the left end is calculated as Total minus position from right plus 1, which is 8 minus 4 plus 1 equals 5. Since X is at position 3 and Y is at position 5, exactly 1 person (at position 4) sits between them.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q175', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 174, 'Six people are standing in a line, numbered 1 to 6 from left to right. If Raj is standing at position 4, how many people are standing to his right, and how many to his left?', 'Raj has 3 people to his left (positions 1, 2, and 3) and 2 people to his right (positions 5 and 6), since the line has 6 positions total and he occupies position 4.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q176', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 175, 'Statement: "The government has announced a new scholarship scheme for meritorious students from low-income families." Conclusion I: "All low-income families will now be able to afford education." Conclusion II: "Some meritorious students from low-income families may benefit financially from this scheme." Which conclusion logically follows?', 'Conclusion II follows, while Conclusion I does not. The statement only promises support to "meritorious" students, a subset and not all students, so it does not support the sweeping claim in Conclusion I, while it directly supports the more measured and specific claim in Conclusion II.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q177', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 176, 'Statement: "Due to heavy rainfall, several flights were delayed at the airport yesterday." Conclusion I: "Heavy rainfall always causes flight delays." Conclusion II: "Weather conditions can affect flight schedules." Which conclusion logically follows?', 'Conclusion II follows, while Conclusion I does not. The statement describes a single instance of delays caused by rainfall, which supports the general idea that weather can affect flights, but does not justify the absolute claim that heavy rainfall "always" causes delays.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q178', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 177, 'Statement: "The company reported a 10% increase in profits this quarter compared to the previous quarter." Conclusion I: "The company''s sales volume definitely increased this quarter." Conclusion II: "The company''s financial performance improved this quarter compared to the previous one." Which conclusion logically follows?', 'Conclusion II follows, while Conclusion I does not necessarily follow. An increase in profit does not automatically mean sales volume increased, since profit could rise due to cost-cutting or price increases even with flat or lower sales, but it does directly indicate that overall financial performance improved.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q179', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 178, 'Statement: "Only candidates who score above 60% in the written exam will be called for the interview." Conclusion I: "A candidate who scores 55% will not be called for the interview." Conclusion II: "A candidate who scores 75% will definitely get the job." Which conclusion logically follows?', 'Conclusion I follows, while Conclusion II does not. The statement directly implies that scoring 55 percent, below the 60 percent threshold, disqualifies a candidate from the interview stage, but merely qualifying for an interview does not guarantee they will actually get the job, since other factors like interview performance would still apply.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q180', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 179, 'Statement: "Several studies have found a correlation between regular exercise and improved mental health." Conclusion I: "Regular exercise always directly causes improved mental health." Conclusion II: "There may be a meaningful relationship between physical activity and mental well-being worth further study." Which conclusion logically follows?', 'Conclusion II follows, while Conclusion I does not. The statement describes a "correlation" found by studies, which only indicates an observed relationship, not proven direct causation, so Conclusion II''s cautious framing is supported, while Conclusion I''s absolute causal claim overreaches from correlational data.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q181', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 180, 'In an exam, a student scored 408 marks out of 600. What percentage of marks did the student score?', 'Percentage = (408/600) times 100 = 68%. So the student scored 68% marks.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q182', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 181, 'If 35% of a number is 161, what is the number?', 'Let the number be x. 35% of x = 161, so (35/100) times x = 161. Therefore x = (161 times 100)/35 = 460.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q183', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 182, 'The price of an item increased from Rs. 250 to Rs. 325. What is the percentage increase?', 'Increase = 325 - 250 = 75. Percentage increase = (75/250) times 100 = 30%.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q184', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 183, 'In a village of 8,000 people, 60% are literate. How many people are illiterate?', 'Literate people = 60% of 8000 = (60/100) times 8000 = 4800. Illiterate people = 8000 - 4800 = 3200.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q185', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 184, 'A number is first increased by 25% and then decreased by 20%. What is the net percentage change?', 'Let the number be 100. After a 25% increase: 100 + 25 = 125. After a 20% decrease on 125: 125 - (20/100 times 125) = 125 - 25 = 100. So there is no net change (0%).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q186', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 185, 'Rahul spends 40% of his monthly salary on rent and 25% of the remaining on groceries. If his salary is Rs. 30,000, how much does he spend on groceries?', 'Rent = 40% of 30000 = 12000. Remaining = 30000 - 12000 = 18000. Groceries = 25% of 18000 = 4500. So Rahul spends Rs. 4500 on groceries.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q187', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 186, 'A trader buys a table for Rs. 1,200 and sells it for Rs. 1,440. What is his profit percentage?', 'Profit = 1440 - 1200 = 240. Profit percentage = (240/1200) times 100 = 20%.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q188', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 187, 'A shopkeeper sells an article at a loss of 15%. If the cost price is Rs. 800, what is the selling price?', 'Loss amount = 15% of 800 = (15/100) times 800 = 120. Selling price = Cost price - Loss = 800 - 120 = Rs. 680.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q189', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 188, 'An item is sold for Rs. 2,340 at a profit of 17%. What was its cost price?', 'Let cost price be x. Selling price = x + 17% of x = 1.17x. So 1.17x = 2340, giving x = 2340/1.17 = Rs. 2000.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q190', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 189, 'A dealer marks goods 40% above cost price and allows a discount of 10% on the marked price. What is his overall profit percentage?', 'Let cost price be 100. Marked price = 100 + 40 = 140. Selling price after 10% discount = 140 - (10% of 140) = 140 - 14 = 126. Profit = 126 - 100 = 26, so profit percentage is 26%.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q191', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 190, 'By selling an article for Rs. 1,350, a man loses 10%. At what price should he sell it to gain 10%?', 'Let cost price be x. Selling at a 10% loss means 0.9x = 1350, so x = 1500. To gain 10%, selling price = 1.1 times 1500 = Rs. 1650.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q192', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 191, 'A sum of Rs. 8,000 is lent at a simple interest rate of 6% per annum for 4 years. What is the total interest earned?', 'Simple Interest = (P times R times T)/100 = (8000 times 6 times 4)/100 = 192000/100 = Rs. 1920.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q193', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 192, 'At what rate of simple interest per annum will a sum of Rs. 5,000 amount to Rs. 6,200 in 4 years?', 'Interest earned = 6200 - 5000 = 1200. Using SI = (P times R times T)/100: 1200 = (5000 times R times 4)/100, so R = (1200 times 100)/(5000 times 4) = 120000/20000 = 6%.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q194', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 193, 'In how many years will a principal of Rs. 12,000 produce a simple interest of Rs. 2,880 at a rate of 8% per annum?', 'Using SI = (P times R times T)/100: 2880 = (12000 times 8 times T)/100, so T = (2880 times 100)/(12000 times 8) = 288000/96000 = 3 years.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q195', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 194, 'Find the compound interest on Rs. 10,000 for 2 years at 10% per annum, compounded annually.', 'Amount = P times (1 + R/100) to the power T = 10000 times (1.1 times 1.1) = 10000 times 1.21 = 12100. Compound Interest = 12100 - 10000 = Rs. 2100.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q196', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 195, 'What is the difference between the compound interest and simple interest on Rs. 5,000 for 2 years at 10% per annum?', 'Simple Interest = (5000 times 10 times 2)/100 = 1000. Compound Interest = 5000 times (1.1 times 1.1) - 5000 = 5000 times 1.21 - 5000 = 6050 - 5000 = 1050. Difference = 1050 - 1000 = Rs. 50.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q197', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 196, 'A sum of money becomes Rs. 9,680 after 2 years at 10% per annum compound interest, compounded annually. What was the original principal?', 'Amount = P times (1.1 times 1.1) = P times 1.21 = 9680, so P = 9680/1.21 = Rs. 8000.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q198', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 197, 'Two numbers are in the ratio 4:7. If their difference is 36, find the two numbers.', 'Let the numbers be 4x and 7x. Their difference is 7x - 4x = 3x = 36, so x = 12. The numbers are 4x = 48 and 7x = 84.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q199', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 198, 'Divide Rs. 2,400 among A, B, and C in the ratio 2:3:5. What is C''s share?', 'Total parts = 2 + 3 + 5 = 10. Value of one part = 2400/10 = 240. C''s share = 5 times 240 = Rs. 1200.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q200', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 199, 'If x:y = 3:4 and y:z = 5:6, find x:y:z.', 'To combine, make y common: x:y = 3:4 = 15:20, and y:z = 5:6 = 20:24 (scaling both so that y = 20). So x:y:z = 15:20:24.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q201', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 200, 'The ratio of the ages of two friends is 5:7. If the sum of their ages is 48 years, what is the age of the older friend?', 'Let the ages be 5x and 7x. Sum = 5x + 7x = 12x = 48, so x = 4. The older friend''s age is 7x = 28 years.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q202', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 201, 'If a:b = 2:3 and b:c = 4:5, find a:c.', 'Make b common: a:b = 2:3 = 8:12, and b:c = 4:5 = 12:15 (scaling both so that b = 12). So a:c = 8:15.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q203', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 202, 'The average of 5 consecutive even numbers is 24. What is the largest number?', 'For 5 consecutive even numbers, the average equals the middle (3rd) number, which is 24. The numbers are 20, 22, 24, 26, 28. The largest number is 28.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q204', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 203, 'The average marks of 30 students in a class is 62. If the average of the first 18 students is 58, what is the average of the remaining 12 students?', 'Total marks of 30 students = 30 times 62 = 1860. Total marks of first 18 students = 18 times 58 = 1044. Marks of remaining 12 students = 1860 - 1044 = 816. Their average = 816/12 = 68.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q205', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 204, 'The average age of a family of 4 members is 25 years. If a baby is born and the average age becomes 21 years, what is the age of the baby?', 'Total age before the baby = 4 times 25 = 100. Total age after the baby (5 members) = 5 times 21 = 105. Age of the baby = 105 - 100 = 5 years.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q206', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 205, 'The average weight of 10 boys is 42 kg. When one boy leaves, the average becomes 41 kg. What is the weight of the boy who left?', 'Total weight of 10 boys = 10 times 42 = 420. Total weight of remaining 9 boys = 9 times 41 = 369. Weight of the boy who left = 420 - 369 = 51 kg.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q207', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 206, 'Find the average of the first 20 natural numbers.', 'Sum of first n natural numbers = n times (n+1) divided by 2. For n = 20, sum = 20 times 21 divided by 2 = 210. Average = 210/20 = 10.5.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q208', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 207, 'A car covers a distance of 360 km in 6 hours. What is its speed in km/h?', 'Speed = Distance divided by Time = 360/6 = 60 km/h.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q209', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 208, 'A train 200 metres long crosses a platform 300 metres long in 25 seconds. What is the speed of the train in km/h?', 'Total distance covered = length of train plus length of platform = 200 + 300 = 500 metres. Speed = 500/25 = 20 m/s. Converting to km/h: 20 times (18/5) = 72 km/h.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q210', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 209, 'Two trains, each 125 metres long, are running in opposite directions at speeds of 40 km/h and 50 km/h. How long will they take to cross each other?', 'Relative speed (opposite directions) = 40 + 50 = 90 km/h = 90 times (5/18) = 25 m/s. Total distance to cover = 125 + 125 = 250 metres. Time = 250/25 = 10 seconds.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q211', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 210, 'A man walks at a speed of 5 km/h and covers a certain distance in 3 hours. If he increases his speed to 7.5 km/h, how much less time will he take to cover the same distance?', 'Distance = 5 times 3 = 15 km. Time at new speed = 15/7.5 = 2 hours. Time saved = 3 - 2 = 1 hour.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q212', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 211, 'A boat travels 36 km downstream in 2 hours and the same distance upstream in 3 hours. Find the speed of the boat in still water.', 'Downstream speed = 36/2 = 18 km/h. Upstream speed = 36/3 = 12 km/h. Speed in still water = (downstream speed plus upstream speed) divided by 2 = (18 + 12)/2 = 15 km/h.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q213', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 212, 'A train travelling at 54 km/h crosses a man standing on a platform in 12 seconds. What is the length of the train?', 'Speed in m/s = 54 times (5/18) = 15 m/s. Since the man is essentially a point object, length of train = speed times time = 15 times 12 = 180 metres.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q214', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 213, 'A train running at 90 km/h takes 20 seconds to completely cross a bridge 300 metres long. Find the length of the train.', 'Speed in m/s = 90 times (5/18) = 25 m/s. Total distance covered while crossing = speed times time = 25 times 20 = 500 metres. Length of train = total distance minus length of bridge = 500 - 300 = 200 metres.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q215', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 214, 'A cyclist covers a distance at a speed of 12 km/h and returns the same distance at 8 km/h. What is his average speed for the entire journey?', 'Average speed for equal distances = (2 times speed1 times speed2) divided by (speed1 plus speed2) = (2 times 12 times 8)/(12 + 8) = 192/20 = 9.6 km/h.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q216', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 215, 'A can complete a piece of work in 12 days and B can complete the same work in 18 days. In how many days can they complete the work together?', 'A''s one day work = 1/12. B''s one day work = 1/18. Combined one day work = 1/12 + 1/18 = 3/36 + 2/36 = 5/36. Time taken together = 36/5 = 7.2 days.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q217', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 216, 'A and B together can finish a job in 10 days. A alone can finish it in 15 days. In how many days can B alone finish the job?', 'Combined one day work = 1/10. A''s one day work = 1/15. B''s one day work = 1/10 - 1/15 = 3/30 - 2/30 = 1/30. So B alone takes 30 days.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q218', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 217, '15 workers can complete a wall in 8 days. How many days will 12 workers take to complete the same wall, assuming the same work rate per worker?', 'Total work = 15 times 8 = 120 worker-days. Days needed for 12 workers = 120/12 = 10 days.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q219', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 218, 'A can do a piece of work in 20 days. He worked for 4 days and then B finished the remaining work in 24 days. In how many days can B alone finish the entire work?', 'A''s one day work = 1/20. Work done by A in 4 days = 4/20 = 1/5. Remaining work = 1 - 1/5 = 4/5. B completes 4/5 of the work in 24 days, so B''s one day work = (4/5) divided by 24 = 4/120 = 1/30. Therefore B alone takes 30 days to finish the entire work.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q220', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 219, 'A, B, and C can complete a task in 10, 15, and 30 days respectively. If they all work together, in how many days will the task be completed?', 'One day work of A, B, and C combined = 1/10 + 1/15 + 1/30 = 3/30 + 2/30 + 1/30 = 6/30 = 1/5. So together they complete the task in 5 days.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q221', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 220, 'Find the area of a rectangle with length 18 cm and breadth 12 cm.', 'Area of rectangle = length times breadth = 18 times 12 = 216 square cm.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q222', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 221, 'Find the perimeter of a square with side 15 cm.', 'Perimeter of square = 4 times side = 4 times 15 = 60 cm.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q223', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 222, 'Find the area of a triangle with base 24 cm and height 10 cm.', 'Area of triangle = (1/2) times base times height = (1/2) times 24 times 10 = 120 square cm.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q224', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 223, 'Find the circumference of a circle with radius 14 cm. (Use pi = 22/7)', 'Circumference = 2 times pi times radius = 2 times (22/7) times 14 = 2 times 44 = 88 cm.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q225', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 224, 'Find the volume of a cube with side 6 cm.', 'Volume of cube = side times side times side = 6 times 6 times 6 = 216 cubic cm.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q226', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 225, 'Find the area of a circle with radius 7 cm. (Use pi = 22/7)', 'Area of circle = pi times radius times radius = (22/7) times 7 times 7 = 22 times 7 = 154 square cm.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q227', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 226, 'Find the volume of a cuboid with length 10 cm, breadth 5 cm, and height 4 cm.', 'Volume of cuboid = length times breadth times height = 10 times 5 times 4 = 200 cubic cm.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q228', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 227, 'The area of a trapezium is 180 square cm, with parallel sides of 15 cm and 25 cm. Find the height of the trapezium.', 'Area of trapezium = (1/2) times (sum of parallel sides) times height. So 180 = (1/2) times (15 + 25) times height = (1/2) times 40 times height = 20 times height. Therefore height = 180/20 = 9 cm.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q229', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 228, 'Find the LCM of 18 and 24.', '18 = 2 times 3 times 3, and 24 = 2 times 2 times 2 times 3. LCM takes the highest power of each prime factor: 2 times 2 times 2 times 3 times 3 = 8 times 9 = 72. So the LCM of 18 and 24 is 72.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q230', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 229, 'Find the HCF of 36 and 60.', '36 = 2 times 2 times 3 times 3, and 60 = 2 times 2 times 3 times 5. HCF takes the lowest power of common prime factors: 2 times 2 times 3 = 4 times 3 = 12. So the HCF of 36 and 60 is 12.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q231', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 230, 'What is the smallest number that, when divided by 12, 15, and 20, leaves no remainder in each case?', 'This is the LCM of 12, 15, and 20. 12 = 2 times 2 times 3, 15 = 3 times 5, 20 = 2 times 2 times 5. LCM = 2 times 2 times 3 times 5 = 4 times 3 times 5 = 60. So the smallest such number is 60.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q232', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 231, 'Is the number 4,536 divisible by 9? Explain using the divisibility rule.', 'The divisibility rule for 9 states that a number is divisible by 9 if the sum of its digits is divisible by 9. Sum of digits of 4536 = 4 + 5 + 3 + 6 = 18, and 18 is divisible by 9. Therefore 4536 is divisible by 9.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q233', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 232, 'Find the HCF and LCM of 15 and 20, and verify that their product equals the product of the two numbers.', '15 = 3 times 5, and 20 = 2 times 2 times 5. HCF = 5, and LCM = 2 times 2 times 3 times 5 = 60. Product of HCF and LCM = 5 times 60 = 300, and product of the two numbers = 15 times 20 = 300. Since both equal 300, the relationship HCF times LCM equals the product of the numbers is verified.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q234', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 233, 'Solve for x: 3x + 7 = 25.', '3x + 7 = 25. Subtracting 7 from both sides: 3x = 18. Dividing both sides by 3: x = 6.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q235', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 234, 'Solve for x: 5x - 9 = 2x + 15.', '5x - 9 = 2x + 15. Subtracting 2x from both sides: 3x - 9 = 15. Adding 9 to both sides: 3x = 24. Dividing by 3: x = 8.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q236', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 235, 'If 2x + 3y = 18 and x = 3, find the value of y.', 'Substituting x = 3 into the equation: 2 times 3 + 3y = 18, so 6 + 3y = 18. Subtracting 6 from both sides: 3y = 12. Dividing by 3: y = 4.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q237', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 236, 'The sum of two numbers is 45, and one number is twice the other. Find the two numbers.', 'Let the smaller number be x, so the larger number is 2x. Their sum is x + 2x = 3x = 45, so x = 15. The two numbers are 15 and 2 times 15 = 30.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q238', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 237, 'A bar chart shows the number of students who scored above 80% in four sections: Section A has 12, Section B has 18, Section C has 15, and Section D has 20. What percentage of the total such students belong to Section B?', 'Total students across all sections = 12 + 18 + 15 + 20 = 65. Percentage from Section B = (18/65) times 100, which is approximately 27.7%.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q239', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 238, 'A table shows monthly sales (in units) of a shop: January 200, February 250, March 300, April 350. What is the average monthly sales over these four months?', 'Total sales = 200 + 250 + 300 + 350 = 1100. Average monthly sales = 1100/4 = 275 units.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q240', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 239, 'In a pie chart representing a family''s monthly budget of Rs. 40,000, the Food sector occupies 90 degrees. How much money (in Rs.) is spent on food?', 'A full pie chart represents 360 degrees for the total amount. The fraction for Food = 90/360 = 1/4. Amount spent on food = (1/4) times 40000 = Rs. 10,000.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q241', 'railway-exam-bank', 'General Science', 3, 240, 'What is Newton''s First Law of Motion, and what common term describes the property it is based on?', 'Newton''s First Law states that an object at rest stays at rest, and an object in motion stays in motion at constant velocity, unless acted upon by an external force. This property of resisting a change in state of motion is called "inertia", and the law is often referred to as the Law of Inertia.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q242', 'railway-exam-bank', 'General Science', 3, 241, 'What is Newton''s Second Law of Motion, and what formula expresses it?', 'Newton''s Second Law states that the acceleration of an object is directly proportional to the net force acting on it and inversely proportional to its mass. It is expressed by the formula F = ma, where F is force, m is mass, and a is acceleration.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q243', 'railway-exam-bank', 'General Science', 3, 242, 'What is the difference between "mass" and "weight"?', 'Mass is the amount of matter in an object, measured in kilograms, and remains constant regardless of location. Weight is the force exerted on that mass due to gravity, measured in newtons, and varies depending on the strength of gravity at a given location (e.g., an object weighs less on the Moon than on Earth, though its mass stays the same).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q244', 'railway-exam-bank', 'General Science', 3, 243, 'What is the SI unit of force, and how is it defined?', 'The SI unit of force is the newton (N). One newton is defined as the force required to accelerate a mass of one kilogram at a rate of one metre per second squared (1 N = 1 kg times 1 m/s-squared).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q245', 'railway-exam-bank', 'General Science', 3, 244, 'What is Ohm''s Law, and what formula expresses the relationship between voltage, current, and resistance?', 'Ohm''s Law states that the current flowing through a conductor is directly proportional to the voltage across it, provided temperature remains constant. It is expressed as V = IR, where V is voltage, I is current, and R is resistance.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q246', 'railway-exam-bank', 'General Science', 3, 245, 'What is the difference between a series circuit and a parallel circuit?', 'In a series circuit, components are connected end-to-end along a single path, so the same current flows through all of them, and if one component fails, the entire circuit breaks. In a parallel circuit, components are connected across common points, providing multiple paths for current, so each component gets the same voltage and the circuit continues to function even if one branch fails.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q247', 'railway-exam-bank', 'General Science', 3, 246, 'What is the difference between a conductor and an insulator, with one example of each?', 'A conductor allows electric current (and heat) to flow through it easily because it has free-moving electrons, such as copper or aluminium. An insulator resists the flow of electric current because its electrons are tightly bound, such as rubber or glass.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q248', 'railway-exam-bank', 'General Science', 3, 247, 'What is static electricity, and how is it commonly generated?', 'Static electricity is the buildup of electric charge on the surface of an object, caused by an imbalance of electrons rather than a flow of current. It is commonly generated by friction between two materials, such as rubbing a balloon against hair, which transfers electrons from one surface to the other.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q249', 'railway-exam-bank', 'General Science', 3, 248, 'What is the SI unit of electric current, and what does it measure?', 'The SI unit of electric current is the ampere (A). It measures the rate of flow of electric charge past a point in a circuit, with one ampere equal to one coulomb of charge passing per second.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q250', 'railway-exam-bank', 'General Science', 3, 249, 'What is the difference between alternating current (AC) and direct current (DC)?', 'In direct current (DC), electric charge flows steadily in one direction only, as supplied by batteries. In alternating current (AC), the direction of current flow periodically reverses, which is the form of electricity supplied to homes and used in most power grids because it can be transmitted efficiently over long distances.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q251', 'railway-exam-bank', 'General Science', 3, 250, 'What is the difference between reflection and refraction of light?', 'Reflection occurs when light bounces off a surface and returns into the same medium, such as light reflecting off a mirror. Refraction occurs when light passes from one medium into another of different density (e.g., air to water) and bends due to a change in its speed.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q252', 'railway-exam-bank', 'General Science', 3, 251, 'What is the difference between a concave lens and a convex lens?', 'A convex lens is thicker at the centre than at the edges and converges (focuses) light rays to a point, commonly used to correct long-sightedness. A concave lens is thinner at the centre than at the edges and diverges light rays outward, commonly used to correct short-sightedness.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q253', 'railway-exam-bank', 'General Science', 3, 252, 'Why does the sky appear blue during the day?', 'The sky appears blue because of a phenomenon called Rayleigh scattering, in which shorter wavelengths of sunlight (blue and violet) are scattered more strongly by gas molecules in the atmosphere than longer wavelengths (red and orange). Since human eyes are more sensitive to blue than violet, the sky appears predominantly blue.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q254', 'railway-exam-bank', 'General Science', 3, 253, 'What is the approximate speed of light in a vacuum?', 'The speed of light in a vacuum is approximately 3 times 10 to the power 8 metres per second (about 300,000 kilometres per second), making it the fastest known speed in the universe, as described by Einstein''s theory of relativity.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q255', 'railway-exam-bank', 'General Science', 3, 254, 'Can sound travel through a vacuum? Why or why not?', 'Sound cannot travel through a vacuum because it is a mechanical wave that requires a physical medium (such as air, water, or a solid) to propagate, as it travels through the vibration of particles. Since a vacuum contains no particles, there is nothing to carry the vibration.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q256', 'railway-exam-bank', 'General Science', 3, 255, 'What is the SI unit of frequency, and what does it measure in the context of sound?', 'The SI unit of frequency is the hertz (Hz), which measures the number of complete wave cycles occurring per second. In sound, a higher frequency corresponds to a higher-pitched sound, while a lower frequency corresponds to a lower-pitched sound.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q257', 'railway-exam-bank', 'General Science', 3, 256, 'What is the difference between heat and temperature?', 'Heat is a form of energy that flows between objects due to a temperature difference, and depends on the amount of matter involved. Temperature is a measure of how hot or cold an object is, reflecting the average kinetic energy of its particles, regardless of the object''s size or amount of matter.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q258', 'railway-exam-bank', 'General Science', 3, 257, 'What are the three modes of heat transfer?', 'The three modes of heat transfer are conduction (heat transfer through direct contact between particles, as in a metal rod), convection (heat transfer through the movement of fluids like air or water), and radiation (heat transfer through electromagnetic waves, requiring no medium, such as heat from the Sun reaching Earth).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q259', 'railway-exam-bank', 'General Science', 3, 258, 'What is "specific heat capacity", and what does a higher value indicate?', 'Specific heat capacity is the amount of heat energy required to raise the temperature of one kilogram of a substance by one degree Celsius. A higher specific heat capacity means the substance can absorb more heat energy before its temperature rises significantly, which is why water (with a high specific heat capacity) heats up and cools down more slowly than metals.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q260', 'railway-exam-bank', 'General Science', 3, 259, 'What is a "lever", and what are its three main parts?', 'A lever is a simple machine consisting of a rigid bar that pivots around a fixed point to lift or move a load with less effort. Its three main parts are the fulcrum (the pivot point), the load (the object being moved), and the effort (the force applied to move the load).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q261', 'railway-exam-bank', 'General Science', 3, 260, 'What are the three basic sub-atomic particles that make up an atom, and what charge does each carry?', 'An atom consists of protons (positive charge) and neutrons (no charge, electrically neutral) located in the nucleus, and electrons (negative charge) that orbit the nucleus in shells. The number of protons determines the identity of the element.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q262', 'railway-exam-bank', 'General Science', 3, 261, 'What is the difference between "atomic number" and "mass number" of an element?', 'The atomic number is the number of protons in the nucleus of an atom, which uniquely identifies the element. The mass number is the total number of protons and neutrons combined in the nucleus.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q263', 'railway-exam-bank', 'General Science', 3, 262, 'What are "isotopes"?', 'Isotopes are atoms of the same element that have the same number of protons (and therefore the same atomic number) but a different number of neutrons, giving them different mass numbers. For example, Carbon-12 and Carbon-14 are both isotopes of carbon.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q264', 'railway-exam-bank', 'General Science', 3, 263, 'How is the modern periodic table organized?', 'The modern periodic table organizes elements in order of increasing atomic number, arranged into horizontal rows called "periods" and vertical columns called "groups", with elements in the same group sharing similar chemical properties due to having the same number of electrons in their outermost shell.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q265', 'railway-exam-bank', 'General Science', 3, 264, 'What is a "noble gas", and give one example.', 'A noble gas is an element from Group 18 of the periodic table that has a completely filled outermost electron shell, making it chemically inert (very unreactive) under normal conditions. Examples include helium, neon, and argon.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q266', 'railway-exam-bank', 'General Science', 3, 265, 'What do the terms "oxidation" and "reduction" mean in a chemical reaction?', 'Oxidation is a chemical process in which a substance loses electrons (or gains oxygen), while reduction is a process in which a substance gains electrons (or loses oxygen). These two processes always occur together in what is called a redox (reduction-oxidation) reaction.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q267', 'railway-exam-bank', 'General Science', 3, 266, 'What is a "catalyst" in a chemical reaction?', 'A catalyst is a substance that increases the rate of a chemical reaction without being permanently consumed or chemically altered in the process itself. It works by lowering the activation energy needed for the reaction to occur.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q268', 'railway-exam-bank', 'General Science', 3, 267, 'What type of chemical reaction causes the rusting of iron, and what two substances are required for it to occur?', 'Rusting is an oxidation reaction in which iron reacts with oxygen in the presence of moisture (water) to form iron oxide (rust). Both oxygen and water/moisture must be present for rusting to occur; iron does not rust in completely dry air.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q269', 'railway-exam-bank', 'General Science', 3, 268, 'What is the difference between an "element" and a "compound"?', 'An element is a pure substance made of only one type of atom and cannot be broken down into simpler substances by chemical means (e.g., oxygen, iron). A compound is a substance formed when two or more different elements chemically combine in a fixed ratio, and can only be separated back into its elements through a chemical reaction (e.g., water, made of hydrogen and oxygen).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q270', 'railway-exam-bank', 'General Science', 3, 269, 'What is the difference between a "compound" and a "mixture"?', 'A compound is formed when elements chemically combine in a fixed ratio, creating a new substance with different properties from its components, and can only be separated chemically. A mixture is formed when two or more substances are physically combined without a chemical reaction, retain their individual properties, and can usually be separated by physical methods like filtration or evaporation.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q271', 'railway-exam-bank', 'General Science', 3, 270, 'What is "hard water", and what commonly causes it?', 'Hard water is water that contains a high concentration of dissolved minerals, primarily calcium and magnesium salts, often picked up as water passes through limestone or chalk deposits underground. Hard water can reduce the lathering ability of soap and leave mineral deposits (scale) in pipes and kettles.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q272', 'railway-exam-bank', 'General Science', 3, 271, 'What are "allotropes", and give an example involving carbon?', 'Allotropes are different structural forms of the same element, where the atoms are arranged differently, giving each form distinct physical properties despite being made of identical atoms. Carbon has several allotropes, including diamond (atoms arranged in a rigid 3D lattice, making it extremely hard) and graphite (atoms arranged in flat, stacked layers, making it soft and a good conductor of electricity).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q273', 'railway-exam-bank', 'General Science', 3, 272, 'What is "combustion", and give an example of a common combustion reaction?', 'Combustion is a chemical reaction in which a substance reacts rapidly with oxygen, releasing heat and often light, and typically producing carbon dioxide and water when a carbon-based fuel is involved. A common example is the burning of natural gas (methane) in a stove, which combines with oxygen to produce carbon dioxide, water vapor, heat, and light.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q274', 'railway-exam-bank', 'General Science', 3, 273, 'What is the most abundant gas in Earth''s atmosphere?', 'Nitrogen is the most abundant gas in Earth''s atmosphere, making up about 78% of it by volume, followed by oxygen at about 21%, with the remaining 1% consisting of argon, carbon dioxide, and other trace gases.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q275', 'railway-exam-bank', 'General Science', 3, 274, 'What is the main chemical component of natural gas, commonly used as a fuel?', 'The main chemical component of natural gas is methane (CH4), a simple hydrocarbon that burns cleanly compared to many other fossil fuels and is widely used for heating, cooking, and electricity generation.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q276', 'railway-exam-bank', 'General Science', 3, 275, 'What is the common chemical name for baking soda, and what type of compound is it?', 'Baking soda is chemically known as sodium bicarbonate (NaHCO3). It is a mild alkaline (basic) compound commonly used in cooking as a leavening agent and in various household and industrial applications.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q277', 'railway-exam-bank', 'General Science', 3, 276, 'What is "electrolysis", and give one practical use of it?', 'Electrolysis is a process that uses electrical energy to drive a non-spontaneous chemical reaction, typically to decompose a compound into its constituent elements. A practical use is the electrolysis of water, which splits water molecules into hydrogen and oxygen gas using an electric current.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q278', 'railway-exam-bank', 'General Science', 3, 277, 'What is a "salt" in chemistry, and how is it typically formed?', 'In chemistry, a salt is an ionic compound formed when the hydrogen ion of an acid is replaced by a metal ion (or ammonium ion), typically produced through a neutralization reaction between an acid and a base. Common table salt, sodium chloride, is formed from the reaction of hydrochloric acid and sodium hydroxide.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q279', 'railway-exam-bank', 'General Science', 3, 278, 'What is the main function of the human heart?', 'The human heart is a muscular organ that pumps blood throughout the body via the circulatory system, delivering oxygen and nutrients to tissues and removing waste products like carbon dioxide, by rhythmically contracting and relaxing its four chambers.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q280', 'railway-exam-bank', 'General Science', 3, 279, 'What is the largest organ of the human body?', 'The skin is the largest organ of the human body. It serves as a protective barrier against pathogens and physical damage, helps regulate body temperature, and contains sensory receptors for touch, pressure, and temperature.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q281', 'railway-exam-bank', 'General Science', 3, 280, 'What is "photosynthesis", and what are its main inputs and outputs?', 'Photosynthesis is the process by which green plants, algae, and some bacteria convert light energy into chemical energy, using carbon dioxide and water as inputs (in the presence of sunlight and chlorophyll) to produce glucose and oxygen as outputs.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q282', 'railway-exam-bank', 'General Science', 3, 281, 'What is "cellular respiration", and how does it relate to photosynthesis?', 'Cellular respiration is the process by which cells break down glucose in the presence of oxygen to release energy (ATP), producing carbon dioxide and water as byproducts. It is essentially the reverse of photosynthesis, which uses carbon dioxide and water to produce glucose and oxygen.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q283', 'railway-exam-bank', 'General Science', 3, 282, 'What is the main function of the kidneys in the human body?', 'The kidneys filter waste products, excess salts, and excess water from the blood to form urine, helping regulate the body''s fluid balance, electrolyte levels, and blood pressure, while retaining essential substances like proteins and glucose back into the bloodstream.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q284', 'railway-exam-bank', 'General Science', 3, 283, 'What is the main function of the liver in the human body?', 'The liver performs many vital functions, including detoxifying harmful substances from the blood, producing bile to aid in fat digestion, storing glucose as glycogen for energy regulation, and synthesizing essential proteins such as those involved in blood clotting.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q285', 'railway-exam-bank', 'General Science', 3, 284, 'What is the smallest structural and functional unit of life?', 'The cell is the smallest structural and functional unit of life. All living organisms are composed of one or more cells, and cells carry out all the basic processes necessary for life, such as metabolism, growth, and reproduction.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q286', 'railway-exam-bank', 'General Science', 3, 285, 'What is "DNA", and what is its primary role in living organisms?', 'DNA (deoxyribonucleic acid) is a molecule that carries the genetic instructions used for the growth, development, functioning, and reproduction of all known living organisms. It is structured as a double helix and is passed from parents to offspring, determining inherited traits.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q287', 'railway-exam-bank', 'General Science', 3, 286, 'What is a "vaccine", and how does it generally work to protect against disease?', 'A vaccine is a biological preparation that trains the immune system to recognize and fight a specific pathogen (such as a virus or bacterium), typically by introducing a weakened, inactivated, or partial form of the pathogen (or genetic material encoding part of it). This exposure prompts the immune system to produce antibodies and immune memory cells, so the body can respond quickly if it encounters the real pathogen later.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q288', 'railway-exam-bank', 'General Science', 3, 287, 'What is the main function of white blood cells (leukocytes) in the human body?', 'White blood cells are a key part of the immune system, responsible for identifying, attacking, and destroying pathogens such as bacteria, viruses, and other foreign invaders, as well as helping to clear damaged or abnormal cells from the body.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q289', 'railway-exam-bank', 'General Science', 3, 288, 'What is the role of chlorophyll in plants?', 'Chlorophyll is a green pigment found in plant cells, primarily in chloroplasts, that absorbs light energy (especially red and blue wavelengths) needed to drive the process of photosynthesis. It gives plants their characteristic green color because it reflects green light rather than absorbing it.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q290', 'railway-exam-bank', 'General Science', 3, 289, 'What is "osteoporosis", and which mineral deficiency is commonly associated with it?', 'Osteoporosis is a medical condition in which bones become weak, brittle, and more prone to fractures due to a loss of bone density and mass. It is commonly associated with a deficiency of calcium (and vitamin D, which helps the body absorb calcium) over time, and is particularly common in older adults, especially post-menopausal women.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q291', 'railway-exam-bank', 'General Science', 3, 290, 'What is "diabetes mellitus", in basic terms?', 'Diabetes mellitus is a chronic medical condition in which the body is unable to properly regulate blood glucose (sugar) levels, either because the pancreas does not produce enough insulin (Type 1) or because the body''s cells do not respond effectively to insulin (Type 2), leading to persistently high blood sugar levels.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q292', 'railway-exam-bank', 'General Science', 3, 291, 'What is a "neuron", and what is its basic function in the nervous system?', 'A neuron is a specialized nerve cell that transmits electrical and chemical signals throughout the body, forming the basic building block of the nervous system. Neurons carry information between the brain, spinal cord, and the rest of the body, enabling sensation, movement, and thought.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q293', 'railway-exam-bank', 'General Science', 3, 292, 'What vitamin deficiency causes the disease "scurvy", and what are its characteristic symptoms?', 'Scurvy is caused by a deficiency of Vitamin C (ascorbic acid), which is essential for collagen synthesis in the body. Characteristic symptoms include bleeding and swollen gums, joint pain, fatigue, and slow wound healing, since collagen is needed to maintain healthy skin, blood vessels, and connective tissue.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q294', 'railway-exam-bank', 'General Science', 3, 293, 'What is the main function of the human lungs?', 'The lungs are the primary organs of the respiratory system, responsible for the exchange of gases — taking in oxygen from inhaled air and releasing carbon dioxide (a waste product of cellular respiration) from the blood into the air that is exhaled.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q295', 'railway-exam-bank', 'General Science', 3, 294, 'What is "transpiration" in plants?', 'Transpiration is the process by which water absorbed by a plant''s roots evaporates as water vapor, mainly through small pores called stomata on the surface of leaves. It helps the plant draw water and dissolved minerals upward from the roots and also contributes to cooling the plant.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q296', 'railway-exam-bank', 'General Science', 3, 295, 'What are "antibodies", and what role do they play in the immune system?', 'Antibodies are Y-shaped proteins produced by specialized white blood cells called B-cells, designed to specifically recognize and bind to a particular foreign substance (antigen), such as a virus or bacterium. Once bound, antibodies help neutralize the pathogen directly or mark it for destruction by other components of the immune system.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q297', 'railway-exam-bank', 'General Science', 3, 296, 'What is the difference between a "herbivore", a "carnivore", and an "omnivore"?', 'A herbivore is an animal that feeds exclusively on plants (e.g., a cow). A carnivore is an animal that feeds exclusively on other animals (e.g., a tiger). An omnivore feeds on both plants and animals as part of its regular diet (e.g., humans and bears).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q298', 'railway-exam-bank', 'General Science', 3, 297, 'What is "pasteurization", and what is its purpose?', 'Pasteurization is a process that heats a liquid, typically milk, to a specific temperature for a set period of time and then rapidly cools it, in order to kill harmful bacteria and pathogens without significantly affecting taste or nutritional value. It was named after the French scientist Louis Pasteur, who developed the technique.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q299', 'railway-exam-bank', 'General Science', 3, 298, 'What is an "alloy", and give one common example?', 'An alloy is a mixture of two or more elements, where at least one is a metal, combined to produce a material with enhanced properties such as greater strength, hardness, or resistance to corrosion compared to the individual metals alone. A common example is steel, an alloy of iron and carbon.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q300', 'railway-exam-bank', 'General Science', 3, 299, 'What are the three main functions of the human skeletal system?', 'The human skeletal system provides structural support for the body, protects vital internal organs (such as the skull protecting the brain and the rib cage protecting the heart and lungs), and works together with muscles to enable movement by acting as attachment points and levers.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q031', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 30, 'What is Thorndike''s "Law of Effect," and what does it state about learning?', 'Thorndike''s Law of Effect states that responses followed by a satisfying consequence are strengthened and more likely to be repeated, while responses followed by an annoying or dissatisfying consequence are weakened and less likely to recur. It laid the foundation for later reinforcement-based theories of learning, including Skinner''s operant conditioning.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q032', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 31, 'What is Thorndike''s "Law of Exercise," and what does it imply for classroom practice?', 'The Law of Exercise states that connections between a stimulus and a response are strengthened through repeated practice and weakened through disuse. In the classroom, this implies that regular drill, revision, and practice help consolidate learned skills, while skills not practiced over time tend to fade.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q033', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 32, 'What is Thorndike''s "Law of Readiness," and what does it mean for teaching?', 'The Law of Readiness states that learning occurs most effectively when a learner is physically and mentally prepared to act, and that forcing a learner to perform an action they are not ready for, or preventing them from acting when they are ready, causes frustration or dissatisfaction. It implies teachers should assess a student''s readiness before introducing new content.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q034', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 33, 'What is "trial and error learning," as described by Thorndike''s experiments with cats in a puzzle box?', 'Trial and error learning describes a process where a learner attempts multiple random responses to a problem, gradually eliminating ineffective ones and repeating effective ones, until the correct response is learned. Thorndike observed this in cats escaping a puzzle box, where successful escape responses were gradually learned through repeated trials rather than sudden insight.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q035', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 34, 'What is Thorndike''s theory of "connectionism," in brief?', 'Connectionism is Thorndike''s theory that learning is fundamentally the formation and strengthening of direct connections (bonds) between a specific stimulus and a specific response, shaped primarily through the consequences that follow a response, rather than through reasoning or insight.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q036', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 35, 'How is Thorndike''s work on reward and consequence relevant to classroom reinforcement practices today?', 'Thorndike''s findings that rewarded responses are strengthened directly underpin modern classroom use of praise, grades, and privileges as reinforcers to encourage desired academic and behavioral responses, forming an early theoretical basis for the reinforcement strategies teachers use to shape student behavior.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q037', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 36, 'What is a "continuous reinforcement schedule" in operant conditioning, and what is its main drawback?', 'A continuous reinforcement schedule rewards every correct response without exception. While it produces the fastest initial learning, behavior reinforced this way extinguishes quickly once reinforcement stops, because the learner immediately notices the absence of the expected reward.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q038', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 37, 'What is a "fixed ratio schedule" of reinforcement, and give a classroom example.', 'A fixed ratio schedule provides reinforcement after a set, unchanging number of correct responses (e.g., every 5th correct answer). A classroom example is giving a student a sticker after completing every 10 practice problems.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q039', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 38, 'What is a "variable ratio schedule" of reinforcement, and why does it produce the highest resistance to extinction?', 'A variable ratio schedule provides reinforcement after an unpredictable number of responses, varying around an average. It produces the highest resistance to extinction because the learner cannot predict exactly when reinforcement will come, so they keep responding steadily even through periods without reward, similar to the pattern seen in gambling behavior.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q040', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 39, 'What is a "fixed interval schedule" of reinforcement, and give a classroom example.', 'A fixed interval schedule provides reinforcement for the first correct response after a set, unchanging amount of time has passed. A classroom example is a weekly spelling test given every Friday regardless of how many times a student has practiced during the week.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q041', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 40, 'What is a "variable interval schedule" of reinforcement, and how does response rate under it typically behave?', 'A variable interval schedule provides reinforcement for the first correct response after an unpredictable amount of time has passed, varying around an average. It typically produces a steady, moderate rate of responding, since the learner cannot predict exactly when the next opportunity for reinforcement will occur.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q042', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 41, 'Among the four partial reinforcement schedules, which type generally shows the greatest resistance to extinction, and why?', 'Ratio schedules (especially variable ratio) generally show greater resistance to extinction than interval schedules, because reinforcement under a ratio schedule depends directly on the number of responses made, encouraging a high, steady rate of responding that persists even when reinforcement becomes irregular.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q043', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 42, 'What is the difference between reinforcement and punishment in operant conditioning terms, focusing on their effect on future behavior?', 'Reinforcement (positive or negative) increases the likelihood that a behavior will be repeated in the future. Punishment, in contrast, decreases the likelihood that a behavior will be repeated, by introducing an unpleasant consequence or removing a pleasant one following the behavior.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q044', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 43, 'What is "shaping" in operant conditioning, and how might a teacher use it to teach a complex skill?', 'Shaping is the process of reinforcing successive approximations toward a desired target behavior, gradually raising the standard required for reinforcement as the learner''s behavior gets closer to the goal. A teacher might use shaping to teach a child to write neatly by first rewarding any attempt to hold the pencil correctly, then rewarding legible letters, and finally rewarding properly formed words.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q045', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 44, 'What are the three levels of Kohlberg''s theory of moral development, in order?', 'Kohlberg''s three levels, in order of development, are: Pre-conventional morality (based on consequences to oneself), Conventional morality (based on social rules and approval), and Post-conventional morality (based on abstract ethical principles that may transcend specific laws).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q046', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 45, 'What characterizes Stage 1 of Kohlberg''s pre-conventional level, the "obedience and punishment orientation"?', 'In this stage, a person judges the morality of an action based on its direct physical consequences for themselves, particularly whether it leads to punishment. Rules are obeyed simply to avoid being punished, without any understanding of the broader social reasons behind the rule.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q047', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 46, 'What characterizes Stage 2 of Kohlberg''s pre-conventional level, the "instrumental exchange orientation"?', 'In this stage, a person follows rules when it serves their own immediate interests, and understands morality in terms of fair exchange — "you scratch my back, I''ll scratch yours" — rather than loyalty, gratitude, or justice in a broader sense.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q048', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 47, 'What characterizes Stage 3 of Kohlberg''s conventional level, often called the "good boy/good girl orientation"?', 'In this stage, a person seeks to live up to the expectations of others close to them (family, peers) and values being seen as good, trustworthy, and loyal, judging actions as moral if they earn approval and maintain good relationships.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q049', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 48, 'What characterizes Stage 4 of Kohlberg''s conventional level, the "law and order orientation"?', 'In this stage, a person believes in maintaining social order by following laws, rules, and authority, viewing moral behavior as fulfilling one''s duties and obligations to society as a whole, regardless of personal relationships involved.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q050', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 49, 'What characterizes Stage 5 of Kohlberg''s post-conventional level, the "social contract orientation"?', 'In this stage, a person recognizes that laws are social agreements that can be changed through democratic processes if they no longer serve the greater good, and understands that individual rights can sometimes take precedence over rigid rule-following.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q051', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 50, 'What characterizes Stage 6 of Kohlberg''s post-conventional level, the "universal ethical principles orientation"?', 'In this stage, a person''s moral reasoning is guided by self-chosen, abstract ethical principles such as justice, equality, and human dignity, which are considered valid even if they conflict with specific written laws. Kohlberg considered this the rarest and highest stage of moral reasoning.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q052', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 51, 'What is the "Heinz dilemma," and why is it significant to Kohlberg''s research?', 'The Heinz dilemma is a hypothetical moral scenario in which a man named Heinz must decide whether to steal an unaffordable drug to save his dying wife. Kohlberg used responses to this dilemma not to judge whether stealing was right or wrong, but to analyze the underlying reasoning behind the answer, which revealed the respondent''s stage of moral development.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q053', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 52, 'What is a major criticism raised against Kohlberg''s theory of moral development?', 'A major criticism, notably raised by Carol Gilligan, is that Kohlberg''s theory was developed primarily from research on male subjects and may reflect a justice-based orientation to morality, potentially undervaluing a care-and-relationship-based orientation to moral reasoning that Gilligan argued was more common among women.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q054', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 53, 'How can Kohlberg''s theory of moral development be applied in classroom moral education?', 'Teachers can use moral dilemmas and classroom discussions to encourage students to reason through the consequences and principles involved in ethical decisions, gradually guiding them toward higher stages of moral reasoning by exposing them to perspectives slightly more advanced than their current stage.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q055', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 54, 'What is Bruner''s concept of "discovery learning"?', 'Discovery learning is an approach where students are encouraged to actively explore, investigate, and discover concepts and relationships for themselves, through guided exploration and problem-solving, rather than being given information directly by the teacher through lecture or explanation.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q056', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 55, 'What is Bruner''s concept of the "spiral curriculum"?', 'The spiral curriculum is Bruner''s idea that complex concepts should be introduced to students in a simplified, age-appropriate form early in their education, and then revisited at increasing levels of depth and complexity as the student matures, reinforcing and deepening understanding over time rather than teaching a topic only once.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q057', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 56, 'What are Bruner''s three modes of representation through which learners understand and store information?', 'Bruner proposed three modes of representation: the enactive mode (learning through physical action), the iconic mode (learning through visual images or icons), and the symbolic mode (learning through abstract symbols such as language and mathematical notation).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q058', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 57, 'What is the "enactive mode" of representation in Bruner''s theory, and give a classroom example?', 'The enactive mode involves representing knowledge through physical action and direct manipulation of objects. A classroom example is a young child learning the concept of addition by physically combining groups of counting blocks rather than through numbers alone.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q059', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 58, 'What is the "iconic mode" of representation in Bruner''s theory, and give a classroom example?', 'The iconic mode involves representing knowledge through visual images, pictures, or diagrams without needing physical manipulation. A classroom example is a student understanding fractions by looking at a picture of a pizza divided into slices.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q060', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 59, 'What is the "symbolic mode" of representation in Bruner''s theory, and give a classroom example?', 'The symbolic mode involves representing knowledge through abstract symbols such as words, numbers, and mathematical notation, independent of direct physical or visual representation. A classroom example is a student solving an algebraic equation using only symbols and numerals.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q061', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 60, 'How does Bruner''s view of cognitive development differ from Piaget''s view regarding the role of instruction?', 'While Piaget believed cognitive development follows a relatively fixed sequence of stages that cannot be significantly accelerated by teaching, Bruner argued that any subject can be taught effectively to a child at any stage of development if the content is structured appropriately for that child''s current mode of representation, giving instruction a more central, active role in shaping cognitive growth.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q062', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 61, 'How does the concept of "scaffolding" appear in Bruner''s work, distinct from its use by Vygotsky?', 'Bruner is credited with coining the specific term "scaffolding," building on Vygotsky''s broader concept of guided support within the Zone of Proximal Development, to describe the specific structured, temporary assistance (such as prompts, demonstrations, or simplified tasks) a more knowledgeable person provides to help a learner accomplish what they could not yet do independently.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q063', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 62, 'What is "information processing theory," in brief, as applied to human learning?', 'Information processing theory models the human mind as working similarly to a computer, processing information through a sequence of stages — input (sensory reception), processing (attention, encoding, storage), and output (retrieval and response) — to explain how people perceive, learn, remember, and use information.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q064', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 63, 'What is the "sensory register" (or sensory memory) in information processing theory?', 'The sensory register is the initial, very brief stage of memory that holds incoming sensory information (what we see, hear, etc.) for a fraction of a second to a few seconds, just long enough for the brain to decide whether the information is worth paying attention to and passing on to working memory.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q065', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 64, 'What is "working memory" (short-term memory), and what is its typical capacity according to Miller''s research?', 'Working memory is the temporary mental workspace where information is actively held and manipulated for ongoing tasks, such as following instructions or solving a problem. George Miller''s classic research suggested its capacity is approximately "seven plus or minus two" items, though this can be effectively expanded through chunking.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q066', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 65, 'How is information encoded into long-term memory, according to information processing theory?', 'Information is encoded into long-term memory through processes such as rehearsal (repetition), elaboration (connecting new information to existing knowledge), and organization (structuring information meaningfully), with deeper, more meaningful processing generally leading to stronger, more durable long-term retention.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q067', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 66, 'What role does "attention" play as a filter in information processing theory?', 'Attention acts as a selective filter that determines which sensory information is passed from the sensory register into working memory for further processing, while unattended information is quickly lost; this means a learner''s attention level directly limits how much of the available information can ever be learned.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q068', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 67, 'What is "chunking," and how does it help overcome the limited capacity of working memory?', 'Chunking is the strategy of grouping individual pieces of information into larger, meaningful units, so that a single "chunk" can hold more underlying information while still counting as one item within working memory''s limited capacity. For example, remembering a 10-digit number as grouped sets (like a phone number) rather than 10 separate digits.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q069', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 68, 'What are the three main stages involved in memory processing, as described by information processing theory?', 'The three main stages are encoding (converting information into a form that can be stored), storage (retaining the encoded information over time), and retrieval (accessing and bringing stored information back into conscious awareness when needed).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q070', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 69, 'What is "metacognitive monitoring," and how does it relate to information processing during learning?', 'Metacognitive monitoring is the ongoing self-awareness and self-checking a learner does regarding their own understanding and progress while processing information, such as recognizing when they do not understand a concept and need to re-read or ask for clarification, allowing more efficient and self-regulated learning.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q071', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 70, 'What is Maslow''s "hierarchy of needs," and how is it structured?', 'Maslow''s hierarchy of needs is a theory proposing that human needs are organized into a pyramid of five levels — physiological, safety, belongingness/love, esteem, and self-actualization — and that lower-level, more basic needs generally must be adequately satisfied before a person is strongly motivated to pursue higher-level needs.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q072', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 71, 'How do unmet "physiological needs" affect a student''s ability to learn in the classroom?', 'Physiological needs include hunger, thirst, and sleep. A student who is hungry or exhausted will struggle to concentrate on academic tasks, since their basic bodily needs are unmet and take priority over higher-level cognitive engagement, which is why many schools provide meals or address basic physical needs before instruction.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q073', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 72, 'How do unmet "safety needs" affect a student''s engagement in the classroom?', 'Safety needs include physical safety and emotional security. A student who feels physically unsafe (due to bullying) or emotionally insecure (due to an unpredictable or harsh classroom environment) will be preoccupied with self-protection rather than being able to focus fully on learning tasks.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q074', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 73, 'How do "belongingness and love needs" affect a student''s motivation to learn?', 'Belongingness needs involve feeling accepted, connected, and valued by peers and teachers. A student who feels isolated or rejected by classmates may disengage from classroom participation, while a strong sense of belonging tends to increase willingness to take academic risks and participate actively.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q075', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 74, 'How do "esteem needs" relate to a student''s classroom behavior and motivation?', 'Esteem needs involve the desire for self-respect, confidence, and recognition from others. A student whose esteem needs are met through earned achievement and genuine positive feedback tends to show greater confidence and persistence, while one whose esteem needs are unmet may avoid challenges to protect themselves from failure.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q076', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 75, 'What is "self-actualization" at the top of Maslow''s hierarchy, and what might it look like in an educational context?', 'Self-actualization is the realization of one''s full potential and the pursuit of personal growth, creativity, and meaningful achievement for its own sake. In an educational context, it might look like a student pursuing a subject deeply out of genuine intellectual curiosity and a desire to fulfill their own capabilities, rather than for grades or approval.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q077', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 76, 'What is the difference between "deficiency needs" and "growth needs" in Maslow''s theory?', 'Deficiency needs (physiological, safety, belongingness, esteem) arise from a lack of something and motivate a person to eliminate the deficiency; once satisfied, the motivation to pursue them typically decreases. Growth needs (self-actualization) are not based on a lack but on a desire for personal fulfillment, and satisfying them tends to increase rather than decrease motivation to pursue them further.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q078', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 77, 'Why is understanding Maslow''s hierarchy important for a teacher trying to improve a struggling student''s academic performance?', 'Understanding the hierarchy helps a teacher recognize that a student struggling academically may actually have an unmet lower-level need (hunger, insecurity, lack of belonging) rather than a purely academic or motivational problem, directing the teacher to first address the underlying need before expecting improved engagement with academic content.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q079', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 78, 'What is the central idea of Carl Rogers'' "student-centered" (or "learner-centered") approach to education?', 'Rogers'' student-centered approach proposes that learning is most effective when it is self-directed and personally meaningful to the learner, with the teacher acting as a facilitator who creates a supportive environment rather than a figure who simply transmits information to a passive recipient.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q080', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 79, 'What is "unconditional positive regard," as described by Carl Rogers, and why is it important in an educational setting?', 'Unconditional positive regard means accepting and valuing a person regardless of what they do or say, without attaching conditions to that acceptance. In an educational setting, a teacher showing unconditional positive regard helps students feel safe to express themselves, make mistakes, and take intellectual risks without fear of losing the teacher''s approval.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q081', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 80, 'What is Carl Rogers'' concept of "self-concept," and how does it relate to learning?', 'Self-concept is a person''s overall perception and evaluation of themselves, including their abilities, worth, and identity. Rogers believed that a positive, accurate self-concept supports healthy psychological functioning and openness to learning, while a threatened or negative self-concept can cause a person to become defensive and resistant to new experiences or feedback.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q082', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 81, 'According to Rogers, what is the role of a teacher as a "facilitator" rather than an instructor?', 'As a facilitator, a teacher creates the conditions for learning — providing resources, genuine acceptance, and a non-threatening environment — and guides students'' own self-directed exploration, rather than dictating exactly what and how students must learn through direct, one-way instruction.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q083', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 82, 'What is "experiential learning," as emphasized in Rogers'' humanistic approach to education?', 'Experiential learning is learning that engages the whole person — intellectually and emotionally — through direct, personally relevant experience, which Rogers considered more significant and longer-lasting than learning acquired only through passive listening or rote memorization disconnected from personal meaning.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q084', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 83, 'How does Rogers'' humanistic, student-centered approach differ fundamentally from a traditional teacher-centered approach?', 'A traditional teacher-centered approach positions the teacher as the primary authority and source of knowledge, with students largely receiving and reproducing information. Rogers'' humanistic approach instead centers the student''s own interests, self-direction, and emotional experience, with the teacher supporting rather than directing the learning process.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q085', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 84, 'What is McClelland''s "achievement motivation theory," in brief?', 'McClelland''s theory proposes that individuals differ in their underlying need for achievement — a stable personality characteristic reflecting a person''s drive to accomplish challenging goals, attain standards of excellence, and succeed in competitive situations, which influences the kinds of tasks and risks they are motivated to pursue.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q086', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 85, 'What is Bandura''s concept of "self-efficacy," and how does it affect a student''s academic performance?', 'Self-efficacy is a person''s belief in their own ability to successfully perform a specific task or achieve a specific goal. Students with high self-efficacy in a subject tend to persist longer through difficulty, set more challenging goals, and perform better, while low self-efficacy can lead to avoidance of challenging tasks even when the student has the actual ability to succeed.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q087', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 86, 'What is Bandura''s "social learning theory" (observational learning), and what are its key stages?', 'Social learning theory proposes that people learn new behaviors by observing and imitating others (models), rather than only through direct reinforcement of their own actions. Its key stages are attention (noticing the model''s behavior), retention (remembering what was observed), reproduction (physically performing the observed behavior), and motivation (having a reason to perform it).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q088', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 87, 'What is "locus of control," and how does an internal versus external locus differ in a classroom context?', 'Locus of control refers to the degree to which a person believes they control the outcomes in their life. A student with an internal locus of control believes their own effort and ability determine their academic results, while a student with an external locus of control attributes their results mainly to luck, task difficulty, or other people, which can reduce motivation to try harder.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q089', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 88, 'What is "attribution theory" (Weiner), and what are two common dimensions used to classify the causes people attribute to success or failure?', 'Attribution theory examines how people explain the causes of their successes and failures. Weiner proposed that these causal attributions can be classified along dimensions including locus (internal vs. external cause), stability (whether the cause is likely to change over time), and controllability (whether the person could control the cause), which together shape future motivation and emotional response.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q090', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 89, 'What are the three basic psychological needs proposed by "Self-Determination Theory" as essential for intrinsic motivation?', 'Self-Determination Theory proposes that intrinsic motivation flourishes when three basic psychological needs are satisfied: autonomy (feeling in control of one''s own actions and choices), competence (feeling capable and effective), and relatedness (feeling connected to and supported by others).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q091', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 90, 'What is "expectancy-value theory" of motivation, in brief?', 'Expectancy-value theory proposes that a person''s motivation to engage in a task depends on two factors multiplied together: their expectancy of success (how likely they believe they are to succeed) and the value they place on the task (how important, interesting, or useful they consider it to be) — if either factor is very low, overall motivation tends to be low.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q092', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 91, 'What is the difference between "need for achievement" and "need to avoid failure" as motivational orientations?', 'A person with a high need for achievement is primarily driven by the positive pursuit of success and mastery, often seeking moderately challenging tasks that provide a real sense of accomplishment. A person with a high need to avoid failure is primarily driven by fear of failing or being judged negatively, often avoiding challenging tasks altogether or choosing tasks that are either very easy or unrealistically difficult to minimize personal responsibility for failure.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q093', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 92, 'What are the three main types of memory typically distinguished in memory research, based on duration and capacity?', 'The three main types are sensory memory (very brief, high-capacity initial registration of stimuli), short-term/working memory (limited capacity, holds information for seconds to about a minute during active use), and long-term memory (relatively unlimited capacity, capable of storing information for extended periods, potentially a lifetime).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q094', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 93, 'What is the difference between "episodic memory" and "semantic memory," both types of long-term memory?', 'Episodic memory stores memories of specific personal experiences and events tied to a particular time and place (e.g., remembering your first day of school). Semantic memory stores general factual knowledge and concepts independent of when or where they were learned (e.g., knowing that Delhi is the capital of India).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q095', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 94, 'What is "procedural memory," and give an example relevant to a student?', 'Procedural memory is long-term memory for how to perform skills and actions, often performed automatically without conscious recall of the specific learning process. An example relevant to a student is remembering how to type on a keyboard or ride a bicycle, skills that, once learned, are performed largely without deliberate step-by-step thought.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q096', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 95, 'What is "decay theory" as an explanation for forgetting?', 'Decay theory proposes that memories fade and eventually disappear over time simply due to the natural, gradual weakening of the memory trace if it is not used or reinforced, similar to how an unused path in a forest gradually becomes overgrown.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q097', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 96, 'What is "interference theory" as an explanation for forgetting, and what is the difference between proactive and retroactive interference?', 'Interference theory proposes that forgetting occurs because other memories compete with and disrupt the one being recalled. Proactive interference occurs when older, previously learned information disrupts the recall of newly learned information; retroactive interference occurs when newly learned information disrupts the recall of older, previously learned information.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q098', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 97, 'What is "retrieval failure" as an explanation for forgetting, and how does it differ from information being permanently lost?', 'Retrieval failure proposes that forgetting often occurs not because information has been erased from memory, but because the correct cues needed to access that stored information are missing or inadequate at the moment of recall — the information is still technically present but temporarily inaccessible, as shown by cases where a forgotten memory suddenly returns when a helpful cue is encountered later.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q099', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 98, 'What are the "primacy effect" and "recency effect" in memory, and how do they together explain the "serial position effect"?', 'The primacy effect is the tendency to better remember items presented at the beginning of a list, because they have had more time to be rehearsed into long-term memory. The recency effect is the tendency to better remember items presented at the end of a list, because they are still fresh in working memory. Together, these two effects explain the serial position effect, in which items in the middle of a list are typically remembered least well.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q100', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 99, 'What are "mnemonic devices," and give one common example used by students.', 'Mnemonic devices are memory aids or strategies that help encode information in a more memorable form, often by creating associations, patterns, or imagery. A common example is an acronym, such as using "VIBGYOR" to remember the colors of the rainbow in order (Violet, Indigo, Blue, Green, Yellow, Orange, Red).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q101', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 100, 'What is Spearman''s "two-factor theory" of intelligence, and what do the "g" and "s" factors represent?', 'Spearman''s two-factor theory proposes that intelligence consists of a general factor, "g," which underlies performance across all cognitive tasks, and specific factors, "s," which are unique abilities relevant only to particular tasks or domains. According to this theory, a person''s overall intellectual performance reflects a combination of their general intelligence and their specific abilities in a given area.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q102', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 101, 'What is Thurstone''s "theory of primary mental abilities," and how does it differ from Spearman''s theory?', 'Thurstone''s theory proposes that intelligence consists of seven distinct, relatively independent primary mental abilities (such as verbal comprehension, numerical ability, and spatial visualization) rather than a single general factor. This differs from Spearman''s theory, which emphasized one overarching general intelligence factor underlying performance across all tasks.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q103', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 102, 'What is Sternberg''s "triarchic theory of intelligence," and what are its three components?', 'Sternberg''s triarchic theory proposes that intelligence consists of three components: analytical intelligence (problem-solving and logical reasoning ability), creative intelligence (the ability to deal with novel situations and generate original ideas), and practical intelligence (the ability to apply knowledge effectively to real-world, everyday situations).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q104', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 103, 'What is the difference between "fluid intelligence" and "crystallized intelligence," as proposed by Cattell?', 'Fluid intelligence is the capacity to reason and solve novel problems independently of previously acquired knowledge, and tends to decline somewhat with age. Crystallized intelligence is accumulated knowledge, skills, and vocabulary gained through experience and education, and tends to remain stable or even increase with age.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q105', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 104, 'What is "emotional intelligence," as popularized by Daniel Goleman, and why is it relevant to classroom success?', 'Emotional intelligence is the ability to recognize, understand, and manage one''s own emotions, as well as recognize and respond appropriately to the emotions of others. It is relevant to classroom success because students with higher emotional intelligence tend to manage frustration and stress better, build more positive relationships with peers and teachers, and show better overall social and academic adjustment.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q106', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 105, 'What are the three common categories in the "VAK" model of learning styles?', 'The VAK model categorizes learners as predominantly Visual (learning best through images, diagrams, and written text), Auditory (learning best through listening and verbal discussion), or Kinesthetic (learning best through physical movement, hands-on activity, and direct experience).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q107', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 106, 'What is a major criticism of popular "learning styles" theories like VAK, from an educational research perspective?', 'A major criticism is that despite the theory''s popularity among teachers, rigorous research has found little to no solid scientific evidence that matching instruction specifically to a student''s self-identified preferred learning style actually improves learning outcomes compared to using varied, multi-modal teaching methods for all students regardless of stated preference.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q108', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 107, 'What is the difference between "field-dependent" and "field-independent" cognitive styles?', 'Field-dependent learners tend to perceive and interpret information holistically, influenced by the surrounding context, and often prefer working with others and receiving external guidance. Field-independent learners tend to perceive and analyze information by separating it from its surrounding context, and often prefer working independently and structuring their own approach to tasks.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q109', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 108, 'What is the difference between "convergent thinking" and "divergent thinking"?', 'Convergent thinking involves working toward a single, correct, well-defined solution to a problem, typically assessed by traditional tests with one right answer. Divergent thinking involves generating multiple, varied, and original ideas or solutions to an open-ended problem, and is closely associated with creativity.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q110', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 109, 'What is Chomsky''s concept of the "Language Acquisition Device (LAD)"?', 'Chomsky''s Language Acquisition Device is a theoretical innate mental mechanism that he proposed all humans are born with, which predisposes children to acquire the grammar and structure of their native language rapidly and naturally through exposure, even without explicit, formal teaching of grammatical rules.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q111', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 110, 'How did Skinner''s behaviorist view explain language acquisition, in contrast to Chomsky''s view?', 'Skinner proposed that language, like other behaviors, is learned through operant conditioning — children imitate the speech they hear and are reinforced (through attention, approval, or successful communication) for producing correct language, gradually shaping their speech through this reinforcement process, in contrast to Chomsky''s view that language acquisition relies on an innate biological mechanism rather than reinforcement alone.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q112', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 111, 'What is the "critical period hypothesis" in language acquisition?', 'The critical period hypothesis proposes that there is a specific, biologically limited window early in life (generally before puberty) during which language acquisition occurs most easily and naturally, and that acquiring native-like fluency, especially in a second language, becomes significantly more difficult once this window has passed.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q113', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 112, 'What was Vygotsky''s view on the relationship between language and thought in child development?', 'Vygotsky proposed that language and thought develop from separate origins in early infancy but gradually merge, with language becoming an essential tool for organizing, directing, and advancing a child''s thinking; he described "private speech" (children talking to themselves) as an important stage where language actively guides a child''s problem-solving and self-regulation.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q114', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 113, 'What is the central question in the "nature versus nurture" debate in child development?', 'The nature versus nurture debate concerns the relative contribution of genetic/biological inheritance (nature) versus environmental experiences, upbringing, and learning (nurture) in shaping an individual''s development, abilities, and behavior, with most contemporary psychologists viewing development as resulting from a complex interaction of both factors rather than either one alone.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q115', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 114, 'What role does heredity play in child development, according to the "nature" side of the debate?', 'Heredity provides the genetic blueprint that sets a child''s basic physical characteristics, temperament tendencies, and the biological potential or constraints for various abilities, with proponents of the nature perspective emphasizing that many developmental outcomes are significantly shaped by inherited genetic factors regardless of environment.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q116', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 115, 'What role does environment play in child development, according to the "nurture" side of the debate?', 'Environment includes all external influences on a child — family upbringing, education, culture, nutrition, and social experiences — with proponents of the nurture perspective emphasizing that these experiences play the dominant role in shaping a child''s abilities, personality, and behavior, often more than any fixed genetic predisposition.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q117', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 116, 'What is the "interactionist perspective" on the nature versus nurture debate, and why is it the dominant view today?', 'The interactionist perspective holds that development results from a continuous, dynamic interaction between genetic predispositions and environmental experiences, rather than either factor acting in isolation — for example, a genetic predisposition toward high intelligence may only be fully realized in an environment that provides adequate nutrition, stimulation, and educational opportunity. It is the dominant view today because research consistently shows that genes and environment influence and shape each other throughout development.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q118', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 117, 'What is "maturation" in child development, and how does it differ from learning?', 'Maturation is the genetically programmed, biological unfolding of physical and neurological growth over time (such as a child''s nervous system developing to the point where walking becomes physically possible), occurring relatively independently of specific practice or teaching. Learning, by contrast, refers to relatively permanent changes in behavior or knowledge that result specifically from experience and practice.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q119', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 118, 'What is a "critical period" (or "sensitive period") in development, and why is the concept important for early childhood education?', 'A critical or sensitive period is a specific window of time during development when a child is maximally receptive to acquiring a particular skill or is especially vulnerable to the effects of certain experiences or their absence. The concept is important for early childhood education because it suggests that providing the right kind of stimulation and experiences at the right developmental stage can be especially impactful, while missing that window may make the same learning considerably harder later.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q120', 'teaching-pedagogy-bank', 'Learning Theories & Educational Psychology', 1, 119, 'What is "resilience" in the context of child development, and what are "protective factors"?', 'Resilience is a child''s capacity to adapt positively and recover well despite facing significant adversity, stress, or risk factors in their life. Protective factors are the specific conditions or resources — such as a strong supportive relationship with at least one caring adult, good self-regulation skills, or a stable and predictable environment — that help build and sustain this resilience in the face of difficult circumstances.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q121', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 120, 'What is the "lecture method" of teaching, and what is its primary limitation?', 'The lecture method involves a teacher orally presenting information to students in a structured, one-way format, with the teacher as the primary source of content. Its primary limitation is that it is largely passive for the learner, offering limited opportunities for hands-on engagement, immediate feedback, or accommodation of different learning paces.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q122', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 121, 'What defines an "activity-based" teaching method, and what principle of learning does it rest on?', 'An activity-based method engages students in hands-on tasks, experiments, or exercises through which they discover or practice concepts directly, rather than only receiving information verbally. It rests on the principle that learning is more effective and lasting when learners actively construct understanding through doing, not just listening.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q123', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 122, 'In which kind of classroom situation is the lecture method still considered appropriate, despite its limitations?', 'The lecture method remains appropriate when introducing a large amount of new factual information efficiently to a large group, or when time constraints make extended hands-on activity impractical, such as providing background context before a practical session.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q124', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 123, 'What is a "demonstration-cum-activity" approach in teaching, and why is it often preferred over pure lecture?', 'It combines a teacher''s demonstration of a skill or concept with students then practicing the same activity themselves. It is often preferred over pure lecture because it gives learners both a clear model to follow and the opportunity to apply it immediately, reinforcing retention.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q125', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 124, 'What is "learning by doing," and which educational theorist is this principle most closely associated with?', '"Learning by doing" is the principle that students understand and retain concepts more effectively when they actively engage in tasks and experiences rather than passively receiving information. It is most closely associated with John Dewey, who argued that education should be rooted in real, purposeful experience.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q126', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 125, 'What is one key disadvantage of relying solely on activity-based methods in a classroom with large student numbers?', 'With large class sizes, activity-based methods can be difficult to manage and supervise effectively, since the teacher may be unable to give individual attention or ensure each student is genuinely engaged, and resources or materials for hands-on activities may be limited.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q127', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 126, 'What is the difference between "passive learning" and "active learning" in the classroom?', 'Passive learning occurs when students primarily receive information without actively engaging with it, such as listening to a lecture without discussion. Active learning occurs when students participate directly in the learning process through questioning, discussion, problem-solving, or hands-on tasks, which tends to improve engagement and retention.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q128', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 127, 'What is "project-based learning (PBL)," and what is its core educational purpose?', 'Project-based learning is a teaching method where students learn by actively engaging in a real-world, meaningful project over an extended period, investigating and responding to an authentic problem or question. Its core purpose is to develop deeper understanding, critical thinking, and practical skills by applying knowledge in context rather than only through isolated lessons.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q129', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 128, 'What are the typical stages involved in executing a classroom project under the project method?', 'The typical stages are: selecting a purposeful topic or problem, planning the approach and resources needed, executing the project through investigation or creation, and evaluating the outcome and process, often with student reflection on what was learned.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q130', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 129, 'Who is credited with developing the "Project Method" in education, building on Dewey''s ideas?', 'William Heard Kilpatrick is credited with developing the Project Method, extending John Dewey''s philosophy of learning by doing into a structured teaching approach centered on purposeful, student-driven projects.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q131', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 130, 'What skill, beyond subject content, does project-based learning particularly help develop in students?', 'Project-based learning particularly helps develop skills such as collaboration, time management, problem-solving, and self-directed inquiry, since students must plan, organize, and often work with others to complete an extended task.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q132', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 131, 'What is a common challenge teachers face when implementing project-based learning in schools with rigid timetables?', 'A common challenge is that projects often require extended, flexible blocks of time that don''t fit neatly into short, fixed class periods, making it difficult to sustain continuity of student engagement and coordinate project work across multiple sessions.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q133', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 132, 'How does project-based learning typically differ from a single classroom "activity" in terms of scope and duration?', 'A classroom activity is usually a short, self-contained task completed within a single lesson, while a project is typically more extensive, spans multiple sessions or even weeks, and usually results in a tangible product or presentation that integrates several skills and concepts.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q134', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 133, 'What role does the teacher play during project-based learning, as opposed to in a traditional lecture?', 'In project-based learning, the teacher primarily acts as a facilitator or guide, helping students frame questions, locate resources, and reflect on their progress, rather than being the direct and sole source of information as in a lecture.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q135', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 134, 'What is "cooperative learning," and what is one of its defining features compared to simple group work?', 'Cooperative learning is a structured instructional approach where small groups of students work together toward a shared goal, with each member having a specific, interdependent responsibility. A defining feature is "positive interdependence" — the idea that the group''s success depends on every member''s individual contribution, unlike unstructured group work where roles may be unclear.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q136', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 135, 'What is meant by "individual accountability" in a cooperative learning structure?', 'Individual accountability means that even though students work in a group, each member is still responsible for mastering the material or completing their assigned part, and is typically assessed individually as well, to ensure no one member can simply rely on others without contributing.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q137', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 136, 'What is the "Jigsaw" technique in cooperative learning, and how does it work?', 'The Jigsaw technique divides a larger topic into smaller sub-topics, with each student in a group becoming an "expert" on one sub-topic by studying it (often with students from other groups studying the same sub-topic), then returning to their home group to teach their piece to the others, so the full topic is only complete when all pieces are shared.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q138', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 137, 'What is the key difference between "cooperative learning" and "collaborative learning"?', 'Cooperative learning typically involves a more structured division of tasks with defined individual roles and accountability, often guided closely by the teacher. Collaborative learning is generally less structured, with the group working together more freely and jointly constructing understanding, with greater shared responsibility for the overall process rather than fixed individual pieces.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q139', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 138, 'What is one social-emotional benefit of cooperative learning, beyond academic achievement?', 'Cooperative learning helps develop social skills such as communication, empathy, conflict resolution, and respect for diverse viewpoints, since students must negotiate roles, share ideas, and work through disagreements with their peers.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q140', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 139, 'What is "positive interdependence," and why is it considered essential to effective cooperative learning?', 'Positive interdependence is the principle that group members are linked in such a way that one cannot succeed unless all members succeed, encouraging mutual support and shared effort. It is considered essential because without it, cooperative learning can collapse into one or two students doing most of the work while others remain passive.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q141', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 140, 'What is a potential drawback of cooperative learning if group roles and accountability are not clearly structured?', 'Without clear structure, cooperative learning can suffer from the "free-rider effect," where some students contribute little while relying on more motivated group members to complete the task, undermining both fairness and the learning benefits for the less-engaged students.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q142', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 141, 'What is "think-pair-share," and what purpose does it serve in a lesson?', 'Think-pair-share is a brief cooperative learning strategy where students first think individually about a question, then discuss their thoughts with a partner, and finally share their conclusions with the larger class. It serves to give every student processing time and a low-pressure opportunity to articulate ideas before whole-class discussion.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q143', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 142, 'What is the "discussion method" of teaching, and what kind of learning objective is it best suited for?', 'The discussion method involves structured verbal exchange of ideas among students (and the teacher) on a topic, question, or problem, encouraging students to express, defend, and refine their viewpoints. It is best suited for objectives involving critical thinking, the exploration of multiple perspectives, and the development of reasoning and communication skills, rather than simple factual recall.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q144', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 143, 'What is the teacher''s primary role during a classroom discussion, as opposed to during a lecture?', 'During a discussion, the teacher primarily acts as a facilitator or moderator — posing guiding questions, ensuring balanced participation, and steering the conversation productively — rather than being the main source of information being delivered.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q145', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 144, 'What is a "panel discussion," and how does it differ from an open class discussion?', 'A panel discussion involves a small group of selected students (or experts) presenting and discussing different viewpoints on a topic in front of the rest of the class, who then may ask questions. It differs from an open class discussion in that participation in the actual exchange is initially limited to the panel members, with the wider class typically observing before engaging.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q146', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 145, 'What is one risk of poorly managed classroom discussions, in terms of student participation?', 'A common risk is that discussion can become dominated by a few vocal or confident students, while quieter or less confident students remain disengaged or are given little opportunity to contribute, undermining the method''s goal of broad participation.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q147', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 146, 'What is the "Socratic method" of discussion, and what is its primary technique?', 'The Socratic method is a form of discussion-based teaching where the teacher guides students toward deeper understanding primarily through a structured series of probing questions, rather than direct explanation, encouraging students to examine and often revise their own assumptions and reasoning.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q148', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 147, 'What preparation is typically necessary for a discussion method lesson to be effective, beyond simply posing a topic?', 'Effective discussion lessons typically require the teacher to prepare clear guiding questions in advance, establish ground rules for respectful participation, and have a plan for drawing in quieter students, rather than simply opening a topic and hoping discussion naturally emerges.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q149', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 148, 'What is "buzz session" (or buzz group) technique, and how is it typically used within a larger discussion lesson?', 'A buzz session involves briefly dividing a large class into small groups (often pairs or trios) to quickly discuss a specific question or problem for a short, fixed time, before reconvening to share key points with the whole class — used to generate broader participation before a full class discussion.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q150', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 149, 'What is the "demonstration method" of teaching, and in which kinds of subjects is it most commonly used?', 'The demonstration method involves a teacher (or sometimes a student) performing an activity, experiment, or procedure in front of the class to visually illustrate a concept or skill, often followed by explanation. It is most commonly used in science, mathematics (e.g., geometric constructions), and skill-based or vocational subjects.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q151', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 150, 'What is one key advantage of the demonstration method over a purely verbal explanation?', 'The demonstration method provides a concrete, visual model of a process or concept, making abstract ideas more tangible and easier for students to understand and later replicate themselves, compared to relying only on verbal description.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q152', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 151, 'What is a major limitation of the demonstration method in a classroom with a large number of students?', 'With a large class, students seated farther away may struggle to clearly see the details of the demonstration, limiting its effectiveness unless supplemented with visual aids, repeated smaller demonstrations, or technology like a document camera or projected video.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q153', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 152, 'What should a teacher do immediately after completing a demonstration, to reinforce student learning?', 'The teacher should typically review and explain the key steps and underlying principles of what was demonstrated, invite student questions, and ideally provide an opportunity for students to attempt the same procedure themselves under supervision.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q154', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 153, 'What is the difference between a "demonstration" and an "experiment" conducted by students themselves?', 'In a demonstration, the teacher (or a designated presenter) performs the activity while students observe. In a student-conducted experiment, the students themselves carry out the procedure hands-on, which typically leads to deeper engagement and understanding, though it requires more resources, time, and supervision.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q155', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 154, 'Why is careful advance preparation particularly important for the demonstration method?', 'Since a demonstration is usually performed live in front of the class, any error, equipment failure, or unclear sequencing can confuse students or fail to illustrate the intended concept, so careful rehearsal and preparation of materials beforehand is essential to ensure clarity and safety.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q156', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 155, 'What is a "silent demonstration," and when might a teacher choose to use one?', 'A silent demonstration is performed without verbal explanation during the activity itself, requiring students to observe closely and infer what is happening. A teacher might use this to develop students'' observation skills or to have students predict outcomes before an explanation is given afterward.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q157', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 156, 'What are the three broad components typically included in a lesson plan, according to standard pedagogical practice?', 'A standard lesson plan typically includes: clearly stated learning objectives (what students should know or be able to do by the end), the teaching-learning process and materials (the activities, methods, and aids used to achieve those objectives), and an evaluation component (how the teacher will check whether the objectives were met).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q158', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 157, 'What is a "learning objective" in a lesson plan, and why should it be stated in observable, measurable terms?', 'A learning objective is a specific statement of what a student should be able to know, understand, or do by the end of a lesson. It should be stated in observable, measurable terms (e.g., "identify," "explain," "solve") so the teacher can clearly assess afterward whether the objective was actually achieved.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q159', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 158, 'What does "TLM" stand for in the context of lesson planning, and what does it include?', 'TLM stands for Teaching-Learning Materials — the resources used to support instruction, such as textbooks, charts, models, worksheets, audio-visual aids, or digital tools, selected specifically to help achieve the lesson''s stated objectives.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q160', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 159, 'What is the purpose of an "introduction" or "warm-up" stage at the start of a lesson plan?', 'The introduction stage is used to capture students'' attention, activate relevant prior knowledge, and establish a connection between what students already know and the new content to be taught, setting a purposeful context for the rest of the lesson.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q161', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 160, 'Why should a lesson plan include built-in flexibility rather than a rigid, minute-by-minute script?', 'Because actual classroom dynamics, such as varying student responses, unexpected questions, or technical issues, can require adjustments on the spot; a lesson plan with some flexibility allows a teacher to adapt pacing or activities in real time while still working toward the stated objectives.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q162', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 161, 'What is the difference between a "unit plan" and a "lesson plan"?', 'A unit plan outlines the objectives, content, and sequence of instruction for an entire topic or theme spanning multiple class periods or weeks. A lesson plan is a more detailed, specific plan for a single class period, derived from and fitting within the broader unit plan.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q163', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 162, 'What is meant by "recapitulation" at the end of a lesson, and why is it included in lesson planning?', 'Recapitulation is a brief summary or review of the key points covered during the lesson, often involving quick questions to students. It is included to reinforce retention, check for immediate understanding, and provide closure before moving to the next topic.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q164', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 163, 'Why is it considered good practice to state the "previous knowledge" or prerequisite assumed before a lesson, within a lesson plan?', 'Stating assumed previous knowledge helps the teacher verify, often through quick questioning at the start, that students actually have the necessary foundation before introducing new material, preventing gaps in understanding and allowing the teacher to briefly review prerequisites if needed.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q165', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 164, 'What is a "teaching aid," and what is its primary educational purpose?', 'A teaching aid is any material or resource (visual, audio, or audio-visual) used by a teacher to support and enhance the delivery and understanding of a lesson''s content. Its primary purpose is to make abstract or complex concepts more concrete, engaging, and easier for students to grasp and retain.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q166', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 165, 'What is the difference between an "audio aid" and a "visual aid" in teaching, with one example of each?', 'An audio aid conveys information through sound alone, such as a recorded lecture or audio clip. A visual aid conveys information through sight, such as a chart, diagram, or picture, without necessarily involving sound.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q167', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 166, 'What is an "audio-visual aid," and why is it often considered more effective than audio or visual aids alone?', 'An audio-visual aid combines both sound and visual elements, such as an educational video. It is often considered more effective because it engages multiple senses simultaneously, which tends to improve attention, comprehension, and memory retention compared to using only one sensory channel.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q168', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 167, 'What is one risk of over-reliance on teaching aids or technology in a classroom?', 'Over-reliance on teaching aids can reduce direct teacher-student interaction and critical thinking opportunities if the aid becomes a substitute for explanation and discussion rather than a supplement to it, and can also cause disruption if the technology fails during the lesson.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q169', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 168, 'What is a "smart classroom," and what technologies are typically part of it?', 'A smart classroom is a technology-enabled learning space typically equipped with an interactive whiteboard or digital display, internet connectivity, and multimedia projection equipment, allowing teachers to present digital content, videos, and interactive materials as part of instruction.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q170', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 169, 'What is "blended learning," in simple terms?', 'Blended learning combines traditional face-to-face classroom instruction with online or digital learning components, allowing students to benefit from both direct teacher interaction and the flexibility, pace, and resources offered by digital tools.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q171', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 170, 'What criteria should a teacher consider when selecting a teaching aid for a particular lesson?', 'A teacher should consider whether the aid is directly relevant to the lesson''s objectives, appropriate for the students'' age and comprehension level, practically available and functional in the classroom setting, and genuinely adds clarity or engagement rather than being used merely for novelty.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q172', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 171, 'What is the educational value of using "models" (three-dimensional representations) as a teaching aid, particularly in science?', 'Models allow students to visualize and interact with the structure of objects, processes, or systems that may be too small, too large, too abstract, or otherwise impossible to observe directly, such as a model of the solar system or a human organ, making complex concepts more concrete and understandable.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q173', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 172, 'What is the key difference between "authoritarian" and "authoritative" approaches to classroom discipline?', 'An authoritarian approach relies on strict rules and control enforced through punishment, with little room for student input or explanation. An authoritative approach also maintains clear rules and high expectations, but combines this with warmth, explanation of reasoning, and responsiveness to students'' needs, generally producing better long-term self-discipline.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q174', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 173, 'What is "positive discipline," and how does its underlying philosophy differ from punitive discipline?', 'Positive discipline focuses on teaching students self-control and appropriate behavior through encouragement, clear expectations, and natural or logical consequences, rather than relying primarily on punishment. Its underlying philosophy is that discipline should guide and teach rather than simply penalize.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q175', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 174, 'What is a "classroom rule," as distinct from a one-time instruction, and why are clearly established rules important for discipline?', 'A classroom rule is a general, standing expectation of behavior that applies consistently across situations, such as "raise your hand before speaking," unlike a one-time instruction given for a specific task. Clearly established rules are important because they create predictability and fairness, helping students understand expectations in advance rather than being surprised by consequences.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q176', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 175, 'What is the significance of consistency in enforcing classroom discipline policies?', 'Consistency ensures that students understand that the same behavior will lead to the same consequence regardless of circumstance or which student is involved, which builds trust in the fairness of the system and reduces testing of boundaries that often occurs when enforcement is unpredictable.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q177', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 176, 'What does "withitness," as described by educational researcher Jacob Kounin, refer to in classroom management?', '"Withitness" refers to a teacher''s ability to be aware of everything happening in the classroom at all times, including noticing early signs of potential misbehavior before it escalates, communicated through the teacher''s apparent awareness, such as addressing an issue without having to visibly search for its source.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q178', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 177, 'What is the difference between a "natural consequence" and a "logical consequence" in discipline?', 'A natural consequence occurs without adult intervention, arising directly from the behavior itself, such as a student who doesn''t bring their book being unable to follow along in a reading lesson. A logical consequence is deliberately applied by the teacher but is directly and reasonably related to the misbehavior, such as a student who misuses classroom materials losing access to them for a short period.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q179', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 178, 'Why is corporal punishment prohibited in Indian schools under the RTE Act, 2009, and what alternative approach does educational policy encourage instead?', 'Corporal punishment is prohibited because it can cause physical and psychological harm, undermine a child''s dignity, and is not considered an effective long-term method of behavior change. Educational policy instead encourages positive discipline strategies that build intrinsic motivation and self-regulation.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q180', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 179, 'What role does establishing a predictable classroom routine play in preventing discipline problems before they occur?', 'A predictable routine reduces uncertainty and idle time, which are common triggers for disruptive behavior, by giving students clear expectations for transitions, activities, and conduct, thereby proactively minimizing opportunities for misbehavior rather than only reacting to it after it happens.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q181', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 180, 'What is the recommended first step a teacher should typically take when addressing minor, low-level disruptive behavior during a lesson?', 'The recommended first step is usually a low-key, non-verbal or minimally disruptive intervention, such as eye contact, proximity (moving closer to the student), or a brief pause, to address the behavior without interrupting the flow of the lesson or drawing excessive attention to the student.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q182', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 181, 'What is the purpose of "proximity control" as a classroom management technique?', 'Proximity control involves the teacher physically moving closer to a student who is off-task or misbehaving, which often redirects the student''s attention and discourages continued disruption without requiring any verbal correction.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q183', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 182, 'Why might publicly reprimanding a disruptive student in front of the whole class be counterproductive?', 'Public reprimand can embarrass the student, potentially escalating defiance or attention-seeking behavior, and may also disrupt the broader class momentum; a private, calm conversation is often more effective at addressing the root cause without triggering a public power struggle.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q184', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 183, 'What is meant by identifying the "function" of a disruptive behavior before responding to it?', 'Identifying the function means trying to understand why a student is behaving disruptively, for example to seek attention, escape a difficult task, express frustration, or gain peer approval, since an effective response typically needs to address that underlying motivation rather than only the surface behavior.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q185', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 184, 'What is a potential downside of repeatedly removing a disruptive student from the classroom as a consequence?', 'Repeated removal can cause the student to miss instructional time, potentially worsening academic difficulties that may be contributing to the disruptive behavior in the first place, and for a student seeking to escape a task, removal may actually reinforce the behavior rather than discourage it.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q186', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 185, 'What is the value of a teacher privately discussing expectations with a chronically disruptive student outside of class time?', 'A private discussion allows the teacher to understand the student''s perspective, build rapport, clarify expectations without an audience, and collaboratively identify solutions, which is often more effective at producing lasting behavior change than repeated in-class corrections alone.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q187', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 186, 'How can involving a disruptive student in setting their own behavioral goals help improve classroom conduct?', 'Involving the student increases their sense of ownership and accountability for the agreed-upon goals, since they participated in creating them rather than having rules simply imposed externally, which tends to increase intrinsic motivation to follow through.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q188', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 187, 'What is one key factor a teacher should consider when deciding group size for a classroom group activity?', 'Group size should balance providing enough diversity of ideas and shared workload against the risk that very large groups allow some members to remain passive; smaller groups, commonly 3 to 5 students, often make it easier to ensure every member actively participates.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q189', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 188, 'What is the difference between a "homogeneous" and "heterogeneous" grouping strategy, in terms of student ability levels?', 'Homogeneous grouping places students of similar ability or skill level together, while heterogeneous grouping deliberately mixes students of varying ability levels within the same group, often to encourage peer learning and support between stronger and weaker students.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q190', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 189, 'What is a common challenge related to "social loafing" in group work, and what does the term mean?', 'Social loafing refers to the tendency for individuals to exert less effort on a task when working in a group than when working alone, since individual contribution may be less visible or feel less consequential, which can undermine the fairness and effectiveness of group work if not managed.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q191', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 190, 'What is the purpose of assigning specific roles, such as "recorder," "timekeeper," or "presenter," within a group activity?', 'Assigning specific roles helps ensure that every group member has a clear, individual responsibility, which reduces the chances of some students doing most of the work while others remain uninvolved, and helps the group function in an organized way.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q192', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 191, 'Why might a teacher deliberately rotate group membership across different activities throughout the term, rather than keeping the same groups fixed?', 'Rotating group membership exposes students to working with a wider range of peers, helps develop broader social and collaborative skills, and prevents the formation of fixed, potentially exclusionary cliques or persistent imbalances in group dynamics.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q193', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 192, 'What is one strategy a teacher can use to monitor and assess individual contribution within group work, despite a shared group outcome?', 'A teacher can use strategies such as individual reflection logs, peer evaluation forms where group members rate each other''s contribution, or having each student explain or defend a specific part of the group''s work individually, to distinguish individual effort within the collective outcome.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q194', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 193, 'What is the benefit of having groups briefly present or share their work to the rest of the class after a group activity?', 'Presenting to the class holds groups accountable for producing a coherent output, allows the whole class to benefit from multiple groups'' ideas and approaches, and gives students practice in communicating their reasoning publicly.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q195', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 194, 'What is the difference between a "convergent" question and a "divergent" question in classroom questioning?', 'A convergent question has a single correct or expected answer, typically testing recall or understanding of specific facts, such as "What is the capital of India?" A divergent question has multiple possible valid answers and encourages open-ended thinking, creativity, or exploration of different perspectives, such as "What might happen if India had no monsoon season?"', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q196', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 195, 'What is "wait time" in classroom questioning, and why is it pedagogically significant?', 'Wait time is the pause a teacher deliberately gives after asking a question, before calling on a student to answer, and/or after a student''s answer before responding. It is pedagogically significant because research shows that even a few seconds of additional wait time increases the quality and length of student responses and encourages more students to participate.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q197', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 196, 'What is a "probing question," and what is its purpose during classroom discussion?', 'A probing question is a follow-up question asked after an initial student response, intended to encourage the student to elaborate, clarify, justify, or extend their original answer, rather than accepting a surface-level response as final.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q198', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 197, 'What is a common pitfall of asking only "closed" (yes/no) questions throughout a lesson?', 'Relying only on closed questions limits opportunities for students to demonstrate deeper understanding or reasoning, since such questions can often be answered correctly by guessing, and they typically do not reveal whether a student genuinely understands the underlying concept.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q199', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 198, 'What is the purpose of "redirecting" a question to multiple students rather than accepting the first response and moving on?', 'Redirecting encourages broader participation and allows the teacher to gather multiple perspectives or check whether understanding is shared across the class, rather than assuming the entire class understands based on just one student''s correct answer.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q200', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 199, 'Why is it generally recommended that a teacher pose a question to the whole class before naming a specific student to answer?', 'Posing the question first keeps all students mentally engaged and thinking about a possible answer, since they do not yet know who will be called upon; naming a student first can cause the rest of the class to disengage, assuming they are not responsible for answering.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q201', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 200, 'What is a "higher-order question," as distinguished from a "lower-order question," in terms of cognitive demand?', 'A lower-order question typically requires only recall or basic comprehension of information, such as "What year did an event occur?" A higher-order question requires deeper cognitive processes such as analysis, synthesis, or evaluation, such as "Why do you think this event had the consequences it did?", demanding more complex thinking from the student.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q202', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 201, 'What is the risk of a teacher unintentionally answering their own question too quickly after posing it to the class?', 'If a teacher answers too quickly, students learn that they do not need to actively think or respond, since the teacher will eventually provide the answer regardless, which discourages genuine engagement and reduces opportunities for students to practice reasoning.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q203', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 202, 'What is a "flipped classroom," and how does it reverse the traditional sequence of instruction and practice?', 'In a flipped classroom, students first learn new content independently outside of class, often through recorded videos or reading material, and then use class time for activities such as discussion, problem-solving, or practice with direct teacher support — reversing the traditional sequence where new content is introduced in class and practice happens independently as homework.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q204', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 203, 'What is one key advantage of the flipped classroom model in terms of how class time is used?', 'Since initial content delivery happens outside class, class time can be dedicated to more interactive, higher-value activities like guided practice, discussion, and addressing individual student difficulties directly, rather than being consumed mostly by one-way content delivery.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q205', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 204, 'What is a significant practical challenge to implementing a flipped classroom model, particularly in under-resourced settings?', 'A significant challenge is unequal access to the technology, such as devices or reliable internet, needed for students to engage with pre-class materials at home, which can disadvantage students without such access and undermine the model''s effectiveness.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q206', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 205, 'What is the difference between "synchronous" and "asynchronous" components of blended learning?', 'Synchronous components occur in real time with direct interaction, such as a live class session or video call, where the teacher and students are present simultaneously. Asynchronous components do not require simultaneous participation, such as pre-recorded videos or materials students can access and complete at their own pace and time.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q207', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 206, 'What is the "rotation model" of blended learning, and what does it typically involve?', 'The rotation model involves students rotating, either on a fixed schedule or at the teacher''s discretion, between different learning modes or stations within a course, such as online self-paced work, small-group instruction, and whole-class instruction, combining digital and face-to-face learning in a structured sequence.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q208', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 207, 'Why is student accountability considered particularly important for the pre-class component of a flipped classroom to succeed?', 'Since the in-class activities are built on the assumption that students have already engaged with the pre-class material, students who skip or skim that material arrive unprepared for the deeper in-class work, undermining the model''s effectiveness for both themselves and group activities relying on shared preparation.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q209', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 208, 'What is one way a teacher can verify that students actually engaged with pre-class material in a flipped classroom approach?', 'A teacher can use short, low-stakes quizzes, reflection questions, or brief discussion prompts at the start of class based directly on the pre-class material, which both checks engagement and quickly surfaces common areas of confusion to address during the lesson.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q210', 'teaching-pedagogy-bank', 'Teaching Methods & Classroom Management', 2, 209, 'What is "blended learning" sometimes criticized for, in terms of equity, when implemented without adequate support?', 'It is sometimes criticized because it can widen gaps between students who have reliable access to technology and a supportive home environment for independent learning, versus those who lack such resources, potentially disadvantaging students from lower-resource backgrounds if the school does not provide adequate support or alternatives.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q211', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 210, 'What is Autism Spectrum Disorder (ASD), and how does it typically manifest in a classroom setting?', 'ASD is a neurodevelopmental condition characterized by difficulties in social communication and interaction, along with restricted or repetitive patterns of behavior and interests. In the classroom, a student with ASD may avoid eye contact, show limited interest in group activities, prefer strict routines, and react strongly to sensory stimuli like loud noises or bright lights.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q212', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 211, 'Why is predictability and routine important for students with Autism Spectrum Disorder?', 'Many students with ASD find unpredictable changes distressing because they rely on routine to make sense of their environment and reduce anxiety. Teachers often use visual schedules and give advance notice of changes to help these students transition smoothly between activities.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q213', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 212, 'What is sensory overload, and how might it affect a student with ASD?', 'Sensory overload occurs when a person receives more sensory input (sound, light, touch, smell) than their nervous system can process comfortably. A student with ASD experiencing sensory overload may become withdrawn, agitated, or display repetitive calming behaviors, requiring a quiet space or sensory breaks to self-regulate.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q214', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 213, 'What are social stories, and how are they used to support students with ASD?', 'Social stories are short, simple narratives that describe a social situation, event, or skill in concrete terms, often with visual supports, to help a student with ASD understand expected behaviors and anticipate outcomes before encountering that situation in real life.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q215', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 214, 'What is meant by echolalia, sometimes observed in children with ASD?', 'Echolalia is the repetition of words, phrases, or sounds previously heard, either immediately or after a delay, without necessarily using them in a typical conversational context. It can be a communication strategy for some children with ASD rather than simply meaningless repetition.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q216', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 215, 'How can a teacher adapt classroom instructions to better support a student with ASD?', 'Teachers can use clear, concrete, literal language (avoiding idioms or sarcasm that may be misunderstood), break multi-step instructions into smaller steps, pair verbal instructions with visual cues, and allow extra processing time before expecting a response.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q217', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 216, 'What is the difference between "high-functioning" and "low-functioning" labels historically used for ASD, and why have they fallen out of favor?', 'These labels attempted to describe severity based on perceived cognitive ability and independence, but they have fallen out of favor because they oversimplify a highly variable spectrum of strengths and challenges, can mask real support needs in "high-functioning" individuals, and can underestimate capabilities in "low-functioning" individuals.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q218', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 217, 'What role can peer-mediated support play for a student with ASD in an inclusive classroom?', 'Peer-mediated support involves training typically developing classmates to initiate interaction, model appropriate social behavior, and include the student with ASD in group activities, which can improve social engagement more naturally than adult-led intervention alone.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q219', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 218, 'What is the difference between a speech disorder and a language disorder?', 'A speech disorder affects the physical production of sounds, such as articulation errors, stuttering, or voice quality issues. A language disorder affects the understanding or use of words and sentences to communicate meaning, including vocabulary, grammar, and the ability to follow or construct conversations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q220', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 219, 'What is stuttering, and what classroom accommodations can help a student who stutters?', 'Stuttering is a speech fluency disorder involving involuntary repetitions, prolongations, or blocks in speech sounds. Helpful classroom accommodations include giving the student time to finish speaking without interruption, not finishing their sentences for them, and reducing pressure to speak quickly or in front of the whole class if that increases anxiety.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q221', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 220, 'What is receptive language, as distinct from expressive language?', 'Receptive language is the ability to understand words, sentences, and instructions that others communicate. Expressive language is the ability to use words, gestures, or writing to convey one''s own thoughts and needs. A child may have difficulty in one area without the other being equally affected.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q222', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 221, 'How might a language disorder affect a child''s reading comprehension, even if their decoding skills are strong?', 'A child can decode words accurately (read them aloud correctly) while still struggling to understand their meaning if they have an underlying language disorder, since comprehension depends on vocabulary knowledge, grammatical understanding, and the ability to link ideas across sentences.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q223', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 222, 'What is augmentative and alternative communication (AAC), and when might it be used in a classroom?', 'AAC refers to methods of communication other than or alongside spoken speech, including picture boards, communication apps, or sign language, used to support students who have little or no functional speech, so they can still express needs, ideas, and participate in classroom activities.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q224', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 223, 'What is the role of a speech-language pathologist in supporting students with communication impairments at school?', 'A speech-language pathologist assesses a student''s speech and language abilities, develops individualized intervention goals and strategies, works directly with the student (often in short, regular sessions), and collaborates with classroom teachers on accommodations to support the student''s communication across all school settings.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q225', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 224, 'What is the difference between low vision and blindness in educational terms?', 'Low vision refers to a significant visual impairment that cannot be fully corrected with glasses or surgery but still allows some functional use of sight, often with aids like magnification. Blindness refers to little or no usable vision, typically requiring the student to rely primarily on non-visual senses like touch and hearing for learning.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q226', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 225, 'What is Braille, and what skill does learning it primarily develop?', 'Braille is a tactile writing system of raised dots that blind or severely visually impaired individuals read with their fingertips. Learning Braille primarily develops literacy, the ability to read and write independently, in students who cannot access print text visually.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q227', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 226, 'What classroom accommodations commonly support a student with low vision?', 'Common accommodations include large-print materials, high-contrast text and backgrounds, additional lighting or reduced glare, magnification devices, preferential seating close to the board, and extra time for visually demanding tasks.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q228', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 227, 'What is orientation and mobility training for students with visual impairment?', 'Orientation and mobility training teaches a visually impaired student to understand their position in space (orientation) and to move safely and independently through their environment (mobility), often using tools like a white cane and systematic route-learning techniques.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q229', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 228, 'Why should a teacher verbally describe visual content, like diagrams or gestures, when teaching a class that includes a blind student?', 'Verbal description ensures the blind student has equal access to information that sighted students receive visually, since gestures, facial expressions, and diagrams convey meaning the student cannot otherwise perceive, preventing them from missing key parts of the lesson.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q230', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 229, 'What is a talking book or audio textbook, and how does it support students with visual impairment?', 'A talking book is an audio recording of a text''s content, allowing a student with visual impairment to access the same material as their sighted peers by listening rather than reading print, supporting independent study and review outside of direct teacher instruction.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q231', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 230, 'What is the difference between hard of hearing and deaf in educational contexts?', 'Hard of hearing describes a person with partial hearing loss who can still use some residual hearing, often with hearing aids, to process spoken language. Deaf describes a person with little or no functional hearing, who typically relies primarily on visual communication methods such as sign language or lip-reading.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q232', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 231, 'What is the role of an interpreter in a classroom that includes a deaf student?', 'A sign language interpreter translates the teacher''s spoken instruction and classroom discussion into sign language in real time for the deaf student, and may also voice the student''s signed responses back to the class, enabling full participation in verbal classroom activities.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q233', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 232, 'Why is preferential seating important for a student who is hard of hearing?', 'Seating a hard-of-hearing student close to the teacher and away from background noise sources, like fans, doors, or hallways, maximizes the clarity of speech they can perceive and allows better access to visual cues like lip movement and facial expressions that support understanding.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q234', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 233, 'What is an FM system, and how does it help a student with hearing loss in the classroom?', 'An FM system is an assistive listening device where the teacher wears a small microphone transmitter and the student wears a receiver, often paired with their hearing aid, which transmits the teacher''s voice directly and clearly to the student, reducing the impact of classroom noise and distance on speech clarity.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q235', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 234, 'Why might captioning or visual supports be important even for hard-of-hearing students who can hear some speech?', 'Captioning and visual supports provide a reliable backup when speech is unclear due to distance, noise, accents, or rapid speech, ensuring the student does not miss key information that partial hearing alone might cause them to misinterpret or miss entirely.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q236', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 235, 'What is total communication as an approach for deaf education?', 'Total communication is an approach that combines multiple methods, such as sign language, speech, lip-reading, gestures, and written text, simultaneously, rather than relying on a single communication mode, to maximize the chances that a deaf or hard-of-hearing student successfully receives the intended message.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q237', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 236, 'What does giftedness mean in educational psychology, beyond simply having a high IQ score?', 'Giftedness refers to significantly above-average ability or potential in one or more domains, which can include intellectual ability, but also creativity, leadership, or specific academic or artistic talent, not solely a high IQ score, since a student can be gifted in a specific area without uniformly high scores across all subjects.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q238', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 237, 'What is asynchronous development in gifted children?', 'Asynchronous development refers to a mismatch between a gifted child''s advanced cognitive abilities and their typical, same-age, social, emotional, or physical development. For example, a child may reason about complex ideas far beyond their age but still have age-typical emotional regulation skills.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q239', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 238, 'What is curriculum compacting, and why is it used for gifted learners?', 'Curriculum compacting involves assessing what a gifted student already knows and streamlining or skipping content they have already mastered, freeing up instructional time for more challenging, enriched, or accelerated material suited to their readiness level.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q240', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 239, 'What is the difference between acceleration and enrichment as strategies for gifted education?', 'Acceleration involves moving a gifted student through curriculum content faster than the standard pace, such as grade-skipping or early entry to advanced coursework. Enrichment involves providing additional depth, breadth, or complexity within the student''s current grade level, without necessarily speeding up progression through the standard curriculum.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q241', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 240, 'Why might some gifted students underachieve academically despite high potential?', 'Gifted underachievement can result from factors like lack of challenge leading to boredom and disengagement, perfectionism causing avoidance of tasks where failure feels risky, social or emotional difficulties, or an unidentified co-occurring learning difficulty that masks their true ability.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q242', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 241, 'What is twice-exceptional, or 2e, referring to certain gifted students?', 'Twice-exceptional describes a student who is both gifted in one or more areas and also has a diagnosed disability, such as a learning disability, ADHD, or ASD, requiring educators to address both the need for enrichment and challenge and the need for targeted support simultaneously.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q243', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 242, 'What is a common misconception about gifted students that can lead to them being overlooked for support?', 'A common misconception is that gifted students, by definition, do not need additional support or intervention since they already perform well, but without appropriate challenge, they can become bored, disengaged, or even develop behavioral issues from lack of stimulation.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q244', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 243, 'What role can mentorship programs play in gifted education?', 'Mentorship programs connect gifted students with experts or advanced practitioners in their area of talent or interest, providing real-world exposure, deeper subject mastery, and guidance beyond what a general classroom curriculum can offer.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q245', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 244, 'What is cluster grouping as an instructional strategy for gifted students?', 'Cluster grouping involves placing a small group of gifted students together within an otherwise heterogeneous, mixed-ability classroom, rather than spreading them one per class, allowing the teacher to more efficiently provide targeted enrichment to that group while still maintaining an inclusive classroom structure.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q246', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 245, 'Why is early identification of giftedness considered important by educational researchers?', 'Early identification allows appropriate challenge and support to begin before a gifted child experiences prolonged boredom, disengagement, or underachievement, and helps prevent later motivational or behavioral problems that can arise when a child''s educational needs go unmet for an extended period.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q247', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 246, 'What is code-switching in a multilingual classroom context?', 'Code-switching is the practice of alternating between two or more languages or language varieties within a single conversation or even a single sentence, often used naturally by multilingual speakers to express meaning, emphasis, or to engage with different audiences.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q248', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 247, 'What is the difference between Basic Interpersonal Communicative Skills (BICS) and Cognitive Academic Language Proficiency (CALP)?', 'BICS refers to the everyday conversational language used for social interaction, typically acquired relatively quickly within 1-2 years. CALP refers to the more complex, abstract academic language needed for subject-area learning, like science or mathematics, which takes significantly longer to develop, often 5-7 years, even after conversational fluency is achieved.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q249', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 248, 'Why can a multilingual student who converses fluently in a second language still struggle academically in that language?', 'Fluent conversational ability, or BICS, does not guarantee the more complex academic language proficiency, or CALP, needed to understand subject-specific vocabulary, abstract concepts, and formal text structures used in academic instruction and assessment.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q250', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 249, 'What is additive bilingualism, as opposed to subtractive bilingualism?', 'Additive bilingualism occurs when a second language is learned while the first language continues to be maintained and valued, enriching the learner''s overall linguistic repertoire. Subtractive bilingualism occurs when learning a second language comes at the expense of the first language, which may be lost or devalued over time.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q251', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 250, 'What is the benefit of using a student''s mother tongue as a foundation before introducing a second or third language in early schooling?', 'Using the mother tongue first allows children to grasp foundational literacy and numeracy concepts using language they already understand deeply, building a stronger cognitive foundation that can then transfer more effectively to learning additional languages later.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q252', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 251, 'What is a multilingual classroom, and what pedagogical challenge does it commonly present?', 'A multilingual classroom is one where students come from diverse language backgrounds, sometimes speaking different home languages from each other and from the language of instruction. A common challenge is ensuring equitable access to content for all students despite varying levels of proficiency in the language used for teaching.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q253', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 252, 'What is translanguaging as a pedagogical practice?', 'Translanguaging is an instructional approach that allows and encourages students to draw flexibly on all the languages in their repertoire, not just the official language of instruction, to make sense of content, express understanding, and communicate, rather than strictly separating or banning the use of other languages.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q254', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 253, 'According to NEP 2020, what is the recommended medium of instruction for young children wherever possible?', 'NEP 2020 recommends that, wherever possible, the medium of instruction until at least Grade 5, and preferably until Grade 8, should be the child''s home language, mother tongue, or local or regional language, to support stronger early learning outcomes.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q255', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 254, 'What challenge can arise in a linguistically diverse country like India when trying to implement mother-tongue-based instruction uniformly?', 'Practical challenges include a shortage of trained teachers fluent in every local language, a lack of textbooks and teaching materials in many minor or tribal languages, and classrooms containing children from several different home-language backgrounds simultaneously, making a single shared mother-tongue approach difficult to implement for every student.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q256', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 255, 'What is a three-language formula in the context of Indian education policy?', 'The three-language formula is a long-standing policy approach, reaffirmed under NEP 2020, encouraging students to learn three languages during their schooling, typically the regional or mother tongue, a second Indian language, and English, aiming to promote multilingualism while preserving linguistic diversity across the country.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q257', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 256, 'What is the National Curriculum Framework (NCF), and what is its primary purpose?', 'The NCF is a policy document that provides the overarching guidelines, principles, and direction for curriculum design, pedagogy, and assessment across schools in India, serving as the foundation from which state and national textbooks and syllabi are developed.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q258', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 257, 'What does NEP 2020 recommend regarding the introduction of vocational education in schools?', 'NEP 2020 recommends integrating vocational education starting from Grade 6, with internships in local trades, so students gain exposure to practical skills and real-world work experience alongside their academic curriculum, rather than treating vocational training as a separate, lower-status track introduced only later.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q259', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 258, 'What is a holistic progress card, as introduced under NEP 2020-aligned assessment reforms?', 'A holistic progress card is a comprehensive report that captures a student''s development across multiple dimensions, cognitive, affective or social-emotional, and psychomotor or physical and skill-based, often incorporating self-assessment, peer assessment, and teacher assessment, rather than reporting only academic marks or grades from exams.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q260', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 259, 'What shift in assessment philosophy does NEP 2020 promote, compared to traditional high-stakes, rote-memorization-focused exams?', 'NEP 2020 promotes shifting assessment away from rote memorization and one-time, high-stakes summative exams, toward regular, formative, competency-based assessment that evaluates higher-order skills like analysis, critical thinking, and conceptual understanding throughout the learning process.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q261', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 260, 'What is PARAKH, as established under NEP 2020?', 'PARAKH, which stands for Performance Assessment, Review, and Analysis of Knowledge for Holistic Development, is a national assessment body established under NEP 2020 to set norms and standards for student assessment and evaluation across school boards in India, aiming to bring greater consistency and quality to assessment practices nationally.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q262', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 261, 'What does NEP 2020 propose regarding board examinations, in terms of frequency and stakes?', 'NEP 2020 proposes making board examinations easier to take, testing core competencies rather than memorized content, and allowing students to take board exams up to twice a year, in subjects of their choice, reducing the single high-stakes nature of traditional one-time board exams.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q263', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 262, 'What is meant by experiential learning as emphasized in the National Curriculum Framework?', 'Experiential learning is an approach where students learn through direct experience, hands-on activities, and active engagement with real-world contexts and problems, rather than through passive reception of information, helping them construct deeper and more durable understanding.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q264', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 263, 'What does the National Curriculum Framework for Foundational Stage (NCF-FS) specifically address?', 'The NCF-FS, developed following NEP 2020, specifically addresses curriculum and pedagogy for the Foundational Stage, ages 3-8, emphasizing play-based, activity-based, and discovery-based learning methods appropriate for early childhood development, rather than formal, textbook-driven instruction at this early stage.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q265', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 264, 'What is a rubric in educational assessment?', 'A rubric is a scoring guide that lists specific criteria for evaluating a piece of work, along with descriptions of different performance levels for each criterion, used to make assessment of complex or subjective tasks, like essays or projects, more transparent, consistent, and objective.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q266', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 265, 'What is the difference between an analytic rubric and a holistic rubric?', 'An analytic rubric breaks down an assignment into separate criteria, such as content, organization, and grammar, and scores each one individually, producing a detailed, multi-part evaluation. A holistic rubric evaluates the work as a whole using a single overall score based on a general description of quality at each performance level, without separating out individual criteria.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q267', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 266, 'What is one key benefit of sharing a rubric with students before they complete an assignment?', 'Sharing the rubric in advance makes performance expectations transparent, helping students understand exactly what qualities or elements their work will be judged on, which can guide their effort and self-monitoring while completing the task rather than leaving them to guess what is expected.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q268', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 267, 'What does criteria-based assessment mean, as opposed to norm-referenced assessment?', 'Criteria-based, or criterion-referenced, assessment measures a student''s performance against a fixed, predefined standard or set of learning criteria, regardless of how other students perform. Norm-referenced assessment instead compares a student''s performance relative to the performance of a reference group of peers, such as ranking or percentile scores.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q269', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 268, 'What is a potential drawback of poorly designed rubrics in classroom assessment?', 'Poorly designed rubrics can use vague or overlapping criteria descriptions that are open to inconsistent interpretation between different teachers, or even the same teacher at different times, undermining the very consistency and fairness that rubrics are meant to provide.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q270', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 269, 'How can rubrics support self-assessment and peer-assessment among students?', 'Because rubrics clearly articulate the specific criteria and performance levels for a task, students can use the same rubric to evaluate their own work or a classmate''s work against those explicit standards, developing greater awareness of quality and ownership over their own learning process.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q271', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 270, 'What is a single-point rubric, and how does it differ from a traditional multi-level rubric?', 'A single-point rubric describes only the criteria for proficient, expected performance for each category, leaving space on either side for the teacher to note specific ways the work fell short or exceeded that standard, rather than pre-writing out separate descriptions for every performance level, such as excellent, good, or needs improvement, in advance.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q272', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 271, 'Why are rubrics particularly useful for assessing performance-based or project-based tasks?', 'Performance-based and project-based tasks often don''t have a single correct answer like a multiple-choice question, so rubrics provide a structured way to fairly and consistently evaluate more open-ended, creative, or multi-faceted work across multiple dimensions of quality.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q273', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 272, 'What is a portfolio in the context of student assessment?', 'A portfolio is a purposeful, organized collection of a student''s work samples gathered over time, used to document and demonstrate their learning progress, effort, achievement, and development of skills across a period, rather than relying on a single test or assignment as evidence of learning.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q274', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 273, 'What is the difference between a process portfolio and a showcase portfolio?', 'A process portfolio includes drafts, revisions, and work-in-progress samples to document a student''s learning journey and growth over time. A showcase portfolio contains only the student''s best, final, polished work samples, selected to demonstrate their highest level of achievement.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q275', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 274, 'What is one advantage of portfolio assessment over a single standardized test for evaluating student learning?', 'Portfolio assessment can capture growth and development over time, a wider range of skills and competencies, including creativity and problem-solving demonstrated through varied work, and a more authentic picture of a student''s abilities than a single test taken on one specific day.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q276', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 275, 'What role does student reflection typically play in portfolio assessment?', 'Students are often asked to write reflective statements about the work samples included in their portfolio, explaining why they chose each piece, what they learned, and how their understanding or skills have developed. This metacognitive component helps students take ownership of and insight into their own learning progress.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q277', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 276, 'What is one practical challenge teachers face when implementing portfolio assessment at scale?', 'Portfolio assessment is time-intensive to review and evaluate fairly and consistently for each student compared to a single standardized test, and establishing consistent criteria or rubrics for judging a highly individualized collection of varied work samples can be more difficult than scoring a uniform test.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q278', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 277, 'How can a portfolio support differentiated assessment for students with diverse abilities?', 'Because a portfolio can include varied types of evidence, such as written work, drawings, recordings, and projects, rather than a single fixed format, it allows students to demonstrate their understanding and skills in ways that play to their individual strengths, which is especially valuable for students who may not perform their best on traditional written tests.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q279', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 278, 'What is an e-portfolio, and what advantage does it offer over a traditional paper-based portfolio?', 'An e-portfolio is a digital collection of a student''s work samples, often including multimedia formats like video, audio, or interactive projects. It offers the advantage of easier storage, sharing, and long-term accessibility, plus the ability to include evidence types, such as recorded oral presentations, that a paper portfolio cannot capture.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q280', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 279, 'What is diagnostic teaching, and when is it typically used?', 'Diagnostic teaching is a process of identifying the specific nature and root cause of a student''s learning difficulty in a particular area, through careful observation, questioning, and targeted assessment tasks, typically used when a student is consistently struggling despite regular classroom instruction, to inform a precise intervention plan.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q281', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 280, 'What is the difference between diagnostic assessment and remedial teaching?', 'Diagnostic assessment is the process of identifying exactly what gaps, misconceptions, or difficulties a student has in their understanding or skills. Remedial teaching is the subsequent instructional intervention designed specifically to address those identified gaps and help the student catch up to expected learning levels.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q282', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 281, 'What is a common first step in diagnosing the cause of a student''s reading difficulty?', 'A common first step is to systematically assess separate reading sub-skills, such as letter-sound recognition, phonemic awareness, decoding accuracy, reading fluency, and comprehension, individually, to pinpoint exactly which specific sub-skill is breaking down, rather than treating reading difficulty as one single, undifferentiated problem.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q283', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 282, 'What does task analysis mean in the context of designing remedial instruction?', 'Task analysis involves breaking a complex skill or learning objective down into its smaller, sequential component sub-skills, so that remedial teaching can target and build up each prerequisite sub-skill in order, rather than attempting to teach the complex skill as a single, undivided unit.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q284', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 283, 'Why is small-group or one-on-one instruction often preferred for remedial teaching?', 'Small-group or one-on-one instruction allows the teacher to give immediate, individualized feedback, adjust pacing precisely to the student''s specific needs, and closely monitor whether the targeted intervention is working, which is harder to achieve consistently within a large, mixed-ability whole-class setting.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q285', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 284, 'What is error analysis, as a diagnostic tool used by teachers?', 'Error analysis involves systematically examining the specific mistakes a student makes in their work, such as consistently miscounting while regrouping in subtraction, to identify underlying patterns or misconceptions driving those errors, rather than simply marking answers right or wrong without investigating why they are wrong.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q286', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 285, 'What is the purpose of periodic progress monitoring during a remedial teaching program?', 'Progress monitoring involves repeatedly and regularly assessing a student''s performance on the targeted skill throughout the remedial intervention, to check whether the chosen strategy is actually working and to make timely adjustments to the approach if the student is not showing adequate improvement.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q287', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 286, 'Why might remedial teaching for the same academic gap look different for two students with different diagnosed causes of that gap?', 'Since remedial teaching is designed to directly address the specific root cause identified through diagnosis, two students who both struggle with word problems in math may receive different interventions if one struggle stems from weak reading comprehension and the other from weak computation skills, because effective remediation must target the actual underlying deficit, not just the surface-level symptom.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q288', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 287, 'What is the main difference between grading and marking in assessment terminology?', 'Marking typically refers to assigning a numerical score to an individual response or test item. Grading refers to converting scores, often from multiple assessments, into a broader category or symbol, like a letter grade, a grade point, or a descriptive band, that summarizes overall performance over an assignment, unit, or term.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q289', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 288, 'What is a grade point average (GPA), and how is it typically calculated?', 'GPA is a standardized measure of a student''s overall academic performance, typically calculated by converting each grade into a numerical point value, weighting those points by the credit value of each respective course, and averaging them across all courses taken.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q290', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 289, 'What is criterion-referenced grading, as distinct from grading on a curve?', 'Criterion-referenced grading assigns grades based on whether a student meets fixed, predetermined performance standards, regardless of how classmates perform. Grading on a curve instead adjusts grades based on the relative distribution of scores within a specific class or cohort, meaning the same raw score could earn a different grade depending on how the rest of the group performed.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q291', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 290, 'What is a potential drawback of grading on a curve in a classroom setting?', 'Grading on a curve can create unhealthy competition among students, since one student''s higher score can effectively lower a classmate''s relative grade, and it does not reliably indicate whether a student has truly mastered the actual learning objectives, since the grade depends on peer performance rather than a fixed standard.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q292', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 291, 'What is a mastery-based or standards-based grading system?', 'A mastery-based grading system reports a student''s level of proficiency on specific, clearly defined learning standards or skills, rather than averaging scores across many varied assignments into one overall grade. A student is only considered to have passed a standard once they have demonstrated genuine mastery of it, sometimes allowing multiple attempts to do so.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q293', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 292, 'Why might averaging all scores across a term, including early low scores from when a skill was first being learned, create a misleading final grade under traditional grading?', 'Averaging penalizes a student for their early performance on a skill they had not yet mastered, even if they later achieve strong, consistent mastery of that same skill by the end of the term. The final average may understate the student''s true, current level of proficiency compared to a system that credits demonstrated mastery regardless of when it was achieved.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q294', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 293, 'What is grade inflation, as a concern in educational assessment?', 'Grade inflation refers to a trend of assigning progressively higher grades over time for work of a similar or even declining standard of quality, which can erode the meaningfulness and comparability of grades as an accurate signal of a student''s actual achievement or mastery.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q295', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 294, 'What is one argument in favor of using descriptive feedback alongside or instead of a single letter grade?', 'Descriptive feedback explains specifically what a student did well and what they need to improve, giving them actionable information to guide further learning, whereas a single letter grade alone communicates a summary judgment without necessarily helping the student understand how to improve.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q296', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 295, 'What is universal design for learning (UDL), and how does it relate to inclusive assessment?', 'UDL is a framework for designing curriculum and assessment that proactively offers multiple means of engagement, representation, and expression from the outset, so that the broadest possible range of learners, including those with disabilities, can access and demonstrate learning, rather than retrofitting accommodations only after a student struggles.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q297', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 296, 'What is the difference between an accommodation and a modification in assessment for students with special needs?', 'An accommodation changes how a student accesses or demonstrates learning, such as extended time or a scribe, without changing the underlying content or expected standard being assessed. A modification changes the actual content or expected performance standard itself, such as a simplified test or reduced number of questions, altering what is being assessed.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q298', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 297, 'What is dyspraxia, or developmental coordination disorder, and how might it present in a school setting?', 'Dyspraxia is a condition affecting motor coordination and planning, which can make tasks like handwriting, using scissors, physical education activities, and even organizing one''s own belongings or following multi-step physical instructions noticeably more difficult, despite typical intellectual ability.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q299', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 298, 'What is the purpose of a resource room in an inclusive school setting?', 'A resource room is a separate, smaller instructional space within a mainstream school where students with identified learning needs receive specialized, individualized, or small-group support for part of their school day, while still being primarily included in the general classroom for the remainder of their schooling.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q300', 'teaching-pedagogy-bank', 'Inclusive Education & Assessment', 3, 299, 'Why is ongoing teacher professional development considered essential for effective inclusive education?', 'Successfully supporting the wide range of learning needs, disabilities, and backgrounds found in an inclusive classroom requires specific knowledge and skills, such as recognizing signs of specific learning difficulties, applying appropriate accommodations, and using varied instructional strategies, that general pre-service teacher training often does not fully cover, making continuous professional development necessary to keep educators equipped.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q031', 'police-exam-bank', 'Police Organization & Structure', 0, 30, 'What is the rank hierarchy in Indian state police forces, starting from the lowest uniformed rank?', 'The typical hierarchy, from lowest to highest, runs: Constable, Head Constable, Assistant Sub-Inspector (ASI), Sub-Inspector (SI), Inspector, Deputy Superintendent of Police (DSP/ACP), Superintendent of Police (SP), Senior Superintendent of Police (SSP), Deputy Inspector General (DIG), Inspector General (IG), Additional Director General (ADG), and Director General of Police (DGP).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q032', 'police-exam-bank', 'Police Organization & Structure', 0, 31, 'What distinguishes a Sub-Inspector (SI) from an Inspector in terms of typical duties?', 'A Sub-Inspector usually handles day-to-day investigation, patrolling, and FIR registration under supervision at the police station level. An Inspector typically supervises multiple Sub-Inspectors, may head a larger police station or a specialized unit, and takes on more serious case investigations and administrative responsibilities.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q033', 'police-exam-bank', 'Police Organization & Structure', 0, 32, 'What is the function of an Anti-Terrorism Squad (ATS) within state police?', 'An Anti-Terrorism Squad is a specialized state police unit dedicated to preventing, investigating, and responding to terrorism-related threats and activities, often working in coordination with central agencies like the NIA and intelligence bureaus to gather intelligence and neutralize threats before they materialize.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q034', 'police-exam-bank', 'Police Organization & Structure', 0, 33, 'What is the role of a Cyber Crime cell within a state police department?', 'A Cyber Crime cell is a specialized unit that investigates offences involving computers, networks, and digital devices, such as online fraud, hacking, cyberstalking, and digital financial crimes, and often provides technical support such as digital forensics to other investigating units.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q035', 'police-exam-bank', 'Police Organization & Structure', 0, 34, 'What are the main responsibilities of traffic police within a city police force?', 'Traffic police are responsible for regulating vehicular movement, enforcing traffic laws (such as speed limits, signal violations, and licensing requirements), managing congestion, investigating road accidents, and promoting road safety awareness among the public.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q036', 'police-exam-bank', 'Police Organization & Structure', 0, 35, 'What is the key difference between a State Armed Police force and the regular civil police within a state?', 'State Armed Police (such as the Provincial Armed Constabulary in Uttar Pradesh) are organized, trained, and equipped primarily for maintaining law and order during riots, large gatherings, and emergencies, and are generally not assigned routine civil policing duties like FIR registration or daily patrolling, which fall to the regular civil police.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q037', 'police-exam-bank', 'Police Organization & Structure', 0, 36, 'What is the difference between a Central Armed Police Force (CAPF) and a state police force in terms of command structure?', 'A Central Armed Police Force operates under the Ministry of Home Affairs and can be deployed across any state for duties such as border security, internal security, or law-and-order support, regardless of state boundaries. A state police force operates under the respective state government and has jurisdiction limited to that state.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q038', 'police-exam-bank', 'Police Organization & Structure', 0, 37, 'What is the primary role of the Border Security Force (BSF)?', 'The BSF is a Central Armed Police Force primarily responsible for guarding India''s international land borders during peacetime and preventing trans-border crimes such as smuggling and infiltration, particularly along the borders with Pakistan and Bangladesh.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q039', 'police-exam-bank', 'Police Organization & Structure', 0, 38, 'What is the primary role of the Indo-Tibetan Border Police (ITBP)?', 'The ITBP is a Central Armed Police Force responsible for guarding India''s border with China (the Indo-Tibetan border) in high-altitude and difficult terrain, and is also trained for disaster response and mountaineering operations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q040', 'police-exam-bank', 'Police Organization & Structure', 0, 39, 'What is the Sardar Vallabhbhai Patel National Police Academy, and what is its role?', 'The Sardar Vallabhbhai Patel National Police Academy, located in Hyderabad, is the premier training institution for Indian Police Service (IPS) officer trainees, providing foundational and in-service training in law, investigation, leadership, and physical fitness before they take up field postings.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q041', 'police-exam-bank', 'Police Organization & Structure', 0, 40, 'What is the purpose of a Police Training College at the state level?', 'A Police Training College provides basic and advanced training to newly recruited state police personnel, including constables and sub-inspectors, covering areas such as law, weapons handling, physical fitness, investigation techniques, and human rights awareness, before they are deployed to field postings.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q042', 'police-exam-bank', 'Police Organization & Structure', 0, 41, 'What is a Mahila Thana (Women''s Police Station), and why was this concept introduced?', 'A Mahila Thana is a police station staffed primarily by women police personnel, set up to encourage women to report crimes like domestic violence and sexual harassment more comfortably, in an environment designed to be more approachable and sensitive to such complainants than a standard police station.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q043', 'police-exam-bank', 'Police Organization & Structure', 0, 42, 'What is the purpose of a Women Help Desk at a regular police station?', 'A Women Help Desk is a dedicated counter staffed by trained women police personnel within a regular police station, meant to ensure that women visiting the station to report a complaint are received sensitively and their cases are handled appropriately, without needing to travel to a separate women''s police station.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q044', 'police-exam-bank', 'Police Organization & Structure', 0, 43, 'What is the role of the Railway Protection Force (RPF)?', 'The RPF is responsible for the security of railway property, passenger areas, and passengers on Indian Railways, working alongside the Government Railway Police (GRP) which handles law-and-order and crime investigation duties on railway premises under state police jurisdiction.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q045', 'police-exam-bank', 'Police Organization & Structure', 0, 44, 'What is the difference between the Railway Protection Force (RPF) and the Government Railway Police (GRP)?', 'The RPF, under the Ministry of Railways, primarily protects railway property and passenger security. The GRP, under state police administration, is responsible for registering FIRs and investigating crimes that occur on railway premises or trains, similar to how a civil police station handles crime in its jurisdiction.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q046', 'police-exam-bank', 'Police Organization & Structure', 0, 45, 'What is the role of a Special Branch within state police?', 'The Special Branch is the intelligence-gathering wing of a state police force, responsible for collecting and analyzing information related to law-and-order threats, political developments, and security matters to support preventive policing and strategic decision-making.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q047', 'police-exam-bank', 'Police Organization & Structure', 0, 46, 'What is a Quick Reaction Team (QRT) in the context of police deployment?', 'A Quick Reaction Team is a specially trained and equipped police unit kept on standby to respond rapidly to emergency situations such as terrorist attacks, hostage crises, or sudden law-and-order breakdowns, aiming to minimize response time and contain threats quickly.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q048', 'police-exam-bank', 'Police Organization & Structure', 0, 47, 'What is the function of the Police Control Room (PCR) in urban policing?', 'The Police Control Room is the central coordination hub that receives distress calls (such as via helpline numbers), dispatches patrol vehicles or personnel to incident locations, and coordinates communication between different police units during ongoing situations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q049', 'police-exam-bank', 'Police Organization & Structure', 0, 48, 'What is the role of Home Guards in supporting the regular police force?', 'Home Guards are a voluntary, trained auxiliary force that assists the regular police in maintaining law and order, managing traffic, providing support during natural disasters, and supplementing police presence during large public events, without being full-time police personnel.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q050', 'police-exam-bank', 'Police Organization & Structure', 0, 49, 'What is the purpose of a Forensic Science Laboratory (FSL) in supporting police investigations?', 'A Forensic Science Laboratory scientifically examines physical evidence collected during an investigation — such as fingerprints, DNA samples, ballistics, and chemical residues — to establish facts that can support or disprove a case theory, providing expert reports admissible in court.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q051', 'police-exam-bank', 'Police Organization & Structure', 0, 50, 'What is the role of the Narcotics Cell within a state police department?', 'The Narcotics Cell is a specialized unit focused on detecting and investigating drug trafficking and possession cases within the state, often coordinating with the central Narcotics Control Bureau on larger or inter-state drug trafficking networks.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q052', 'police-exam-bank', 'Police Organization & Structure', 0, 51, 'What is the difference between a constabulary recruitment exam and an officer-level (Sub-Inspector) recruitment exam in terms of typical eligibility?', 'A constable recruitment exam typically requires a minimum educational qualification (often 10th or 12th pass) and tests physical fitness, general knowledge, and reasoning at a foundational level. A Sub-Inspector recruitment exam usually requires a graduate degree and includes a more rigorous written examination along with physical standards, reflecting the greater supervisory and investigative responsibilities of the rank.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q053', 'police-exam-bank', 'Police Organization & Structure', 0, 52, 'What is the role of the Civil Defence organization in relation to police and disaster response?', 'Civil Defence is a volunteer-based organization that assists citizens and authorities, including police, during emergencies such as natural disasters, fires, and civil disturbances, focusing on rescue, evacuation, and first-aid support to reduce the burden on full-time emergency responders.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q054', 'police-exam-bank', 'Police Organization & Structure', 0, 53, 'What is the significance of community liaison groups such as Mohalla Committees in urban policing?', 'Mohalla Committees are local community groups that work with police to maintain communal harmony, share early warnings about tension or unrest, and build trust between residents and law enforcement, particularly in areas with a history of communal sensitivity.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q055', 'police-exam-bank', 'Law & Legal Awareness', 1, 54, 'What are two notable procedural changes the Bharatiya Nagarik Suraksha Sanhita (BNSS) introduced compared to the earlier CrPC?', 'The BNSS mandates the use of forensic investigation for offences punishable with seven years or more of imprisonment, and introduces provisions for audio-video recording of search and seizure proceedings, aiming to improve evidence quality and transparency during investigations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q056', 'police-exam-bank', 'Law & Legal Awareness', 1, 55, 'What is a notable change the Bharatiya Nyaya Sanhita (BNS) introduced regarding organized crime and terrorism, compared to the earlier IPC?', 'The BNS explicitly defines and criminalizes organized crime and terrorist acts as standalone offences within the main penal code itself, whereas under the earlier IPC regime these were primarily addressed through separate special laws rather than being codified directly in the general penal code.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q057', 'police-exam-bank', 'Law & Legal Awareness', 1, 56, 'What is a key change the Bharatiya Sakshya Adhiniyam (BSA) introduced regarding the definition of documents, compared to the Indian Evidence Act?', 'The BSA broadened the definition of "document" to explicitly include electronic and digital records, such as emails and electronic communications, ensuring that evidence stored or transmitted digitally is treated with the same evidentiary status as traditional paper documents.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q058', 'police-exam-bank', 'Law & Legal Awareness', 1, 57, 'What is the Juvenile Justice (Care and Protection of Children) Act primarily concerned with?', 'The Juvenile Justice Act provides a legal framework for the care, protection, treatment, and rehabilitation of children in conflict with the law and children in need of care and protection, establishing Juvenile Justice Boards and Child Welfare Committees to handle such cases separately from the adult criminal justice system.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q059', 'police-exam-bank', 'Law & Legal Awareness', 1, 58, 'What is the age threshold that generally defines a "juvenile" under Indian law?', 'A person below the age of 18 years is generally considered a juvenile (child) under the Juvenile Justice Act, though the Act allows a Juvenile Justice Board to try a juvenile aged 16-18 as an adult for certain heinous offences after a preliminary assessment.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q060', 'police-exam-bank', 'Law & Legal Awareness', 1, 59, 'What is the primary purpose of the Information Technology (IT) Act, 2000, in India?', 'The IT Act provides the primary legal framework for electronic governance, digital signatures, and cybercrime in India, defining offences such as hacking, identity theft, and data breaches, and giving legal recognition to electronic records and digital transactions.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q061', 'police-exam-bank', 'Law & Legal Awareness', 1, 60, 'What does Section 66 of the IT Act, 2000, primarily deal with?', 'Section 66 of the IT Act deals with computer-related offences, including unauthorized access, data theft, and introducing viruses or malicious code into computer systems, prescribing penalties for such cyber offences.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q062', 'police-exam-bank', 'Law & Legal Awareness', 1, 61, 'What is the difference between "documentary evidence" and "oral evidence" in a criminal trial?', 'Documentary evidence consists of written or recorded material presented to the court, such as contracts, letters, or digital records. Oral evidence consists of statements made by witnesses in court, under oath, describing what they personally saw, heard, or experienced relevant to the case.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q063', 'police-exam-bank', 'Law & Legal Awareness', 1, 62, 'What is "circumstantial evidence," and how does it differ from direct evidence?', 'Circumstantial evidence proves a fact indirectly, through inference from a chain of related facts and circumstances (e.g., fingerprints at a crime scene), rather than directly witnessing the act itself. Direct evidence, such as eyewitness testimony, directly establishes a fact without requiring inference.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q064', 'police-exam-bank', 'Law & Legal Awareness', 1, 63, 'What is the lowest level of criminal court in the Indian judicial hierarchy at the district level?', 'At the district level, the lowest criminal courts are typically the Courts of Judicial Magistrates (First Class or Second Class), which handle less serious criminal cases, with more serious cases being committed to the Court of Sessions.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q065', 'police-exam-bank', 'Law & Legal Awareness', 1, 64, 'What is the role of a Sessions Court in the Indian judicial hierarchy?', 'A Sessions Court, headed by a Sessions Judge, is the principal criminal court at the district level with jurisdiction to try serious offences (such as those punishable with death or life imprisonment) that are beyond the powers of magistrate courts, and it also hears appeals from magistrate courts.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q066', 'police-exam-bank', 'Law & Legal Awareness', 1, 65, 'What is the function of a High Court in relation to criminal cases within a state?', 'A High Court is the highest judicial authority within a state, hearing appeals against Sessions Court judgments, exercising original jurisdiction in certain serious matters, and supervising the functioning of subordinate courts within the state, in addition to its writ jurisdiction under the Constitution.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q067', 'police-exam-bank', 'Law & Legal Awareness', 1, 66, 'What is "witness protection," and why is it important in criminal trials?', 'Witness protection refers to measures taken to safeguard a witness''s identity, safety, and well-being before, during, and after a trial, such as identity concealment or physical security, to prevent intimidation or harm that could otherwise discourage witnesses from testifying truthfully.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q068', 'police-exam-bank', 'Law & Legal Awareness', 1, 67, 'What does the Witness Protection Scheme, 2018 (as approved by the Supreme Court), classify witnesses into?', 'The Scheme classifies witnesses into three categories of threat perception — Category A (threat to life during and after trial), Category B (threat to safety, reputation, or property during the trial), and Category C (moderate threat limited to the harassment or intimidation of the witness or their family) — with protection measures scaled accordingly.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q069', 'police-exam-bank', 'Law & Legal Awareness', 1, 68, 'What is the difference between "cognizance" taken by a magistrate and the registration of an FIR by police?', 'Registration of an FIR is the police''s administrative act of formally recording information about a cognizable offence to begin investigation. "Taking cognizance" is a judicial act where a magistrate formally applies their mind to the facts of a case to decide whether to proceed with it legally, which can happen based on a police report, a complaint, or other information.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q070', 'police-exam-bank', 'Law & Legal Awareness', 1, 69, 'What is a "summons case" as distinguished from a "warrant case" under criminal procedure?', 'A summons case involves relatively minor offences (generally punishable with imprisonment of up to two years), where the accused is called to court via a summons. A warrant case involves more serious offences (punishable with more than two years'' imprisonment, including death or life imprisonment), where a warrant may be issued to secure the accused''s presence.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q071', 'police-exam-bank', 'Law & Legal Awareness', 1, 70, 'What is the purpose of Lok Adalats in the Indian legal system?', 'Lok Adalats ("people''s courts") are forums for the amicable, speedy settlement of disputes through conciliation and compromise, particularly for cases like minor criminal matters, motor accident claims, and civil disputes, reducing the burden on regular courts and avoiding lengthy litigation.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q072', 'police-exam-bank', 'Law & Legal Awareness', 1, 71, 'What is the role of the National Legal Services Authority (NALSA)?', 'NALSA is a statutory body established to provide free legal aid and services to weaker and marginalized sections of society, organize Lok Adalats, and promote legal literacy, ensuring that access to justice is not denied due to economic or social disadvantage.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q073', 'police-exam-bank', 'Law & Legal Awareness', 1, 72, 'What is the significance of Article 22 of the Indian Constitution for an arrested person?', 'Article 22 guarantees certain protections to an arrested person, including the right to be informed of the grounds of arrest, the right to consult and be defended by a legal practitioner of choice, and the right to be produced before a magistrate within 24 hours of arrest (excluding travel time).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q074', 'police-exam-bank', 'Law & Legal Awareness', 1, 73, 'What is the legal concept of "double jeopardy," and which constitutional provision protects against it in India?', 'Double jeopardy is the principle that a person should not be tried or punished twice for the same offence. In India, this protection is provided under Article 20(2) of the Constitution, which states that no person shall be prosecuted and punished for the same offence more than once.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q075', 'police-exam-bank', 'Law & Legal Awareness', 1, 74, 'What is the difference between a "First Appeal" and a "Second Appeal" in the Indian judicial system?', 'A First Appeal is the initial appeal against a trial court''s judgment, typically filed before a higher court reviewing both facts and law. A Second Appeal is a further appeal against the decision of the first appellate court, usually restricted to significant questions of law rather than re-examining factual findings.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q076', 'police-exam-bank', 'Law & Legal Awareness', 1, 75, 'What is the role of a Public Prosecutor in a criminal trial?', 'A Public Prosecutor is a legal officer appointed by the government to represent the State in criminal proceedings, presenting evidence and arguments to prove the guilt of the accused, as distinguished from a private lawyer who represents an individual party''s personal interests.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q077', 'police-exam-bank', 'Law & Legal Awareness', 1, 76, 'What is the difference between "acquittal" and "discharge" in a criminal case?', 'An acquittal is a verdict given after a full trial where the court finds the accused not guilty based on the evidence presented. A discharge occurs at an earlier stage, before a full trial begins, when the court finds insufficient grounds to proceed against the accused and releases them from the case without going through trial.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q078', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 77, 'What is the purpose of Facial Recognition Technology (FRT) systems being adopted by Indian police forces?', 'FRT systems help police identify suspects, missing persons, or persons of interest by matching facial images captured on CCTV or by officers against existing databases, speeding up identification in investigations and at large public events where manual verification would be impractical.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q079', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 78, 'What is the purpose of body-worn cameras being deployed by police personnel?', 'Body-worn cameras record police interactions with the public in real time, improving accountability and transparency, providing reliable evidence during disputes or complaints, and often having a deterrent effect on both officer misconduct and public aggression during confrontations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q080', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 79, 'What is an "e-challan" system, and how does it change traffic enforcement?', 'An e-challan system allows traffic violations to be recorded and fines issued electronically, often using cameras or handheld devices linked to a central database, reducing cash handling, enabling faster processing, and allowing violators to pay fines online rather than in person at a police station or court.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q081', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 80, 'What is the primary role of the National Disaster Response Force (NDRF)?', 'The NDRF is a specialized force under the National Disaster Management Authority, trained and equipped to respond to natural and man-made disasters such as earthquakes, floods, and chemical/biological/nuclear emergencies, conducting search, rescue, and relief operations across the country.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q082', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 81, 'What is the role of state Anti-Human Trafficking Units (AHTUs)?', 'Anti-Human Trafficking Units are specialized police units set up at the district level to prevent, detect, and investigate cases of human trafficking, rescue victims, and coordinate with NGOs and other agencies for the rehabilitation of trafficking survivors.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q083', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 82, 'What is the purpose of the Narco-Coordination Centre (NCORD) mechanism?', 'NCORD is a multi-tiered coordination mechanism involving central and state agencies, set up to improve intelligence sharing and joint operational action against drug trafficking networks across different levels — from the national level down to the district level.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q084', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 83, 'What is the significance of the "112" emergency helpline number in India?', '"112" is India''s single, unified emergency helpline number, integrating police, fire, and ambulance emergency services into one easily memorable number under the Emergency Response Support System (ERSS), allowing citizens to seek any form of emergency assistance through a single call.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q085', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 84, 'What is the purpose of the "181" or similar dedicated Women Helpline numbers run by several states?', 'Dedicated Women Helpline numbers provide a confidential channel for women to report domestic violence, harassment, or any safety concern, connecting them to counseling, police assistance, or shelter services as needed, often operating 24x7.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q086', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 85, 'What is the role of Childline (1098) in India?', 'Childline 1098 is a 24-hour national helpline for children in distress, providing emergency assistance and referral services for children facing abuse, abandonment, trafficking, or other forms of exploitation, connecting them with police, child welfare committees, or shelter homes as required.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q087', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 86, 'What is the purpose of Safe City projects being implemented in several Indian metropolitan areas?', 'Safe City projects aim to improve women''s safety in urban areas through measures such as improved street lighting, increased CCTV surveillance, dedicated women''s safety mobile apps, rapid-response units, and better-designed public transport and infrastructure to reduce opportunities for crime against women.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q088', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 87, 'What is the significance of Interceptor vehicles used by traffic police?', 'Interceptor vehicles are specially equipped police vehicles fitted with speed-detection radar/laser guns, breath analyzers, and often cameras, enabling traffic police to detect speeding, drunk driving, and other violations in real time while patrolling highways and city roads.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q089', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 88, 'What is the purpose of the Integrated Road Accident Database (iRAD) initiative?', 'iRAD is a digital system for recording detailed data on road accidents across India, used by police and transport authorities to analyze accident patterns, identify high-risk locations ("black spots"), and design targeted road safety interventions.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q090', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 89, 'What is the role of the Bureau of Police Research and Development (BPR&D)?', 'BPR&D is an organization under the Ministry of Home Affairs that conducts research on policing issues, assists in modernizing police forces, develops training curricula, and promotes the adoption of new technology and best practices across state and central police organizations.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q091', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 90, 'What is the significance of the Inter-Operable Criminal Justice System (ICJS) mobile app for citizens?', 'The ICJS-linked citizen services allow the public to check case status, FIR details, court hearing dates, and prisoner information online, improving transparency and reducing the need for citizens to physically visit police stations or courts for routine status updates.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q092', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 91, 'What is the purpose of drone surveillance being adopted by Indian police for law-and-order management?', 'Drones provide aerial monitoring during large public gatherings, protests, or VIP movements, helping police assess crowd behavior, identify potential threats, and coordinate ground response more effectively than relying solely on ground-level observation.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q093', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 92, 'What is the significance of the "One Nation, One Challan" initiative?', '"One Nation, One Challan" is a unified digital platform intended to standardize and link traffic violation and e-challan records across states, enabling seamless tracking and payment of fines regardless of where in India a vehicle is registered or where the violation occurred.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q094', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 93, 'What is the role of State Disaster Response Forces (SDRFs), as distinguished from the NDRF?', 'State Disaster Response Forces are state-level specialized units, often raised from existing state police or armed police personnel and trained similarly to the NDRF, meant to provide a faster first-response capability for disasters within the state before or alongside NDRF deployment.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q095', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 94, 'What is the purpose of Automatic Number Plate Recognition (ANPR) cameras used by traffic and law-enforcement agencies?', 'ANPR cameras automatically capture and read vehicle number plates, allowing police to track stolen vehicles, detect violations like driving without valid documents, and cross-check vehicles against watchlists in real time as they pass monitored points.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q096', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 95, 'What is the significance of the National Automated Fingerprint Identification System (NAFIS)?', 'NAFIS is a centralized, nationwide digital database of fingerprint records linked to criminal cases, allowing police across different states to quickly search and match fingerprints found at crime scenes against a national database, rather than relying only on state-level records.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q097', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 96, 'What is the purpose of Command and Control Centres being set up in major Indian cities?', 'Command and Control Centres integrate CCTV feeds, emergency helpline data, and communication systems from across a city into a single monitoring hub, allowing police to coordinate a faster, better-informed response to incidents, traffic issues, and public safety concerns in real time.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q098', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 97, 'What is the role of the Anti-Rowdy Sheet or history-sheet system maintained by police on repeat offenders?', 'A history-sheet is a police record maintained on individuals with a history of repeated criminal activity, documenting their past offences and movements, which helps police in preventive monitoring and quick identification of likely suspects when similar crimes occur in an area.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q099', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 98, 'What is the purpose of the POSH Act (Prevention of Sexual Harassment at Workplace Act, 2013) in relation to police coordination with organizations?', 'The POSH Act requires workplaces to set up Internal Complaints Committees to address sexual harassment complaints, and police may be approached when a complaint also involves a criminal offence, working alongside these internal committees rather than replacing their role in workplace-level redressal.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q100', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 99, 'What is the significance of helpline number "1930" in India?', '"1930" is India''s national cybercrime helpline number, allowing victims of financial cyber fraud to report incidents immediately so that banks and payment platforms can be alerted quickly to freeze or trace fraudulent transactions before the funds are withdrawn.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q031', 'ssc-english-bank', 'English Language & Grammar', 0, 30, 'What does the phrasal verb "look into" mean? Give an example.', '"Look into" means to investigate or examine something carefully. Example: "The police agreed to look into the matter of the missing documents."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q032', 'ssc-english-bank', 'English Language & Grammar', 0, 31, 'What is the meaning of "call off," and how is it typically used?', '"Call off" means to cancel a planned event or activity. For example, "The organizers had to call off the match due to heavy rain."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q033', 'ssc-english-bank', 'English Language & Grammar', 0, 32, 'What does "put up with" mean?', '"Put up with" means to tolerate or endure something unpleasant without complaining. Example: "She had to put up with her noisy neighbors for years."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q034', 'ssc-english-bank', 'English Language & Grammar', 0, 33, 'What is the meaning of "bring up" in the context of a conversation?', '"Bring up" means to introduce a topic or subject for discussion. For example, "He brought up the issue of salary increments during the meeting."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q035', 'ssc-english-bank', 'English Language & Grammar', 0, 34, 'What does "carry out" mean?', '"Carry out" means to perform or execute a task, plan, or instruction. Example: "The team carried out the experiment exactly as planned."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q036', 'ssc-english-bank', 'English Language & Grammar', 0, 35, 'What is the meaning of "go through" when referring to a document or process?', '"Go through" means to examine or review something carefully, or to experience a difficult process. Example: "Please go through the report before the meeting" (examine carefully) or "She went through a tough time after the accident" (experienced).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q037', 'ssc-english-bank', 'English Language & Grammar', 0, 36, 'What does "break down" mean, and give two different contexts in which it can be used?', '"Break down" can mean a machine stops functioning (e.g., "The car broke down on the highway") or to become overwhelmed emotionally (e.g., "She broke down in tears after hearing the news"). It can also mean to divide something into smaller parts (e.g., "Let''s break down the problem into steps").', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q038', 'ssc-english-bank', 'English Language & Grammar', 0, 37, 'What does the idiom "to beat around the bush" mean?', '"To beat around the bush" means to avoid talking about something directly, often by delaying or being vague instead of getting to the point.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q039', 'ssc-english-bank', 'English Language & Grammar', 0, 38, 'What is the meaning of "to add insult to injury"?', '"To add insult to injury" means to make a bad situation even worse, especially by doing or saying something that causes additional offense or harm after an initial problem has already occurred.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q040', 'ssc-english-bank', 'English Language & Grammar', 0, 39, 'What does "to hit the nail on the head" mean?', '"To hit the nail on the head" means to describe exactly what is causing a situation or problem, or to be precisely correct about something.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q041', 'ssc-english-bank', 'English Language & Grammar', 0, 40, 'What is the meaning of the idiom "once in a blue moon"?', '"Once in a blue moon" means something that happens very rarely or almost never, referring to an event that occurs infrequently.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q042', 'ssc-english-bank', 'English Language & Grammar', 0, 41, 'What does "to burn the midnight oil" mean?', '"To burn the midnight oil" means to work or study late into the night, typically to complete an important task or prepare for an exam.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q043', 'ssc-english-bank', 'English Language & Grammar', 0, 42, 'What is the meaning of "to take something with a pinch of salt"?', '"To take something with a pinch of salt" means to not fully believe something that one hears, especially because it seems unlikely to be completely true or accurate.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q044', 'ssc-english-bank', 'English Language & Grammar', 0, 43, 'What single word means "a person who cannot read or write"?', '"Illiterate" is the single word that means a person who cannot read or write.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q045', 'ssc-english-bank', 'English Language & Grammar', 0, 44, 'What single word describes "a place where weapons and ammunition are stored"?', '"Arsenal" is the single word for a place where weapons and ammunition are stored.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q046', 'ssc-english-bank', 'English Language & Grammar', 0, 45, 'What single word means "a person who loves books"?', '"Bibliophile" is the single word meaning a person who loves and collects books.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q047', 'ssc-english-bank', 'English Language & Grammar', 0, 46, 'What single word describes "government by the people"?', '"Democracy" is the single word for a system of government by the people, typically through elected representatives.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q048', 'ssc-english-bank', 'English Language & Grammar', 0, 47, 'What single word means "one who eats too much"?', '"Glutton" is the single word for a person who eats excessively or has an insatiable appetite.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q049', 'ssc-english-bank', 'English Language & Grammar', 0, 48, 'What single word describes "a word that is opposite in meaning to another word"?', '"Antonym" is the single word for a word that has the opposite meaning of another word.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q050', 'ssc-english-bank', 'English Language & Grammar', 0, 49, 'What single word means "a person who can speak many languages"?', '"Polyglot" is the single word for a person who knows and can speak many languages.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q051', 'ssc-english-bank', 'English Language & Grammar', 0, 50, 'What does the prefix "mis-" generally indicate, and give an example word?', 'The prefix "mis-" generally indicates something done badly, wrongly, or incorrectly. For example, "misunderstand" means to understand something incorrectly.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q052', 'ssc-english-bank', 'English Language & Grammar', 0, 51, 'What does the suffix "-less" mean when added to a noun, and give an example?', 'The suffix "-less" means "without" or "lacking" when added to a noun. For example, "hopeless" means without hope, and "careless" means without care.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q053', 'ssc-english-bank', 'English Language & Grammar', 0, 52, 'What is the function of the prefix "re-," and give an example?', 'The prefix "re-" generally means "again" or "back," indicating repetition or reversal. For example, "rewrite" means to write again, and "return" means to go back.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q054', 'ssc-english-bank', 'English Language & Grammar', 0, 53, 'What does the suffix "-ful" typically indicate, and give an example?', 'The suffix "-ful" typically indicates "full of" or "characterized by" a quality. For example, "beautiful" means full of beauty, and "helpful" means characterized by being of help.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q055', 'ssc-english-bank', 'English Language & Grammar', 0, 54, 'What is the difference between the prefixes "in-" and "un-" when forming negative adjectives, and give an example of each?', 'Both "in-" and "un-" can form negative adjectives, but which one applies depends on the specific word, since there is no single rule and usage must often be learned individually. For example, "incomplete" (not "uncomplete") uses "in-," while "unhappy" (not "inhappy") uses "un-."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q056', 'ssc-english-bank', 'English Language & Grammar', 0, 55, 'What part of speech does the suffix "-tion" typically create, and give an example?', 'The suffix "-tion" typically transforms a verb into a noun, indicating the action or result of that verb. For example, "educate" (verb) becomes "education" (noun).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q057', 'ssc-english-bank', 'English Language & Grammar', 0, 56, 'What is the comparative and superlative form of the adjective "good"?', 'The comparative form of "good" is "better," and the superlative form is "best" — these are irregular forms that do not follow the standard "-er"/"-est" pattern.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q058', 'ssc-english-bank', 'English Language & Grammar', 0, 57, 'How do you form the comparative and superlative of a two-syllable adjective ending in "-y," such as "happy"?', 'For two-syllable adjectives ending in "-y," change the "y" to "i" and add "-er" for the comparative and "-est" for the superlative. For example, "happy" becomes "happier" (comparative) and "happiest" (superlative).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q059', 'ssc-english-bank', 'English Language & Grammar', 0, 58, 'What is the comparative and superlative form of "little" when referring to quantity (not size)?', 'When referring to quantity, "little" becomes "less" (comparative) and "least" (superlative) — these are irregular forms distinct from "little, littler, littlest," which is used only when referring to physical size.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q060', 'ssc-english-bank', 'English Language & Grammar', 0, 59, 'What is the rule for forming comparatives and superlatives of longer adjectives (generally three or more syllables)?', 'For longer adjectives, instead of adding "-er" or "-est," use "more" before the adjective for the comparative and "most" for the superlative. For example, "beautiful" becomes "more beautiful" and "most beautiful," not "beautifuler" or "beautifulest."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q061', 'ssc-english-bank', 'English Language & Grammar', 0, 60, 'What is wrong with the sentence "This is the most best solution," and how should it be corrected?', 'The sentence contains a double superlative error, since "best" is already the superlative form of "good" and does not need "most" added before it. The correct sentence is simply "This is the best solution."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q062', 'ssc-english-bank', 'English Language & Grammar', 0, 61, 'What is a "zero conditional" sentence used for, and give an example?', 'A zero conditional sentence expresses general truths or facts that are always true when the condition is met, using the present simple tense in both clauses. Example: "If you heat water to 100 degrees Celsius, it boils."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q063', 'ssc-english-bank', 'English Language & Grammar', 0, 62, 'What is the structure and use of a "first conditional" sentence?', 'A first conditional sentence describes a real and likely possibility in the future, using "if" plus present simple in the condition clause, and "will" plus base verb in the result clause. Example: "If it rains tomorrow, we will cancel the picnic."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q064', 'ssc-english-bank', 'English Language & Grammar', 0, 63, 'What is the structure and use of a "second conditional" sentence?', 'A second conditional sentence describes a hypothetical or unlikely situation in the present or future, using "if" plus past simple in the condition clause, and "would" plus base verb in the result clause. Example: "If I won the lottery, I would travel the world."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q065', 'ssc-english-bank', 'English Language & Grammar', 0, 64, 'What is the structure and use of a "third conditional" sentence?', 'A third conditional sentence describes a hypothetical situation in the past that did not actually happen, using "if" plus past perfect in the condition clause, and "would have" plus past participle in the result clause. Example: "If she had studied harder, she would have passed the exam."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q066', 'ssc-english-bank', 'English Language & Grammar', 0, 65, 'What is a "mixed conditional" sentence, and give an example?', 'A mixed conditional combines elements of different conditional types to describe a situation where the time in the "if" clause and the result clause don''t match, such as a past condition with a present result. Example: "If he had taken the job offer, he would be living in Mumbai now" — the condition refers to the past, but the result describes the present.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q067', 'ssc-english-bank', 'English Language & Grammar', 0, 66, 'How do you convert a direct "yes/no" question into reported speech?', 'A direct yes/no question is converted into reported speech using "if" or "whether," with the word order changed back to a statement (subject before verb), and the question mark removed. For example, "She asked, ''Are you coming?''" becomes "She asked if I was coming."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q068', 'ssc-english-bank', 'English Language & Grammar', 0, 67, 'How do you convert a direct "wh-" question (e.g., "where," "what," "why") into reported speech?', 'A direct wh-question keeps the question word but changes the word order to a statement structure (subject before verb) and removes the question mark. For example, "He asked, ''Where do you live?''" becomes "He asked where I lived."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q069', 'ssc-english-bank', 'English Language & Grammar', 0, 68, 'How do you convert a direct command into reported speech?', 'A direct command is reported using an infinitive verb form (to plus base verb), typically introduced by a reporting verb like "told" or "asked," without using "that." For example, "She said, ''Close the door.''" becomes "She told him to close the door."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q070', 'ssc-english-bank', 'English Language & Grammar', 0, 69, 'How do you convert a direct negative command into reported speech?', 'A direct negative command is reported by adding "not" before the infinitive. For example, "The teacher said, ''Do not run in the corridor.''" becomes "The teacher told the students not to run in the corridor."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q071', 'ssc-english-bank', 'English Language & Grammar', 0, 70, 'How does the reporting verb change when reporting a request (as opposed to a command) in indirect speech?', 'When reporting a polite request, the reporting verb is often changed to something like "requested" or "asked," rather than "ordered" or "told," to reflect the more polite tone of the original request. For example, "Could you help me?" becomes "She requested him to help her" or "She asked him to help her."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q072', 'ssc-english-bank', 'English Language & Grammar', 0, 71, 'How do you report an exclamatory sentence (e.g., "What a beautiful view!") in indirect speech?', 'An exclamatory sentence is usually reported by converting it into a statement form, often using a phrase like "exclaimed that" and expressing the sentiment descriptively. For example, "What a beautiful view!" could become "She exclaimed that the view was very beautiful."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q073', 'ssc-english-bank', 'English Language & Grammar', 0, 72, 'When should a semicolon be used to join two sentences?', 'A semicolon can be used to join two independent clauses (complete sentences) that are closely related in meaning, without using a coordinating conjunction like "and" or "but." For example, "It was raining heavily; the match was postponed."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q074', 'ssc-english-bank', 'English Language & Grammar', 0, 73, 'What is the correct use of an apostrophe to show possession for a singular noun?', 'For a singular noun, add an apostrophe followed by "s" to show possession. For example, "the girl''s bag" means the bag belonging to one girl.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q075', 'ssc-english-bank', 'English Language & Grammar', 0, 74, 'What is the correct use of an apostrophe to show possession for a plural noun ending in "s"?', 'For a plural noun that already ends in "s," add only an apostrophe after the "s," without an additional "s." For example, "the girls'' bags" means the bags belonging to multiple girls.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q076', 'ssc-english-bank', 'English Language & Grammar', 0, 75, 'When should a colon be used in a sentence?', 'A colon is used to introduce a list, explanation, or elaboration that follows a complete independent clause. For example, "She packed three things: a book, a water bottle, and a map."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q077', 'ssc-english-bank', 'English Language & Grammar', 0, 76, 'What is the rule for using a comma before a coordinating conjunction (like "and," "but," "or") joining two independent clauses?', 'When a coordinating conjunction joins two independent clauses, each capable of standing alone as a sentence, a comma should be placed before the conjunction. For example, "He wanted to go for a walk, but it started raining."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q078', 'ssc-english-bank', 'English Language & Grammar', 0, 77, 'What is the purpose of using quotation marks in a sentence?', 'Quotation marks are used to enclose a direct quotation of someone''s exact words, to indicate the title of short works such as articles or poems, or sometimes to indicate irony or a non-literal use of a word.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q079', 'ssc-english-bank', 'English Language & Grammar', 0, 78, 'What is the difference between a hyphen and a dash, and when is each typically used?', 'A hyphen (-) is shorter and is used to join compound words or split words at the end of a line (e.g., "well-known"). A dash, which is longer, is used to indicate a break in thought, add emphasis, or set off an explanatory phrase within a sentence (e.g., "She finally arrived, an hour late.").', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q080', 'ssc-english-bank', 'English Language & Grammar', 0, 79, 'What is the difference between "stationary" and "stationery"?', '"Stationary" (with an "a") means not moving, fixed in one place. "Stationery" (with an "e") refers to writing materials such as paper, pens, and envelopes.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q081', 'ssc-english-bank', 'English Language & Grammar', 0, 80, 'What is the difference between "principal" and "principle"?', '"Principal" (as a noun) refers to the head of a school or an amount of money, as in a loan, or (as an adjective) means "main" or "most important." "Principle" refers to a fundamental truth, rule, or standard of behavior.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q082', 'ssc-english-bank', 'English Language & Grammar', 0, 81, 'What is the difference between "complement" and "compliment"?', '"Complement" means something that completes or goes well with something else (e.g., "The scarf complements her outfit"). "Compliment" means a polite expression of praise or admiration (e.g., "He gave her a compliment on her presentation").', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q083', 'ssc-english-bank', 'English Language & Grammar', 0, 82, 'What is the difference between "council" and "counsel"?', 'A "council" is a group of people formally appointed to discuss or manage a particular matter (e.g., "the city council"). "Counsel" means advice, or, as a verb, to give advice (e.g., "The lawyer gave her counsel on the case").', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q084', 'ssc-english-bank', 'English Language & Grammar', 0, 83, 'What is the difference between "desert" and "dessert"?', 'A "desert" (one "s") is a dry, barren area of land. "Dessert" (two "s"s) is a sweet course eaten at the end of a meal.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q085', 'ssc-english-bank', 'English Language & Grammar', 0, 84, 'What is the difference between "elicit" and "illicit"?', '"Elicit" is a verb meaning to draw out a response or reaction (e.g., "The question elicited a strong reaction"). "Illicit" is an adjective meaning not legally permitted or forbidden (e.g., "illicit drugs").', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q086', 'ssc-english-bank', 'English Language & Grammar', 0, 85, 'What is the difference between "accept" and "except"?', '"Accept" is a verb meaning to agree to receive or take something (e.g., "She accepted the award"). "Except" is usually a preposition or conjunction meaning "excluding" or "other than" (e.g., "Everyone came except him").', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q087', 'ssc-english-bank', 'English Language & Grammar', 0, 86, 'What is the difference between "advice" and "advise"?', '"Advice" (with a "c") is a noun meaning a recommendation or suggestion (e.g., "She gave good advice"). "Advise" (with an "s") is a verb meaning to give a recommendation (e.g., "I advise you to be careful").', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q088', 'ssc-english-bank', 'English Language & Grammar', 0, 87, 'What is the difference between "allusion" and "illusion"?', 'An "allusion" is an indirect reference to something, often in literature (e.g., "The poem contains an allusion to Greek mythology"). An "illusion" is a false or misleading perception of reality (e.g., "The painting creates an illusion of depth").', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q089', 'ssc-english-bank', 'English Language & Grammar', 0, 88, 'What is the difference between "eminent" and "imminent"?', '"Eminent" means famous, distinguished, or notable (e.g., "an eminent scientist"). "Imminent" means about to happen very soon (e.g., "The storm is imminent").', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q090', 'ssc-english-bank', 'English Language & Grammar', 0, 89, 'What is the correct spelling of the commonly misspelled word often written as "accomodate"?', 'The correct spelling is "accommodate," with two "c"s and two "m"s.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q091', 'ssc-english-bank', 'English Language & Grammar', 0, 90, 'What is the correct spelling of the commonly misspelled word often written as "seperate"?', 'The correct spelling is "separate," with an "a" in the middle — remember, there''s "a rat" in "sep-a-rate."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q092', 'ssc-english-bank', 'English Language & Grammar', 0, 91, 'What is the correct spelling of the commonly misspelled word often written as "recieve"?', 'The correct spelling is "receive," following the rule "i before e, except after c."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q093', 'ssc-english-bank', 'English Language & Grammar', 0, 92, 'What is the correct spelling of the commonly misspelled word often written as "occured"?', 'The correct spelling is "occurred," with two "r"s, since the final consonant of "occur" is doubled before adding "-ed."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q094', 'ssc-english-bank', 'English Language & Grammar', 0, 93, 'What is the correct spelling of the commonly misspelled word often written as "goverment"?', 'The correct spelling is "government," with an "n" before the final "ment," which is often dropped by mistake in casual writing or pronunciation.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q095', 'ssc-english-bank', 'English Language & Grammar', 0, 94, 'What is the correct spelling of the commonly misspelled word often written as "concious"?', 'The correct spelling is "conscious," with the letters "s-c-i-o-u-s" at the end, not "c-i-o-u-s" alone.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q096', 'ssc-english-bank', 'English Language & Grammar', 0, 95, 'What is a synonym for "abundant," and what is its antonym?', 'A synonym for "abundant" is "plentiful," meaning existing in large quantities. An antonym for "abundant" is "scarce," meaning in short supply.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q097', 'ssc-english-bank', 'English Language & Grammar', 0, 96, 'What is a synonym for "benevolent," and what is its antonym?', 'A synonym for "benevolent" is "kind" or "charitable," meaning well-meaning and generous. An antonym for "benevolent" is "malevolent," meaning having or showing a wish to do harm.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q098', 'ssc-english-bank', 'English Language & Grammar', 0, 97, 'What is a synonym for "meticulous," and what is its antonym?', 'A synonym for "meticulous" is "thorough" or "precise," meaning showing great attention to detail. An antonym for "meticulous" is "careless" or "sloppy."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q099', 'ssc-english-bank', 'English Language & Grammar', 0, 98, 'What is a synonym for "candid," and what is its antonym?', 'A synonym for "candid" is "frank" or "honest," meaning truthful and straightforward in speech. An antonym for "candid" is "evasive" or "deceptive."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q100', 'ssc-english-bank', 'English Language & Grammar', 0, 99, 'What is a synonym for "ephemeral," and what is its antonym?', 'A synonym for "ephemeral" is "transient" or "fleeting," meaning lasting for a very short time. An antonym for "ephemeral" is "permanent" or "everlasting."', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q031', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 30, 'When was the Reserve Bank of India established, and under what act?', 'The RBI was established on April 1, 1935, under the Reserve Bank of India Act, 1934, originally as a privately owned institution. It was nationalized in 1949, after which it has operated fully under government ownership as India''s central bank.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q032', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 31, 'What event led to the nationalization of 14 major commercial banks in India, and in which year did it happen?', 'In 1969, the Government of India nationalized 14 major commercial banks (each with deposits exceeding Rs. 50 crore) under Prime Minister Indira Gandhi, primarily to direct credit toward priority sectors like agriculture and small industries, which private banks had largely neglected. A second round nationalized 6 more banks in 1980.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q033', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 32, 'What was the primary objective behind bank nationalization in India?', 'The primary objective was to extend banking services to rural and underserved areas, redirect credit flows away from a few large industrial houses and toward priority sectors such as agriculture, small-scale industries, and exports, and bring the banking system under greater government control to support planned economic development.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q034', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 33, 'Who is considered the first Governor of the Reserve Bank of India?', 'Sir Osborne Smith was the first Governor of the Reserve Bank of India, serving from 1935 to 1937. C.D. Deshmukh, who became Governor in 1943, was the first Indian to hold the position.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q035', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 34, 'What is the significance of the "Narasimham Committee" in Indian banking reform?', 'The Narasimham Committee (1991 and 1998) recommended major banking sector reforms in India, including reducing statutory pre-emptions (CRR/SLR), strengthening capital adequacy norms, improving asset classification and provisioning for NPAs, and increasing competition and autonomy for banks, laying the foundation for post-liberalization banking reforms.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q036', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 35, 'What was the "Swabhimaan" campaign associated with Indian banking?', 'Swabhimaan was a financial inclusion campaign launched in 2011 to extend banking services to villages with a population of over 2,000 that lacked banking facilities, using business correspondents and low-cost banking technology, serving as a precursor to the later, more comprehensive Pradhan Mantri Jan Dhan Yojana.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q037', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 36, 'What is a "cooperative bank," and how does its ownership structure differ from a commercial bank?', 'A cooperative bank is owned and controlled by its own members, who are also its customers, operating on a "one member, one vote" principle rather than being driven by shareholder profit. Commercial banks, by contrast, are owned by shareholders seeking returns on their investment, and customers have no ownership stake.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q038', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 37, 'What is a "Regional Rural Bank (RRB)," and what is its primary purpose?', 'A Regional Rural Bank is a type of bank established under the RRB Act, 1976, jointly sponsored by the Central Government, a state government, and a commercial bank, with the primary purpose of providing banking and credit facilities to rural and semi-urban areas, particularly for agriculture and small-scale industries.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q039', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 38, 'What is a "payments bank," and what key restriction distinguishes it from a regular commercial bank?', 'A payments bank is a differentiated banking license category in India that can accept deposits (up to a specified limit per customer), offer remittance services, and issue debit cards, but it cannot issue loans or credit cards, distinguishing it from a full-service commercial bank. Examples include Airtel Payments Bank and India Post Payments Bank.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q040', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 39, 'What is a "small finance bank," and who is it primarily meant to serve?', 'A small finance bank is a specialized banking license category aimed at providing basic banking services, such as savings, deposits, and credit, primarily to underserved sections like small business units, small and marginal farmers, micro and small industries, and unorganized sector entities who typically lack easy access to mainstream banking.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q041', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 40, 'What is the difference between a "public sector bank" and a "private sector bank" in India?', 'A public sector bank has majority ownership (more than 50% of shares) held by the Government of India, such as State Bank of India or Punjab National Bank. A private sector bank is majority-owned by private shareholders or promoters, such as HDFC Bank or ICICI Bank, though it is still regulated by the RBI like any other scheduled bank.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q042', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 41, 'What is a "foreign bank" in the Indian banking context, and how does it typically operate?', 'A foreign bank is a bank incorporated outside India that operates within the country through branches or representative offices, subject to RBI regulation, typically serving large corporate clients, trade finance needs, and niche retail segments. Examples operating in India include Citibank, HSBC, and Standard Chartered Bank.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q043', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 42, 'What is the role of NABARD in Indian rural banking?', 'NABARD (National Bank for Agriculture and Rural Development) is an apex development financial institution that provides refinance support to banks and financial institutions for agriculture and rural development, oversees the regulation of Regional Rural Banks and cooperative banks, and promotes rural credit and infrastructure through various schemes.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q044', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 43, 'What is an "Open Market Operation (OMO)," and how does RBI use it?', 'An Open Market Operation involves the RBI buying or selling government securities in the open market to regulate money supply and liquidity in the banking system. Buying securities injects money into the system (increasing liquidity), while selling securities absorbs excess money (reducing liquidity).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q045', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 44, 'What is the "Marginal Standing Facility (MSF)," and how does it differ from the repo rate facility?', 'The MSF is a facility that allows scheduled banks to borrow overnight funds from the RBI against government securities, even if it means dipping below their mandatory SLR requirement, typically at a rate higher than the repo rate. It serves as an emergency liquidity window for banks facing sudden, unanticipated shortfalls.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q046', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 45, 'What is the "bank rate," and how does it differ from the repo rate?', 'The bank rate is the rate at which RBI lends long-term funds to commercial banks without any collateral or repurchase agreement, and is generally used as a signaling or penal rate. The repo rate, by contrast, is used for short-term lending against government securities with an agreement to repurchase, and is RBI''s primary tool for day-to-day liquidity management.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q047', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 46, 'What is the "Liquidity Adjustment Facility (LAF)," and what two tools does it primarily consist of?', 'The LAF is a monetary policy tool that allows banks to manage short-term liquidity mismatches with the RBI. It primarily consists of the repo rate (for borrowing from RBI) and the reverse repo rate (for depositing surplus funds with RBI), allowing RBI to inject or absorb liquidity as needed.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q048', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 47, 'What is "quantitative easing," and is it typically used by the RBI?', 'Quantitative easing is a monetary policy where a central bank purchases large quantities of financial assets (often long-term government bonds) to inject liquidity directly into the economy when conventional interest rate tools have limited effect, often used by central banks like the US Federal Reserve during crises; it has not been a primary tool of the RBI''s standard policy framework.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q049', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 48, 'What is the purpose of periodic "Statutory Liquidity Ratio (SLR)" changes, and who decides them?', 'The RBI''s Monetary Policy Committee and the RBI itself periodically review and adjust the SLR requirement to balance banks'' liquidity needs against the government''s need for banks to hold a stable base of government securities, influencing how much credit banks can extend to the broader economy versus how much they must park in safe government instruments.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q050', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 49, 'What is a "negotiable instrument," and name three common types.', 'A negotiable instrument is a document guaranteeing payment of a specific amount of money, either on demand or at a set time, that can be transferred from one person to another. Common types include cheques, promissory notes, and bills of exchange.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q051', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 50, 'What is a "crossed cheque," and what is its purpose?', 'A crossed cheque has two parallel lines drawn across its face, sometimes with words like "Account Payee Only" written between them, indicating that the cheque amount must be credited directly to the payee''s bank account rather than being paid out in cash over the counter, improving traceability and security.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q052', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 51, 'What is a "bearer cheque," and how does it differ from an "order cheque"?', 'A bearer cheque can be encashed by whoever is holding (bearing) it, without requiring endorsement or identification beyond presenting the cheque. An order cheque is payable only to the specific named payee (or someone they endorse it to), requiring the payee''s signature for the amount to be paid.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q053', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 52, 'What does "dishonour of cheque" mean, and under which law is it a punishable offence in India?', 'Dishonour of cheque occurs when a bank refuses to honor a cheque, commonly due to insufficient funds in the drawer''s account. Under Section 138 of the Negotiable Instruments Act, 1881, dishonouring a cheque issued to discharge a debt is a punishable criminal offence, which can result in fine and/or imprisonment.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q054', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 53, 'What is a "post-dated cheque"?', 'A post-dated cheque is a cheque that bears a future date, meaning the bank will not honor it for payment until that specified date arrives, even if presented earlier.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q055', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 54, 'What is the maximum validity period of a cheque in India, as per current RBI guidelines?', 'As per current RBI guidelines, a cheque in India is valid for 3 months from the date mentioned on it, after which it becomes "stale" and banks will not honor it for payment unless revalidated by the issuer.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q056', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 55, 'What is a "demand draft (DD)," and how does it differ from a cheque?', 'A demand draft is a prepaid negotiable instrument issued by a bank, guaranteeing payment since the amount is already deducted from the purchaser''s account at the time of issue. A cheque, by contrast, is only a payment instruction and is not guaranteed — it can bounce if the drawer''s account lacks sufficient funds.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q057', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 56, 'What is "endorsement" of a cheque, and what does it typically involve?', 'Endorsement is the act of the payee signing on the back of a cheque to transfer their right to receive payment to another person, or to allow it to be deposited into a specific account, effectively authorizing the next step in the cheque''s processing.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q058', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 57, 'What is the role of a "credit rating agency," and name two Indian credit rating agencies.', 'A credit rating agency assesses the creditworthiness of borrowers, including companies, governments, and financial instruments, assigning ratings that indicate the relative risk of default, helping investors make informed lending and investment decisions. Prominent Indian credit rating agencies include CRISIL and ICRA.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q059', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 58, 'What does a credit rating of "AAA" generally indicate about an issuer or instrument?', 'An "AAA" rating is typically the highest credit rating assigned by rating agencies, indicating the lowest possible credit risk and the highest likelihood that the issuer will meet its financial obligations in full and on time.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q060', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 59, 'What is a "credit score" for an individual, and which Indian agency is best known for providing it?', 'A credit score is a numerical representation (commonly ranging from 300 to 900 in India) of an individual''s creditworthiness, based on their credit history, repayment behavior, and existing debt. CIBIL (TransUnion CIBIL) is the agency best known in India for providing individual credit scores.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q061', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 60, 'What is the difference between a "sovereign credit rating" and a "corporate credit rating"?', 'A sovereign credit rating assesses the creditworthiness of a national government — its ability to repay its debt obligations — while a corporate credit rating assesses the creditworthiness of an individual company. Sovereign ratings often influence the maximum possible rating a company within that country can achieve.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q062', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 61, 'What does it mean when a rating agency places an issuer "under watch" or assigns a "negative outlook"?', 'It signals that the agency believes the issuer''s creditworthiness may change, typically for the worse in a negative outlook, in the near term due to specific emerging risks or developments, and that a formal rating change may follow after further review, without immediately changing the current rating itself.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q063', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 62, 'What is the key difference between "life insurance" and "general insurance"?', 'Life insurance provides a payout to beneficiaries upon the death of the insured person (or after a specified maturity period), focusing on long-term financial protection for dependents. General insurance covers non-life risks such as health, motor vehicles, property, and travel, typically providing compensation for specific losses or damages within a policy term.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q064', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 63, 'What is the role of the Insurance Regulatory and Development Authority of India (IRDAI)?', 'IRDAI is the statutory body responsible for regulating and promoting the insurance and re-insurance industry in India, protecting policyholders'' interests, licensing insurance companies and intermediaries, and ensuring the orderly growth of the insurance sector.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q065', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 64, 'What is a "premium" in insurance terminology?', 'A premium is the amount of money a policyholder pays, either as a lump sum or in periodic installments, to an insurance company in exchange for coverage against specified risks under an insurance policy.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q066', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 65, 'What is "term insurance," and how does it typically differ from a traditional whole life insurance policy?', 'Term insurance provides life cover for a fixed period (the "term") and pays a death benefit only if the insured dies within that period, with no payout if they survive it, making it generally cheaper. A whole life policy provides coverage for the insured''s entire life and often includes a savings or investment component, making it more expensive.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q067', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 66, 'What is "third-party insurance" in the context of motor insurance, and is it mandatory in India?', 'Third-party insurance covers damages or injuries caused to a third party (not the policyholder or their own vehicle) in an accident involving the insured vehicle. In India, having at least third-party motor insurance is legally mandatory for all vehicle owners under the Motor Vehicles Act.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q068', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 67, 'What does "sum assured" mean in an insurance policy?', 'The sum assured is the guaranteed amount of money that an insurance company agrees to pay to the policyholder or their beneficiaries upon the occurrence of the insured event, such as death, maturity, or a covered loss, as specified in the policy terms.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q069', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 68, 'What is "reinsurance," and why do insurance companies use it?', 'Reinsurance is insurance purchased by an insurance company from another insurer to spread and reduce its own risk exposure on policies it has underwritten, protecting it from very large or catastrophic claims that could otherwise threaten its financial stability.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q070', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 69, 'What is the General Insurance Corporation of India (GIC Re), and what is its role?', 'GIC Re is India''s national reinsurance company, providing reinsurance support to general insurance companies operating in India, helping them manage and spread large risks, and is regulated by IRDAI.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q071', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 70, 'What is the "Atal Pension Yojana (APY)," and who is it primarily targeted at?', 'Atal Pension Yojana is a government-backed pension scheme primarily targeted at workers in the unorganized sector, guaranteeing a fixed monthly pension, ranging from Rs. 1,000 to Rs. 5,000, after the subscriber turns 60, based on the contribution amount and age at which they joined the scheme.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q072', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 71, 'What is the "Pradhan Mantri Suraksha Bima Yojana (PMSBY)," and what does it provide?', 'PMSBY is a government-backed accidental insurance scheme offering coverage for accidental death and disability at a very low annual premium, aimed at providing affordable insurance protection to economically weaker and uninsured sections of the population.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q073', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 72, 'What is the "Pradhan Mantri Jeevan Jyoti Bima Yojana (PMJJBY)," and how does it differ from PMSBY?', 'PMJJBY is a government-backed life insurance scheme providing a death benefit, covering death due to any cause rather than just accidents, at a low annual premium. PMSBY, by contrast, covers only accidental death and disability, making PMJJBY broader in terms of the cause of death covered, though both are affordable mass-insurance schemes.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q074', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 73, 'What is the "Sukanya Samriddhi Yojana," and who is it designed for?', 'Sukanya Samriddhi Yojana is a government savings scheme designed to encourage parents to save for the education and marriage expenses of their girl child, offering an attractive, often higher-than-standard interest rate, and can be opened for a girl child until she turns 10 years old.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q075', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 74, 'What is the "Stand-Up India" scheme intended to promote?', 'Stand-Up India is a government scheme intended to promote entrepreneurship among women and Scheduled Caste/Scheduled Tribe borrowers by facilitating bank loans between Rs. 10 lakh and Rs. 1 crore for setting up new greenfield enterprises in manufacturing, services, or trading sectors.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q076', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 75, 'What is the "Mudra Yojana (PMMY)," and what type of borrowers does it target?', 'The Pradhan Mantri Mudra Yojana provides collateral-free loans up to Rs. 10 lakh to non-corporate, non-farm small and micro enterprises, categorized into three loan tiers, Shishu, Kishor, and Tarun, based on the scale of the business and funding requirement, aimed at promoting entrepreneurship and self-employment.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q077', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 76, 'What is the "National Pension System (NPS)," and who can subscribe to it?', 'The National Pension System is a voluntary, defined-contribution pension scheme open to all Indian citizens, including government and private sector employees, where subscribers regularly contribute during their working years, and the accumulated corpus is used to provide a pension and lump-sum withdrawal after retirement.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q078', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 77, 'What is the purpose of "Direct Benefit Transfer (DBT)" in the context of government welfare schemes?', 'Direct Benefit Transfer is a mechanism to transfer government subsidies and welfare benefits directly into beneficiaries'' bank accounts, reducing leakages, delays, and corruption that were common with earlier physical or intermediary-based distribution systems.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q079', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 78, 'What is the "Sensex," and which stock exchange does it represent?', 'The Sensex (BSE Sensex) is a benchmark stock market index representing the performance of 30 large, financially sound, and actively traded companies listed on the Bombay Stock Exchange (BSE), used as a key indicator of overall market trends.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q080', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 79, 'What is the "Nifty 50," and which stock exchange does it represent?', 'The Nifty 50 is a benchmark stock market index representing the weighted average performance of 50 of the largest and most liquid companies listed on the National Stock Exchange (NSE) of India.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q081', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 80, 'What is an "Initial Public Offering (IPO)"?', 'An IPO is the process through which a privately held company offers its shares to the public for the first time, raising capital from public investors and becoming a publicly listed company on a stock exchange.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q082', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 81, 'What is a "stock exchange," and name India''s two major stock exchanges.', 'A stock exchange is a regulated marketplace where buyers and sellers trade shares of publicly listed companies, along with other securities. India''s two major stock exchanges are the Bombay Stock Exchange (BSE) and the National Stock Exchange (NSE).', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q083', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 82, 'What is a "bull market" and a "bear market"?', 'A bull market refers to a period of sustained rising stock prices and investor optimism. A bear market refers to a period of sustained falling stock prices and investor pessimism, typically defined as a decline of 20% or more from recent highs.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q084', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 83, 'What is a "dividend," in the context of stock market investing?', 'A dividend is a portion of a company''s profits distributed to its shareholders, usually in proportion to the number of shares they hold, as a reward for their investment, though companies are not obligated to pay dividends and may instead reinvest profits into the business.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q085', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 84, 'What is the role of a "depository" like NSDL or CDSL in the Indian stock market?', 'A depository such as NSDL (National Securities Depository Limited) or CDSL (Central Depository Services Limited) holds investors'' securities in electronic, dematerialized form, facilitating easy, paperless transfer of shares during buying and selling, eliminating the risks associated with physical share certificates.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q086', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 85, 'What is "market capitalization" of a company?', 'Market capitalization is the total market value of a company''s outstanding shares, calculated by multiplying the current share price by the total number of outstanding shares, used to gauge the overall size of a publicly listed company.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q087', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 86, 'What is "two-factor authentication (2FA)" in the context of digital banking security?', 'Two-factor authentication requires a user to provide two different forms of verification before completing a transaction or logging in, typically something they know like a password or PIN combined with something they have like an OTP sent to their registered mobile number, adding an extra layer of security beyond a single password.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q088', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 87, 'What is "phishing," and how does it commonly target bank customers?', 'Phishing is a fraudulent technique where scammers impersonate a legitimate institution such as a bank through fake emails, messages, or websites to trick victims into revealing sensitive information like passwords, OTPs, or card details, which are then used to commit financial fraud.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q089', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 88, 'What is a "Unified Payments Interface (UPI) PIN," and what is it used for?', 'A UPI PIN is a secret numeric code set by a user to authorize and authenticate UPI transactions, required every time money is sent from the user''s bank account via a UPI app, serving as the final security check before a payment is completed.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q090', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 89, 'What is "tokenization" in the context of digital card payments?', 'Tokenization replaces sensitive card details, like the card number, with a unique, randomly generated "token" for use in digital transactions, so that merchants and payment systems never store or transmit the actual card number, reducing the risk of card data theft during a data breach.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q091', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 90, 'What does "CVV" stand for on a debit or credit card, and what is its purpose?', 'CVV stands for Card Verification Value, a 3-digit security code usually on the back of the card, used as an additional authentication step for card-not-present transactions like online purchases, helping verify that the person making the transaction physically possesses the card.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q092', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 91, 'What is "vishing," and how does it differ from phishing?', 'Vishing, or voice phishing, is a fraud technique conducted over phone calls, where scammers impersonate bank representatives or officials to trick victims into revealing sensitive financial information verbally. Phishing typically relies on fraudulent emails, messages, or websites rather than live voice calls.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q093', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 92, 'What is the difference between a "secured loan" and an "unsecured loan"?', 'A secured loan requires the borrower to pledge collateral, such as property, gold, or a fixed deposit, that the lender can seize if the borrower defaults, typically allowing for lower interest rates. An unsecured loan requires no collateral and is granted based on the borrower''s creditworthiness alone, usually carrying a higher interest rate due to the greater risk to the lender.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q094', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 93, 'What is a "cash credit" facility offered by banks to businesses?', 'A cash credit facility allows a business to withdraw funds up to a sanctioned limit, typically against the security of inventory or receivables, for its working capital needs, with interest charged only on the amount actually utilized rather than the entire sanctioned limit.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q095', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 94, 'What is an "overdraft facility," and how does it work?', 'An overdraft facility allows an account holder to withdraw more money than is currently available in their account, up to a pre-approved limit, with interest charged only on the overdrawn amount for the period it remains outstanding.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q096', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 95, 'What is a "term loan," and how does it typically differ from a cash credit facility?', 'A term loan is a loan disbursed as a lump sum for a fixed tenure, to be repaid through scheduled installments (EMIs) covering both principal and interest, often used for specific purposes like buying equipment or property. A cash credit facility, by contrast, is a revolving line of credit for ongoing working capital needs, not a one-time lump-sum disbursement.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q097', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 96, 'What is a "gold loan," and what is typically used as its collateral?', 'A gold loan is a secured loan where the borrower pledges gold ornaments or coins as collateral with the lender, in exchange for a loan amount typically calculated as a percentage of the pledged gold''s market value, offering quick disbursal due to minimal documentation requirements.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q098', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 97, 'What does "EMI" stand for, and what does it represent?', 'EMI stands for Equated Monthly Installment, a fixed payment amount made by a borrower to a lender each month, comprising both a portion of the principal loan amount and the interest due, structured so that the loan is fully repaid by the end of its tenure.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q099', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 98, 'What is a "loan against property (LAP)"?', 'A loan against property is a secured loan where the borrower pledges an owned residential or commercial property as collateral to the lender, in exchange for funds that can be used for various personal or business purposes, typically at a lower interest rate than unsecured loans due to the collateral backing.', '2026-11-12T14:55:35.002Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q100', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 99, 'What is a "Priority Sector Lending Certificate (PSLC)"?', 'A PSLC is a tradable certificate that allows banks which have exceeded their priority sector lending targets to sell their surplus achievement to banks that have fallen short, enabling the banking system as a whole to meet priority sector lending targets more efficiently without forcing every individual bank to directly lend to those sectors.', '2026-11-12T14:55:35.002Z');
